#!/usr/bin/env node

/**
 * Credential validation script for the test environment
 * This script checks:
 * 1. Database connectivity via DATABASE_URL
 * 2. Various API key endpoints
 *
 * NOTE: API key validation checks are limited by API policies.
 * Many APIs block excessive validation requests.
 */

const { URL } = require('url');
const https = require('https');

// Try to load .env.test explicitly
try {
  // Node 20.6+ has built-in dotenv
  if (require.main === module && !process.env.DATABASE_URL) {
    try {
      require('dotenv').config({ path: __dirname + '/.env.test' });
    } catch (e) {
      // dotenv not loaded, will use process.env directly
    }
  }

  // Fallback: manually load .env.test if not set
  if (!process.env.DATABASE_URL && !require.main?.filename) {
    const fs = require('fs');
    const path = __dirname + '/.env.test';
    if (fs.existsSync(path)) {
      const envContent = fs.readFileSync(path, 'utf8');
      const lines = envContent.split('\n');
      for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
          const [key, ...val] = trimmed.split('=');
          process.env[key.trim()] = val.join('=').trim();
        }
      }
    }
  }
} catch (err) {
  // Ignore errors
}

// Configuration from environment
const config = {
  databaseUrl: process.env.DATABASE_URL,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN
};

// Report object
const report = {
  database: { checked: false, valid: false, error: null },
