async function testDatabase() {
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    console.log('❌ DATABASE_URL not set in environment');
    return false;
  }

  try {
    // Parse the URL manually
    const match = dbUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
    if (!match) {
      console.log('❌ Invalid DATABASE_URL format');
      return false;
    }

    const [, username, password, host, port, database] = match;
    console.log(`📋 Connected to: ${host}:${port}/${database}`);
    console.log(`👤 User: ${username}`);

    const pool = new Pool({
      connectionString: dbUrl,
      // Don't display full errors in test
      ssl: { rejectUnauthorized: false },
      idleTimeoutMillis: 5000,
      connectionTimeoutMillis: 10000,
    });

    const start = Date.now();
    const client = await pool.connect();
    const queryStart = Date.now();

    // Test query - should be a lightweight query
    const result = await client.query('SELECT version()');
    const queryTime = Date.now() - queryStart;

    client.release();
    await pool.end();

    const totalTime = Date.now() - start;

    console.log(`✅ Database connection successful`);
    console.log(`⏱️  Query time: ${queryTime}ms`);
    console.log(`⏱️  Total time: ${totalTime}ms`);

    // Display first few lines of version for context
    const version = result.rows[0].version;
    console.log(`\n🛠️  Postgres version: ${version.split(',')[0]}`);

    return true;
  } catch (error) {
    console.log(`❌ Database connection failed!`);
    console.log(`   Error: ${error.message}`);
    if (error.code) {
      console.log(`   Error code: ${error.code}`);
    }
    if (error.detached) {
      console.log(`   ⚠️  Pool was closed before connection completed`);
    }
    return false;
  }
}

// Test 2: API Key Validation
console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
console.log('TEST 2: API Key Validation');
