        passed++;
        results[endpoint.key] = { valid: true, status: response.statusCode };
      } else if (response.statusCode === 404) {
        console.log(`   ⚠️  API endpoint not found - may have changed`);
        failed++;
        results[endpoint.key] = { valid: false, status: 404 };
      } else {
