        console.log(`   ℹ️  API responded but status unclear`);
        results[endpoint.key] = { valid: false, status: response.statusCode };
        failed++;
      }
    } catch (error) {
      const duration = Date.now() - startTime;
      console.log(`   ❌ Request failed after ${duration}ms`);
      console.log(`      Error: ${error.message}`);

      if (error.code === 'ECONNREFUSED') {
        console.log(`      💡 The service/host might be unavailable`);
      } else if (error.code === 'ETIMEDOUT') {
