      console.log(`   💡 Connection timed out - host not responding`);
    } else if (error.code === 'ENOTFOUND') {
      console.log(`   💡 Database host not found in DNS. Check hostname: ${error.host}`);
    } else if (error.code === 'ECONNRESET') {
      console.log(`   💡 Connection was reset by the database`);
    } else if (error.code === 'ECONNABORTED') {
      console.log(`   💡 Connection was aborted during negotiation`);
    }
    return false;
  }
}

