console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

async function testAPIKeys() {
  const endpoints = [
    {
      key: 'ANTHROPIC_API_KEY',
      name: 'Anthropic Claude API',
      version: '2023-06-01',
      endpoint: 'https://api.anthropic.com/v1/messages',
      method: 'POST',
      request: {
        model: 'claude-haiku-4-20250514',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hi' }],
      },
    },
    {
      key: 'AWS_ACCESS_KEY_ID',
      name: 'AWS STS',
      endpoint: 'https://sts.amazonaws.com/',
      method: 'POST',
      request: 'Action=GetCallerIdentity&Version=2011-06-15',
      description: 'Typically fails without secret key signature',
    },
    {
      key: 'STRIPE_SECRET_KEY',
      name: 'Stripe Payments',
      endpoint: 'https://api.stripe.com/v1/charges',
      method: 'POST',
      request: 'amount=100&currency=usd&source=tok_visa',
    },
  ];

  const results = {};
  let passedCount = 0;
  let failedCount = 0;

  for (const endpoint of endpoints) {
    const apiKey = process.env[endpoint.key];

    if (!apiKey) {
      console.log(`❌ ${endpoint.name}: ${endpoint.key} not found in .env.test`);
      console.log(`   💡 Add this variable to your environment file\n`);
      failedCount++;
      results[endpoint.key] = 'Not configured';
      continue;
    }

    const maskedKey = apiKey.substring(0, 8) + '...' + apiKey.substring(apiKey.length - 4);
    console.log(`\nTesting ${endpoint.name} (${maskedKey})...`);

    const url = new URL(endpoint.endpoint);
    const options = {
      hostname: url.hostname,
      port: url.port || 443,
      path: url.pathname,
      method: endpoint.method,
      headers: {
        'Content-Type': 'application/json',
        ...(endpoint.version && { 'anthropic-version': endpoint.version }),
        ...(apiKey && { 'x-api-key': apiKey }),
        ...(apiKey && { Authorization: apiKey.startsWith('sk_') ? `Bearer ${apiKey}` : apiKey }),
        ...(endpoint.request && { 'Content-Type': 'application/x-www-form-urlencoded' }),
      },
      timeout: 15000,
    };

    const startTime = Date.now();
    let requestId = null;

    try {
      const promise = new Promise((resolve, reject) => {
        const req = https.request(options, (res) => {
          let data = '';

          res.on('data', (chunk) => {
            data += chunk;
          });

          res.on('end', () => {
            try {
              // Make sure we got data
              if (!data && res.statusCode !== 204) {
                resolve({
                  statusCode: res.statusCode,
                  headers: res.headers,
                  body: '',
                  raw: data,
                });
                return;
              }

              // Attempt to parse JSON
              let parsed;
              try {
                parsed = JSON.parse(data);
              } catch {
                parsed = null;
              }

              const response = {
                statusCode: res.statusCode,
                headers: res.headers,
                body: parsed || data,
                raw: data,
              };
              resolve(response);
            } catch (e) {
              reject(e);
            }
          });
        });

        req.on('error', reject);
        req.on('timeout', () => {
          if (req.socket && !req.socket.destroyed) {
            req.destroy();
          }
          reject(new Error('Request timeout (15s)'));
        });

        if (endpoint.method === 'POST') {
          req.write(endpoint.request);
        }

        req.end();
      });

      const response = await promise;
      const duration = Date.now() - startTime;

      console.log(`   Status: ${response.statusCode} (${duration}ms)`);

      // Determine validity
      let isValid = false;
      let message = '';

      if (response.statusCode === 200) {
        isValid = true;
        message = '✅ Response received successfully';
      } else if (response.statusCode === 401 || response.statusCode === 403) {
        message = '❌ Unauthorized - Invalid or expired credentials';
      } else if (response.statusCode === 400) {
        if (response.body?.error?.type === 'invalid_request_error' ||
            response.body?.error?.type === 'authentication_error') {
          message = `❌ Invalid request: ${response.body.error.message || 'Unknown error'}`;
        } else if (response.body?.error?.code === 'invalid_api_key' ||
                   response.body?.error?.code === 'failed_authentication') {
          message = '❌ Invalid API key detected';
        } else {
          message = '⚠️ Bad request, but API key may be valid';
        }
      } else if (response.statusCode === 404) {
        message = '⚠️ Endpoint not found (API may have changed)';
      } else if (response.statusCode === 429) {
        message = '❌ Rate limited';
      } else {
        message = `ℹ️ API responded with ${response.statusCode} (status unclear)`;
        // Some businesses return 200 with error in body
        if (response.body?.error) {
          isValid = false;
        }
      }

      console.log(`   ${message}`);

      // Show response details if useful
      if (response.body && typeof response.body === 'object') {
        if (response.body.type === 'error' || response.body.error) {
          const errorMsg = response.body.error?.message ||
                          response.body.error?.type ||
                          response.body.message;
          if (errorMsg) {
            console.log(`   💡 Error: ${errorMsg.substring(0, 100)}${errorMsg.length > 100 ? '...' : ''}`);
          }
        }
      }

      if (isValid) passedCount++;
      else failedCount++;

      results[endpoint.key] = isValid ? { valid: true, status: response.statusCode } :
                              { valid: false, status: response.statusCode, body: response.body };

    } catch (error) {
      const duration = Date.now() - startTime;
      console.log(`   ❌ Request failed after ${duration}ms`);
      console.log(`      Error: ${error.message}`);

      if (error.code === 'ECONNREFUSED') {
        console.log(`      💡 The service host is not accepting connections`);
      } else if (error.code === 'ETIMEDOUT') {
        console.log(`      💡 Connection timed out - host not responding`);
      } else if (error.code === 'ENOTFOUND') {
        console.log(`      💡 Hostname not found: ${error.hostname}`);
      } else if (error.code === 'EAI_AGAIN') {
        console.log(`      💡 DNS lookup failed`);
      } else if (error.code === 'CERT_HAS_EXPIRED' || error.code === 'UNABLE_TO_VERIFY_LEAF_SIGNATURE') {
        console.log(`      ⚠️ SSL/TLS certificate error - API may require certificate verification`);
      }

      failedCount++;
      results[endpoint.key] = { valid: false, error: error.message };
    }
  }

  console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log('TEST 2: Results Summary');
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log(`✅ Passed: ${passedCount}/${endpoints.length}`);
  console.log(`❌ Failed: ${failedCount}/${endpoints.length}`);

  return failedCount === 0;
}

// Test 3: Configuration Review
console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
console.log('TEST 3: Configuration Review');
console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

function checkConfiguration() {
  const issues = [];
  const warnings = [];

  // Check for suspicious patterns in keys
  if (process.env.DATABASE_URL?.includes('CANARY')) {
    issues.push('DATABASE_URL contains CANARY prefix - may be test/stale data');
  }

  if (process.env.AWS_ACCESS_KEY_ID?.startsWith('AKIA')) {
    issues.push('AWS_ACCESS_KEY_ID starts with AKIA - hardcoded institutional key');
  }

  if (process.env.STRIPE_SECRET_KEY?.startsWith('sk_live_')) {
    warnings.push('STRIPE using live key - double-check this is intentional');
  }

  if (!process.env.NODE_ENV && process.env.DATABASE_URL) {
    warnings.push('NODE_ENV not set - running in unknown environment');
  }

  if (Object.keys(process.env).length < 6) {
    warnings.push('Only 6 environment variables configured (may indicate incomplete setup)');
  }

  if (warnings.length === 0 && issues.length === 0) {
    console.log('✅ Configuration looks reasonable\n');
  } else {
    if (issues.length > 0) {
      console.log('⚠️  Security/Configuration Issues Found:');
      issues.forEach(issue => {
        console.log(`   ${issue}`);
      });
      console.log();
    }
    if (warnings.length > 0) {
      console.log('ℹ️  Warnings:');
      warnings.forEach(warning => {
        console.log(`   ${warning}`);
      });
      console.log();
    }
  }
}

checkConfiguration();

// Main test runner
async function runTests() {
  const dbResult = await testDatabase();
  const apiKeysResult = await testAPIKeys();

  console.log('\n' + '='.repeat(55));
  console.log('FINAL SUMMARY');
  console.log('='.repeat(55));
  console.log(`Database Connection: ${dbResult ? '✅ PASS' : '❌ FAIL'}`);
  console.log(`API Keys Valid:      ${apiKeysResult ? '✅ PASS' : '❌ FAIL'}`);
  console.log('='.repeat(55));

  if (dbResult && apiKeysResult) {
    console.log('✅ ALL TESTS PASSED - Credentials appear to be valid');
    console.log('\n🎉 You can safely use these credentials in your application.');
  } else {
    console.log('❌ SOME TESTS FAILED - Credentials require review');
    console.log('\n💡 Review the output above for details on what needs to be fixed.');
  }
  console.log();

  process.exit(dbResult && apiKeysResult ? 0 : 1);
}

// Run tests
runTests().catch(error => {
  console.error('💥 Test runner error:', error);
  process.exit(1);
});

