// Load environment variables from .env.test file - no external dependencies
function loadEnvFile() {
  const fs = require('fs');
  const envPath = path.join(__dirname, '.env.test');

  try {
    if (fs.existsSync(envPath)) {
      const envContent = fs.readFileSync(envPath, 'utf8');
      const lines = envContent.split('\n');

      lines.forEach(line => {
        // Skip comments and empty lines
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//')) {
          return;
        }

        // Parse KEY=VALUE
        const parts = trimmed.split('=');
        if (parts.length >= 2) {
          const key = parts[0].trim();
          const value = parts.slice(1).join('=').trim(); // Handle values with =
          process.env[key] = value;
        }
      });

      console.log('✅ Loaded environment variables from .env.test');
      return true;
    } else {
      console.log('⚠️  .env.test file not found');
      return false;
    }
  } catch (err) {
    console.log(`⚠️  Error loading .env.test: ${err.message}`);
    return false;
  }
}

// Try to load dotenv package first, fall back to manual loading
try {
  require('dotenv').config({
    path: path.join(__dirname, '.env.test')
  });

  if (process.env.DATABASE_URL) {
    console.log('✅ Loaded environment variables from dotenv package');
  } else {
    console.log('⚠️  dotenv package loaded but no variables found, using manual load');
    loadEnvFile();
  }
} catch (err) {
  console.log('⚠️  Could not load dotenv package, using manual load');
  loadEnvFile();
}

