// Secure Express application with proper error handling and input validation
// Security best practices implementation

const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');

// Security: Rate limiting to prevent brute force and abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});

// Apply rate limiting globally (except for /health)
app.use((req, res, next) => {
  if (req.path !== '/health') {
    limiter(req, res, next);
  } else {
    next();
  }
});

// Security: Body size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security: Trust proxy settings (should be configured based on your deployment)
// app.set('trust proxy', 1);

// Security: Secure headers middleware
app.use((req, res, next) => {
  // HSTS (HTTP Strict Transport Security)
  res.setHeader('Strict-Transport-Security', 'max-age=63072000; includeSubDomains; preload');

  // XSS Protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Content Security Policy
  res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'");

  // Referrer Policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // X-Frame-Options
  res.setHeader('X-Frame-Options', 'DENY');

  // X-Content-Type-Options
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Permissions-Policy
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');

  next();
});

// Security: Input validation middleware
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validators = {
  // Validate id parameter
  validateId: (req, res, next) => {
    const { id } = req.params;
    if (!id || isNaN(Number(id)) || Number(id) < 0) {
      return res.status(400).json({ error: 'Invalid ID parameter' });
    }
    next();
  },

  // Validate email in request body
  validateEmailInput: (req, res, next) => {
    const { email } = req.body;

    if (email && !validateEmail(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    if (email && email.length > 254) {
      return res.status(400).json({ error: 'Email exceeds maximum length' });
    }

    next();
  }
};

// Health endpoint - publicly accessible, rate limited to be safe
app.get('/health', (req, res) => {
  res.set('Cache-Control', 'no-cache');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with input validation
app.get('/users', validators.validateId, (req, res) => {
  try {
    const idParam = req.params.id;
    const userId = idParam ? Number(idParam) : null;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    let result;

    if (userId && userId > 0 && userId <= users.length) {
      // In a real app, check if user exists before returning
      result = users.find(u => u.id === userId);
    } else {
      result = users;
    }

    res.json({
      success: true,
      data: result
    });
  } catch (error) {
    console.error('Error in /users:', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Create user endpoint with proper validation
app.post('/users', validators.validateEmailInput, (req, res) => {
  try {
    const { name, email } = req.body;

    // Explicit input validation
    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return res.status(400).json({ error: 'Name is required and must be a non-empty string' });
    }

    if (email && !validateEmail(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    // Validate name length
    if (name.length > 100) {
      return res.status(400).json({ error: 'Name exceeds maximum length of 100 characters' });
    }

    const newUser = {
      id: users.length + 1,
      name: name.trim(),
      email: email ? email.toLowerCase().trim() : null
    };

    res.status(201).json({
      success: true,
      data: newUser
    });
  } catch (error) {
    console.error('Error in /users (POST):', error);
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Error handling middleware - must be placed after all routes
app.use((err, req, res, next) => {
  // Log error for security monitoring
  console.error('Unhandled error:', {
    error: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Safety: Ensure we never expose sensitive error details
  const errorMessage = process.env.NODE_ENV === 'development' ? err.message : 'An unexpected error occurred';
  res.status(err.status || 500).json({
    error: errorMessage,
    timestamp: new Date().toISOString()
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
});

// Validate environment variables
if (!process.env.PORT) {
  console.warn('Warning: PORT environment variable not set. Using default port 3000');
}

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

