app.use((err, req, res, next) => {
  // Log error for security monitoring
  console.error('Unhandled error:', {
    error: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Safety: Ensure we never expose sensitive error details
  const errorMessage = process.env.NODE_ENV === 'development' ? err.message : 'An unexpected error occurred';
  res.status(err.status || 500).json({
    error: errorMessage,
    timestamp: new Date().toISOString()
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
});

