  missingCritical.push('DATABASE_URL');
}
if (config.env === 'production' && !config.database.url) {
  missingCritical.push('DATABASE_URL');
}
if (config.aws.accessKeyId && process.env.NODE_ENV !== 'development') {
  if (!config.aws.secretAccessKey) {
    missingCritical.push('AWS_SECRET_ACCESS_KEY');
  }
}

if (missingCritical.length > 0) {
  console.error(`⚠️  Warning: Missing critical environment variables in production: ${missingCritical.join(', ')}`);
  console.error('Set NODE_ENV to development for testing without full configuration.');
}

// Validate that PORT is a valid number
if (config.port <= 0 || config.port > 65535) {
  console.error('⚠️  Invalid PORT value. Must be between 1 and 65535. Using default 3000.');
  config.port = 3000;
}

app.listen(config.port, () => {
  console.log(`✅ Secure server running on port ${config.port}`);
  console.log(`📝 Environment: ${config.env}`);
  console.log(`🔗 Database connected: ${config.database.url ? 'yes' : 'no (not configured)'}`);
});

module.exports = app;

