// Secure Express application with proper error handling and input validation
// Security best practices implementation

const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');

// Middleware to validate critical environment variables
const validateEnv = () => {
  const criticalVars = {
    database: ['DATABASE_URL'],
    security: ['JWT_SECRET', 'SESSION_SECRET'],
    aws: ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY']
  };

  const missing = [];
  for (const section of Object.entries(criticalVars)) {
    for (const varName of section[1]) {
      if (process.env[varName] === undefined) {
        missing.push(`${varName} (${section[0]})`);
      }
    }
  }

  if (missing.length > 0) {
    console.warn('⚠️  Missing critical environment variables:', missing.join(', '));
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Critical environment variables missing. Is the app running in development mode?');
    }
  }
};

// Security: Rate limiting to prevent brute force and abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});

// Apply rate limiting globally (except for /health)
app.use((req, res, next) => {
  if (req.path !== '/health') {
    limiter(req, res, next);
  } else {
    next();
  }
});

// Security: Body size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security: Trust proxy settings (should be configured based on your deployment)
// app.set('trust proxy', 1);

// Security: Secure headers middleware
app.use((req, res, next) => {
  // HSTS (HTTP Strict Transport Security)
  res.setHeader('Strict-Transport-Security', 'max-age=63072000; includeSubDomains; preload');

  // XSS Protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Content Security Policy
  res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'");

  // Referrer Policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // X-Frame-Options
  res.setHeader('X-Frame-Options', 'DENY');

  // X-Content-Type-Options
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Permissions-Policy
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');

  next();
});

// Security: Input validation middleware
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validators = {
  // Validate id parameter
  validateId: (req, res, next) => {
    const { id } = req.params;
    if (!id || isNaN(Number(id)) || Number(id) < 0) {
      return res.status(400).json({ error: 'Invalid ID parameter' });
    }
    next();
  },

  // Validate email in request body
  validateEmailInput: (req, res, next) => {
    const { email } = req.body;

    if (email && !validateEmail(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    if (email && email.length > 254) {
      return res.status(400).json({ error: 'Email exceeds maximum length' });
    }

    next();
  }
