#!/usr/bin/env node

/**
 * Credential Validation Test Script
 * Tests database connectivity and API key validity
 */

const https = require('https');
const http = require('http');
const axios = require('axios');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m'
};

const log = {
  success: (msg) => console.log(`${colors.green}✓${colors.reset} ${msg}`),
  error: (msg) => console.log(`${colors.red}✗${colors.reset} ${msg}`),
  warning: (msg) => console.log(`${colors.yellow}⚠${colors.reset} ${msg}`),
  info: (msg) => console.log(`${colors.blue}ℹ${colors.reset} ${msg}`),
  header: (msg) => console.log(`\n${colors.cyan}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${colors.reset}`),
  subheader: (msg) => console.log(`\n${colors.cyan}━━━━━━━━${colors.reset} ${msg} ${colors.cyan}━━━━━━━━${colors.reset}`)
};

async function runTests() {
  log.header('Credential Validation Test Suite');
  log.info('Testing at:', new Date().toISOString());

  // Load environment variables
  const envVars = {
    databaseUrl: process.env.DATABASE_URL,
    amazonKeyId: process.env.AWS_ACCESS_KEY_ID,
    amazonSecret: process.env.AWS_SECRET_ACCESS_KEY,
    anthropicKey: process.env.ANTHROPIC_API_KEY,
    stripeKey: process.env.STRIPE_SECRET_KEY,
    logfireToken: process.env.LOGFIRE_TOKEN
  };

  log.info('Environment Variables Loaded:', Object.keys(envVars).filter(k => envVars[k]).length, '/ 6');

  let totalTests = 0;
  let passedTests = 0;

  // Test 1: Database Connection
  log.subheader('Test 1: Database Connectivity');
  totalTests++;

  if (!envVars.databaseUrl) {
    log.warning('DATABASE_URL not set - skipping database test');
  } else {
    await testDatabaseConnection(envVars.databaseUrl)
      .then(() => {
        passedTests++;
        log.success('Database connection successful');
      })
      .catch((error) => {
        if (error.message.includes('empty database')) {
          log.warning('Database exists but is empty (acceptable)');
          passedTests++;
        } else {
          log.error(`Database connection failed: ${error.message}`);
        }
      });
  }

  // Test 2: AWS Credentials
  log.subheader('Test 2: AWS Credentials');
  totalTests++;

  if (!envVars.amazonKeyId || !envVars.amazonSecret) {
    log.warning('AWS credentials not both set - skipping AWS test');
  } else {
    await testAWSConnection(envVars.amazonKeyId, envVars.amazonSecret)
      .then(() => {
        passedTests++;
        log.success('AWS credentials valid');
      })
      .catch((error) => {
        log.error(`AWS credentials invalid: ${error.message}`);
      });
  }

  // Test 3: Anthropic API Key
  log.subheader('Test 3: Anthropic API Key');
  totalTests++;

  if (!envVars.anthropicKey) {
    log.warning('ANTHROPIC_API_KEY not set - skipping test');
  } else {
    await testAnthropicAPI(envVars.anthropicKey)
      .then(() => {
        passedTests++;
        log.success('Anthropic API key valid');
      })
      .catch((error) => {
        log.error(`Anthropic API invalid: ${error.message}`);
      });
  }

  // Test 4: Stripe API Key
  log.subheader('Test 4: Stripe API Key');
  totalTests++;

  if (!envVars.stripeKey) {
    log.warning('STRIPE_SECRET_KEY not set - skipping test');
  } else {
    await testStripeAPI(envVars.stripeKey)
      .then(() => {
        passedTests++;
        log.success('Stripe API key valid');
      })
      .catch((error) => {
