async function testDatabaseConnection(url) {
  try {
    // Parse database URL and connect
    const pg = require('pg');
    const parsed = url.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);

    if (!parsed) {
      throw new Error('Invalid DATABASE_URL format');
    }

    const [_, username, password, host, port, database] = parsed;

    // Create connection pool
    const pool = new pg.Pool({
      user: username,
      host: host,
      port: parseInt(port, 10),
      database: database,
      password: password
    });

    // Test connection
    const client = await pool.connect();
    await client.query('SELECT version()');
    client.release();

    await pool.end();

    return true;
  } catch (error) {
    // Check for specific PostgreSQL error codes
    if (error.code === '3D000' || error.message.includes('does not exist')) {
      throw new Error('Database does not exist');
    } else if (error.code === '8392' || error.code === '28P01') {
      throw new Error('Authentication failed - invalid credentials');
    } else if (error.code === 'ECONNREFUSED' || error.code === 'ETIMEDOUT') {
      throw new Error(`Connection refused or timeout: ${error.message}`);
    }
    throw error;
  }
}

