  prepareAWS4Auth: (accessKeyId, secretAccessKey, host, region, service, algorithm) => {
    const date = new Date();
    const amzDate = date.toISOString().replace(/[:-]|\.\d+/g, '');
    const dateStamp = date.toISOString().slice(0, 10);

    const credentialScope = `${dateStamp}/${region}/${service}/aws4_request`;

    // Create signing key
    const kSecret = `AWS4${secretAccessKey}`;
    const kDate = AWS.hmac(kSecret, dateStamp, 'AWS4-HMAC-SHA256');
    const kRegion = AWS.hmac(kDate, region, 'AWS4-HMAC-SHA256');
    const kService = AWS.hmac(kRegion, service, 'AWS4-HMAC-SHA256');
    const kSigning = AWS.hmac(kService, 'aws4_request', 'AWS4-HMAC-SHA256');

    // Create canonical request
    const method = 'GET';
    const canonicalUri = '/';
    const canonicalQueryString = 'Action=GetCallerIdentity&Version=2011-06-15';
