  header: (msg) => console.log(`\n${colors.cyan}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${colors.reset}`),
  subheader: (msg) => console.log(`\n${colors.cyan}━━━━━━━━${colors.reset} ${msg} ${colors.cyan}━━━━━━━━${colors.reset}`)
};

async function runTests() {
  log.header('Credential Validation Test Suite');
  log.info('Testing at:', new Date().toISOString());

