  };

  const envCount = Object.keys(envVars).filter(k => envVars[k]).length;
  log.info(`Environment Variables Loaded: ${envCount} / 6`);

  let totalTests = 0;
  let passedTests = 0;

  // Test 1: Database Connection
  log.subheader('Test 1: Database Connectivity');
  totalTests++;

  if (!envVars.databaseUrl) {
    log.warning('DATABASE_URL not set - skipping database test');
  } else {
    await testDatabaseConnection(envVars.databaseUrl)
      .then(() => {
        passedTests++;
        log.success('Database connection successful');
      })
      .catch((error) => {
        if (error.message.includes('does not exist') || error.message.includes('empty database')) {
