          passedTests++;
        } else if (error.message.includes('authentication failed') || error.message.includes('28P01')) {
          log.error(`Database login failed: invalid credentials`);
        } else if (error.message.includes('Connection refused') || error.message.includes('ETIMEDOUT')) {
          log.error(`Database connection failed: ${error.message}`);
