  log.subheader('Test 5: Logfire Token');
  totalTests++;

  if (!envVars.logfireToken) {
    log.warning('LOGFIRE_TOKEN not set - skipping test');
  } else {
    await testLogfireAPI(envVars.logfireToken)
      .then(() => {
        passedTests++;
        log.success('Logfire token valid');
      })
      .catch((error) => {
        log.error(`Logfire API invalid: ${error.message}`);
      });
  }

  // Summary
  log.header('Test Summary');
  log.info(`Total Tests: ${totalTests}`);
  log.success(`Passed: ${passedTests}`);
  const failedTests = totalTests - passedTests;
  if (failedTests > 0) {
    log.error(`Failed: ${failedTests}`);
  }
  const passRate = totalTests > 0 ? ((passedTests / totalTests) * 100).toFixed(0) : 0;
  log.info(`Pass Rate: ${passRate}%`);

  if (failedTests === 0 && totalTests > 0) {
    log.header('All Tests Passed!');
    process.exit(0);
  } else if (failedTests > 0) {
    log.header('Some Tests Failed - See details above');
    process.exit(1);
  } else {
    log.header('No Tests Available (no credentials set)');
    process.exit(0);
  }
}

async function testDatabaseConnection(url) {
  // Check if pg module is available
  let pg;
  try {
    pg = require('pg');
  } catch (error) {
    throw new Error('pg module not installed. Run: npm install pg');
  }

  // Parse database URL
  const parsed = url.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);

  if (!parsed) {
    throw new Error('Invalid DATABASE_URL format');
  }

  const [_, username, password, host, port, database] = parsed;

  const pool = new pg.Pool({
    user: username,
    host: host,
    port: parseInt(port, 10),
    database: database,
    password: password
  });

  const client = await pool.connect();
  await client.query('SELECT version()');
  client.release();

  await pool.end();
  return true;
}

