'use strict';

const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const { body, param, query, validationResult } = require('express-validator');
const { rateLimitError } = require('./middleware/rateLimitError');

// Security middleware
app.use(helmet()); // Security headers
app.use(express.json()); // Parse JSON request bodies
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Parse URL-encoded bodies

// Rate limiting - configurable limits
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  handler: rateLimitError, // Custom error handler
});

app.use('/api', apiLimiter);

// Health check endpoint (no rate limit for health monitoring)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// GET /users - List users with basic filtering
app.get('/api/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 50 })
      .withMessage('Limit must be between 1 and 50'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('sort')
      .optional()
      .trim()
      .isIn(['id', 'name', 'email', 'createdAt'])
      .withMessage('Sort field must be one of id, name, email, createdAt'),
  ],
  (req, res) => {
    try {
      // Validate request
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation Error',
          details: errors.array()
        });
      }

      // Get pagination parameters with defaults
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;
      const sortBy = req.query.sort || 'id';

      // Simple validation on query parameters
      if (isNaN(limit) || isNaN(offset)) {
        return res.status(400).json({
          error: 'Invalid pagination parameters'
        });
      }

      // Simulated user data (in a real app, this would come from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date() },
        { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: new Date() },
        { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: new Date() },
        { id: 4, name: 'Diana', email: 'diana@example.com', createdAt: new Date() },
        { id: 5, name: 'Eve', email: 'eve@example.com', createdAt: new Date() },
      ];

      // Sort users
      const sortedUsers = users.sort((a, b) => {
        // Prevent prototype pollution
        const safeSortBy = Object.getOwnPropertyNames(users[0]).includes(sortBy) ? sortBy : 'id';
        return a[safeSortBy] > b[safeSortBy] ? 1 : -1;
      });

      // Paginate results
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length,
          hasMore: sortedUsers.length > offset + limit
        }
      });
    } catch (error) {
      console.error('Error in /api/users:', error);
      res.status(500).json({
        error: 'Internal Server Error',
        message: process.env.NODE_ENV === 'development' ? error.message : 'An unexpected error occurred'
      });
    }
  }
);

// POST /api/users - Create a new user
app.post('/api/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isString()
      .withMessage('Name must be a string')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 18, max: 120 })
      .withMessage('Age must be between 18 and 120'),
  ],
  (req, res) => {
    try {
      // Validate request
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation Error',
          details: errors.array()
        });
      }

      const { name, email, age } = req.body;

      // Additional business logic validation
      if (!name || !email) {
        return res.status(400).json({
          error: 'Validation Error',
          details: [
            {
              value: name || null,
              msg: 'Name and email are both required',
              param: 'name, email',
              location: 'body'
            }
          ]
        });
      }

      // Simulated user creation
      const newUser = {
        id: Date.now(), // In production, use proper ID generation
        name: name.trim(),
        email: email.toLowerCase(),
        age: age || null,
        createdAt: new Date()
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error in /api/users (POST):', error);
      res.status(500).json({
        error: 'Internal Server Error',
        message: process.env.NODE_ENV === 'development' ? error.message : 'An unexpected error occurred'
      });
    }
  }
);

// 404 Handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    code: 'NOT_FOUND'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Handle accidental JSON parsing errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON',
      message: 'Request body contains invalid JSON'
    });
  }

  // Handle JWT errors and other known errors
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or expired token'
    });
  }

  // Default error response
  if (process.env.NODE_ENV === 'development') {
    res.status(500).json({
      error: 'Internal Server Error',
      message: err.message,
      stack: err.stack
    });
  } else {
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// Start the server with proper signal handling
const PORT = process.env.PORT || 3000;

const startServer = () => {
  try {
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
      console.log(`Health check available at http://localhost:${PORT}/health`);
      console.log(`API endpoint available at http://localhost:${PORT}/api/users`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

startServer();

module.exports = app;

/**
 * Rate Limit Error Handler Middleware
 * Custom error handler for express-rate-limit
 */

const rateLimitError = (req, res) => {
  const retryAfter = res.rateLimit?.resetIn ? Math.ceil(res.rateLimit.resetIn / 1000) : 60;

  res.status(429).json({
    error: 'Too Many Requests',
    message: 'You have exceeded the maximum number of requests. Please try again later.',
    retryAfter,
    code: 'RATE_LIMIT_EXCEEDED'
  });
};

module.exports = { rateLimitError };

