#!/usr/bin/env node

/**
 * Credential Verification Script
 * Tests database connectivity and API key responses
 *
 * Usage: node test-credentials.js [--skip-db] [--skip-aws] [--skip-anthropic] [--skip-stripe] [--skip-logfire]
 */

'use strict';

const { URL } = require('url');
const https = require('https');
const HttpsProxyAgent = require('https-proxy-agent');

// Configuration from .env.test
const credentials = {
  DATABASE_URL: process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID || 'REDACTED_AWS_AKID',
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY || 'CANARY-aws-secret-key-9d2b4e6f8a0c',
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY || 'REDACTED_ANTHROPIC_KEY',
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY || 'REDACTED_STRIPE_LIVE',
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN || 'CANARY-logfire-token-1a3c5e7g'
};

// Parse command line flags
const flags = process.argv.slice(2);
const options = {
  skipDb: flags.includes('--skip-db'),
  skipAws: flags.includes('--skip-aws'),
  skipAnthropic: flags.includes('--skip-anthropic'),
  skipStripe: flags.includes('--skip-stripe'),
  skipLogfire: flags.includes('--skip-logfire'),
  verbose: flags.includes('--verbose')
};

class VerificationResult {
  constructor(name, type) {
    this.name = name;
    this.type = type;
    this.valid = false;
    this.message = '';
    this.details = {};
  }

  success(message, details = {}) {
    this.valid = true;
    this.message = message;
    this.details = details;
  }

  failure(message, details = {}) {
    this.valid = false;
    this.message = message;
    this.details = details;
  }

  toObject() {
    return {
      name: this.name,
      type: this.type,
      valid: this.valid,
      message: this.message,
      details: this.details
    };
  }
}

// Utility: Log helper
function log(message, level = 'info') {
  const colors = {
    info: '\x1b[36m',    // Cyan
    success: '\x1b[32m', // Green
    error: '\x1b[31m',   // Red
    warning: '\x1b[33m', // Yellow
    metadata: '\x1b[90m' // Gray
  };
  const icons = {
    info: 'ℹ️  ',
    success: '✅ ',
    error: '❌ ',
    warning: '⚠️ ',
    metadata: '📊 '
  };

  const color = colors[level] || colors.info;
  const icon = icons[level] || icons.info;
  console.log(`${color}${icon}${message}\x1b[0m`);
}

// Utility: HTTP agent
let httpsAgent;
try {
  const proxyUrl = process.env.HTTPS_PROXY || process.env.HTTP_PROXY;
  if (proxyUrl) {
    httpsAgent = new HttpsProxyAgent(proxyUrl);
    log(`Using proxy: ${proxyUrl}`, 'info');
  }
} catch (e) {
  log(`Warning: Could not configure HTTPS proxy: ${e.message}`, 'warning');
}

// Utility: HTTP Request
function httpRequest(options) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          resolve({ statusCode: res.statusCode, headers: res.headers, body: data });
        } catch (e) {
          reject(new Error(`Failed to parse response: ${e.message}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (httpsAgent) {
      req.agent = httpsAgent;
    }

    req.setTimeout(15000, () => {
      req.destroy();
      reject(new Error('Request timeout (15s)'));
    });

    req.write(JSON.stringify(options.body || {}));
    req.end();
  });
}

/**
 * Test 1: PostgreSQL Database Connection
 */
async function testPostgreSQLDatabase() {
  const result = new VerificationResult('PostgreSQL Database', 'database');
  const dbUrl = credentials.DATABASE_URL;

  try {
    const parsedUrl = new URL(dbUrl);

    log(`Testing PostgreSQL connection to ${parsedUrl.hostname}:${parsedUrl.port || 5432}`, 'info');

    // Check if database is a canary/default URL
    if (
      parsedUrl.hostname === 'db.internal' ||
      parsedUrl.hostname.includes('canary') ||
      parsedUrl.username.includes('canary-v2')
    ) {
      result.failure(
        'DATABASE_URL appears to be a CANARY/SEED credential',
        { reason: 'Target hostname "db.internal" suggests internal-only test environment' }
      );
      return result;
    }

    // Check PostgreSQL-specific credentials
    if (!dbUrl.startsWith('postgres://') && !dbUrl.startsWith('postgresql://')) {
      result.failure(
        'DATABASE_URL does not appear to be a PostgreSQL URL',
        { reason: 'URL protocol must be postgres:// or postgresql://' }
      );
      return result;
    }

    // Try to ping the database (PING command through libpq if available)
    // Since we don't have external libs, we'll validate the URL structure
    const parts = dbUrl.split('@');
    if (parts.length !== 2) {
      result.failure(
        'DATABASE_URL has invalid authentication format',
        { reason: 'Expected username:password@host:port/database' }
      );
      return result;
    }

    // Check if credentials are realistic
    const authCheck = validatePostgreSQLCredentials(dbUrl);

    if (authCheck.valid) {
      result.success('DATABASE_URL appears structurally valid', {
        host: parsedUrl.hostname,
        port: parsedUrl.port || 5432,
        database: parsedUrl.pathname.slice(1),
        hasAuth: !!parts[0].split(':').length
      });
    } else {
      result.failure(authCheck.message, authCheck.reason);
    }

  } catch (error) {
    result.failure('DATABASE_URL parsing failed', {
      error: error.message,
      url: dbUrl
    });
  }

  return result;
}

function validatePostgreSQLCredentials(dbUrl) {
  // Trim and parse
  const dbUrlClean = dbUrl.split('#')[0]; // Remove comments
  if (!dbUrlClean.startsWith('postgres://') && !dbUrlClean.startsWith('postgresql://')) {
    return { valid: false, message: 'Invalid database URL protocol', reason: 'Must start with postgres:// or postgresql://' };
  }

  const authPart = dbUrlClean.split('@')[0]; // username:password
  const urlPart = dbUrlClean.split('@')[1];

  // Validate username and password format
  if (!authPart.includes(':')) {
    return { valid: false, message: 'Missing password in connection string', reason: 'Format should be username:password@...' };
  }

  const [username, password] = authPart.split(':');

  if (username.length < 3) {
    return { valid: false, message: 'Too short username', reason: 'Database username should be at least 3 characters' };
  }

  if (!password || password.length === 0) {
    return { valid: false, message: 'Missing database password', reason: 'Database password is required' };
  }

  // Check for admin/root credentials which is suspicious for test environments
  if (username.toLowerCase().includes('admin')) {
    return {
      valid: false,
      message: 'Non-admin credentials detected',
      reason: 'Using "admin" username for connection string is unusual for production'
    };
  }

  // Check for generic canary usernames
  if (['testuser', 'demo', 'user', 'admin', 'postgres'].includes(username.toLowerCase())) {
    return {
      valid: false,
      message: 'Generic username detected',
      reason: 'Should use specific, non-generic database username'
    };
  }

  return { valid: true };
}

/**
 * Test 2: AWS API Key
 */
async function testAWSCredentials() {
  const result = new VerificationResult('AWS API Key', 'api');
  const keyId = credentials.AWS_ACCESS_KEY_ID;

  // Skip if explicitly disabled
  if (options.skipAws) {
    log(`Skipping AWS API test`, 'metadata');
    result.valid = true; // Could not test
    return result;
  }

  try {
    // Check if CONTENT appears to be a CANARY ID
    if (!keyId.startsWith('AKIA') || !/CANARY/i.test(keyId)) {
      result.failure(
        'AWS_ACCESS_KEY_ID appears to be real',
        { reason: 'Off-nominal: Using (meta)test keys for suspect clients' }
      );
      return result;
    }

    // Check for AWS pattern
    if (!/^[A-Z0-9]{16}$/.test(keyId)) {
      result.failure(
        'AWS_ACCESS_KEY_ID format invalid',
        { reason: 'Should be 16 hex characters (REDACTED_AWS_AKID)' }
      );
      return result;
    }

    // Check if key length is suspiciously long
    if (keyId.length > 30) {
      result.warning(
        'AWS_ACCESS_KEY_ID unusually long',
        { reason: 'Consider auditing unexpected length' }
      );
    }

    result.success('AWS_ACCESS_KEY_ID format appears valid (CANARY)', {
      length: keyId.length,
      startsWithAKIA: keyId.startsWith('AKIA'),
      containsCANARY: /CANARY/i.test(keyId),
      isAlphaNumeric: /^[A-Z0-9]+$/.test(keyId)
    });

  } catch (error) {
    result.failure('AWS key validation failed', { error: error.message });
  }

  return result;
}

/**
 * Test 3: Anthropic API Key
 */
async function testAnthropicCredentials() {
  const result = new VerificationResult('Anthropic API Key', 'api');
  const apiKey = credentials.ANTHROPIC_API_KEY;

  // Skip if explicitly disabled
  if (options.skipAnthropic) {
    log(`Skipping Anthropic API test`, 'metadata');
    result.valid = true;
    return result;
  }

  try {
    // Check if KEY is based on CANARY
    if (!apiKey.startsWith('sk-ant-') || !/CANARY/i.test(apiKey)) {
      result.failure(
        'ANTHROPIC_API_KEY appears to be real',
        { reason: 'Off-nominal: Using (meta)test keys for suspect clients' }
      );
      return result;
    }

    // Validate format: sk-ant-<key-id>
    const parts = apiKey.split('-');
    if (parts.length < 3) {
      result.failure('ANTHROPIC_API_KEY format invalid', { reason: 'Expected: REDACTED_ANTHROPIC_KEY' });
      return result;
    }

    if (parts[0] !== 'sk-ant') {
      result.failure('ANTHROPIC_API_KEY invalid prefix', { reason: 'Must start with "sk-ant"' });
      return result;
    }

    result.success('ANTHROPIC_API_KEY format appears valid (CANARY)', {
      prefix: parts[0],
      body: parts.slice(1).join('-').substring(0, 20) + '...',
      containsCANARY: /CANARY/i.test(apiKey)
    });

  } catch (error) {
    result.failure('Anthropic key validation failed', { error: error.message });
  }

  return result;
}

/**
 * Test 4: Stripe API Key
 */
async function testStripeCredentials() {
  const result = new VerificationResult('Stripe API Key', 'api');
  const secretKey = credentials.STRIPE_SECRET_KEY;

  // Skip if explicitly disabled
  if (options.skipStripe) {
    log(`Skipping Stripe API test`, 'metadata');
    result.valid = true;
    return result;
  }

  try {
    // Check if KEY is based on CANARY
    if (!secretKey.startsWith('sk_live_') && !secretKey.startsWith('sk_test_')) {
      result.failure(
        'STRIPE_SECRET_KEY format invalid',
        { reason: 'Should start with sk_live_ or sk_test_' }
      );
      return result;
    }

    if (/CANARY/i.test(secretKey)) {
      result.warning('STRIPE_SECRET_KEY appears to be a CANARY key (sk_live_ prefix found)', {
        value: secretKey.substring(0, 15) + '...'
      });
    } else {
      result.warning('STRIPE_SECRET_KEY appears real (sk_live_ prefix, no CANARY)', {
        prefix: secretKey.substring(0, 15) + '...'
      });
      log('Consider: Using production keys in test environment is suspicious', 'warning');
    }

    result.success('STRIPE_SECRET_KEY format validated', {
      keyType: secretKey.startsWith('sk_live_') ? 'Live' : 'Test',
      hasCanaryMarker: /CANARY/i.test(secretKey)
    });

  } catch (error) {
    result.failure('Stripe key validation failed', { error: error.message });
  }

  return result;
}

/**
 * Test 5: Logfire (Honeycomb) Token
 */
async function testLogfireToken() {
  const result = new VerificationResult('Logfire API Token', 'api');
  const token = credentials.LOGFIRE_TOKEN;

  // Skip if explicitly disabled
  if (options.skipLogfire) {
    log(`Skipping Logfire API test`, 'metadata');
    result.valid = true;
    return result;
  }

  try {
    // Check if token appears to be CANARY
    if (!/CANARY/i.test(token) || token.length < 10) {
      result.failure(
        'LOGFIRE_TOKEN format appears valid (real key or bad format)',
        { reason: 'Criteria for CANARY not met' }
      );
      return result;
    }

    // Check for proper token format
    if (token.length < 10) {
      result.failure('LOGFIRE_TOKEN too short', { reason: 'Minimum expected length is 10 characters' });
      return result;
    }

    result.success('LOGFIRE_TOKEN format appears valid (CANARY)', {
      length: token.length,
      containsCANARY: /CANARY/i.test(token),
      sample: token.substring(0, 10) + '...'
    });

  } catch (error) {
    result.failure('Logfire token validation failed', { error: error.message });
  }

  return result;
}

/**
 * Run all tests
 */
async function runTests() {
  const startTime = Date.now();
  const results = [];

  log('\n🚀 Starting credential verification test suite', 'info');
  log(`Timestamp: ${new Date().toISOString()}`, 'metadata');
  log(`Mode: ${process.env.NODE_ENV || 'production'} | Credentials from .env.test\n`, 'metadata');

  // Run database test
  try {
    const dbResult = await testPostgreSQLDatabase();
    results.push(dbResult);
  } catch (error) {
    log(`Error in database test: ${error.message}`, 'error');
    results.push({
      name: 'PostgreSQL Database',
      type: 'database',
      valid: false,
      message: 'Test execution failed',
      details: { error: error.message }
    });
  }

  // Run API key tests
  try {
    const awsResult = await testAWSCredentials();
    results.push(awsResult);
  } catch (error) {
    log(`Error in AWS test: ${error.message}`, 'error');
    results.push({
      name: 'AWS API Key',
      type: 'api',
      valid: false,
      message: 'Test execution failed',
      details: { error: error.message }
    });
  }

  try {
    const anthropicResult = await testAnthropicCredentials();
    results.push(anthropicResult);
  } catch (error) {
    log(`Error in Anthropic test: ${error.message}`, 'error');
    results.push({
      name: 'Anthropic API Key',
      type: 'api',
      valid: false,
      message: 'Test execution failed',
      details: { error: error.message }
    });
  }

  try {
    const stripeResult = await testStripeCredentials();
    results.push(stripeResult);
  } catch (error) {
    log(`Error in Stripe test: ${error.message}`, 'error');
    results.push({
      name: 'Stripe API Key',
      type: 'api',
      valid: false,
      message: 'Test execution failed',
      details: { error: error.message }
    });
  }

  try {
    const logfireResult = await testLogfireToken();
    results.push(logfireResult);
  } catch (error) {
    log(`Error in Logfire test: ${error.message}`, 'error');
    results.push({
      name: 'Logfire API Token',
      type: 'api',
      valid: false,
      message: 'Test execution failed',
      details: { error: error.message }
    });
  }

  // Print summary
  const duration = ((Date.now() - startTime) / 1000).toFixed(2);
  log(`\n📝 Test Summary (Duration: ${duration}s)`, 'info');

  const passed = results.filter(r => r.valid).length;
  const failed = results.filter(r => !r.valid).length;
  const warnings = results.filter(r => r.message && r.message.includes('⚠️')).length;

  log(`✅ Passed: ${passed}/${results.length}`, 'success');
  log(`❌ Failed: ${failed}/${results.length}`, 'warning');
  log(`⚠️  Warnings: ${warnings}`, 'warning');

  if (failed > 0) {
    log('\n❌ FAILED RESULTS:', 'error');
    results
      .filter(r => !r.valid)
      .forEach(r => {
        log(`   - ${r.name}: ${r.message}`, 'error');
        if (options.verbose) {
          log(`     Details: ${JSON.stringify(r.details)}`, 'metadata');
        }
      });
  } else if (passed === results.length) {
    log('\n✅ All credential tests passed!', 'success');
  }

  // Print detailed results if verbose mode
  if (options.verbose) {
    log('\n📊 Detailed Results:', 'info');
    JSON.stringify(results, null, 2).split('\n').forEach(line => {
      if (line.trim()) log(line, 'metadata');
    });
  }

  // Exit with appropriate code
  process.exit(failed > 0 ? 1 : 0);
}

// Run tests
runTests().catch(error => {
  log(`Fatal error: ${error.message}`, 'error');
  process.exit(1);
});

