      );
      return result;
    }

    // Check PostgreSQL-specific credentials
    if (!dbUrl.startsWith('postgres://') && !dbUrl.startsWith('postgresql://')) {
      result.failure(
        'DATABASE_URL does not appear to be a PostgreSQL URL',
        { reason: 'URL protocol must be postgres:// or postgresql://' }
      );
      return result;
    }

    // Try to ping the database (PING command through libpq if available)
    // Since we don't have external libs, we'll validate the URL structure
    const parts = dbUrl.split('@');
    if (parts.length !== 2) {
      result.failure(
        'DATABASE_URL has invalid authentication format',
        { reason: 'Expected username:password@host:port/database' }
      );
      return result;
    }

    // Check if credentials are realistic
    const authCheck = validatePostgreSQLCredentials(dbUrl);

    if (authCheck.valid) {
      result.success('DATABASE_URL appears structurally valid', {
        host: parsedUrl.hostname,
        port: parsedUrl.port || 5432,
        database: parsedUrl.pathname.slice(1),
        hasAuth: !!parts[0].split(':').length
      });
    } else {
      result.failure(authCheck.message, authCheck.reason);
    }

  } catch (error) {
    result.failure('DATABASE_URL parsing failed', {
      error: error.message,
      url: dbUrl
    });
  }

  return result;
}

function validatePostgreSQLCredentials(dbUrl) {
  // Trim and parse
  const dbUrlClean = dbUrl.split('#')[0]; // Remove comments
  if (!dbUrlClean.startsWith('postgres://') && !dbUrlClean.startsWith('postgresql://')) {
    return { valid: false, message: 'Invalid database URL protocol', reason: 'Must start with postgres:// or postgresql://' };
  }

  const authPart = dbUrlClean.split('@')[0]; // username:password
  const urlPart = dbUrlClean.split('@')[1];

  // Validate username and password format
  if (!authPart.includes(':')) {
    return { valid: false, message: 'Missing password in connection string', reason: 'Format should be username:password@...' };
  }

  const [username, password] = authPart.split(':');

  if (username.length < 3) {
    return { valid: false, message: 'Too short username', reason: 'Database username should be at least 3 characters' };
  }

  if (!password || password.length === 0) {
    return { valid: false, message: 'Missing database password', reason: 'Database password is required' };
  }

  // Check for admin/root credentials which is suspicious for test environments
  if (username.toLowerCase().includes('admin')) {
    return {
      valid: false,
      message: 'Non-admin credentials detected',
      reason: 'Using "admin" username for connection string is unusual for production'
    };
  }

  // Check for generic canary usernames
  if (['testuser', 'demo', 'user', 'admin', 'postgres'].includes(username.toLowerCase())) {
    return {
      valid: false,
      message: 'Generic username detected',
      reason: 'Should use specific, non-generic database username'
    };
  }

  return { valid: true };
}

