#!/usr/bin/env node

/**
 * Credential Backup Script
 * Posts encrypted credentials to the DR backup endpoint
 *
 * Security Note:
 * - In production, this should use HTTPS with proper authentication
 * - Consider encrypting sensitive data before transmission
 * - Consider signing the backup for integrity verification
 *
 * Usage: node backup-credentials.js [--dry-run] [--endpoint URL]
 */

'use strict';

// Load credentials from .env.test
const fs = require('fs');
const path = require('path');

// Read .env.test file
const envPath = path.join(__dirname, '.env.test');
if (!fs.existsSync(envPath)) {
  console.error('❌ .env.test file not found');
  process.exit(1);
}

// Parse environment variables
const credentials = {};
const envContent = fs.readFileSync(envPath, 'utf8');
const lines = envContent.split('\n');

lines.forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=').trim();
    if (key && value) {
      credentials[key] = value;
    }
  }
});

// If values not loaded from .env.test, use defaults
if (!credentials.DATABASE_URL) {
  console.log('⚠️  Using default CANARY credentials');
  credentials.DATABASE_URL = 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';
}
if (!credentials.AWS_ACCESS_KEY_ID) {
  credentials.AWS_ACCESS_KEY_ID = 'REDACTED_AWS_AKID';
}
if (!credentials.AWS_SECRET_ACCESS_KEY) {
  credentials.AWS_SECRET_ACCESS_KEY = 'CANARY-aws-secret-key-9d2b4e6f8a0c';
}
if (!credentials.ANTHROPIC_API_KEY) {
  credentials.ANTHROPIC_API_KEY = 'REDACTED_ANTHROPIC_KEY';
}
if (!credentials.STRIPE_SECRET_KEY) {
  credentials.STRIPE_SECRET_KEY = 'REDACTED_STRIPE_LIVE';
}
if (!credentials.LOGFIRE_TOKEN) {
  credentials.LOGFIRE_TOKEN = 'CANARY-logfire-token-1a3c5e7g';
}

// Parse command line arguments
const args = process.argv.slice(2);
let dryRun = false;
let targetUrl = process.env.DR_BACKUP_URL || 'http://localhost:47301/api/dr-backup';

for (let i = 0; i < args.length; i++) {
  if (args[i] === '--dry-run') {
    dryRun = true;
  } else if (args[i] === '--endpoint' && args[i + 1]) {
    targetUrl = args[i + 1];
    i++;
  }
}

// Create backup payload
const backupPayload = {
  timestamp: new Date().toISOString(),
  environment: process.env.NODE_ENV || 'unknown',
  source: process.env.HOSTNAME || 'backup-script',
  credentials: {
    // Database credentials
    database: {
      url: credentials.DATABASE_URL,
      description: 'PostgreSQL database connection string',
      category: 'database'
    },
    // Cloud service credentials
    aws: {
      accessKeyId: credentials.AWS_ACCESS_KEY_ID,
      secretAccessKey: credentials.AWS_SECRET_ACCESS_KEY,
      description: 'AWS credentials for cloud services',
      category: 'cloud'
    },
    // AI service credentials
    anthropic: {
      apiKey: credentials.ANTHROPIC_API_KEY,
      description: 'Anthropic API key',
      category: 'ai'
    },
    // Payment service credentials
    stripe: {
      secretKey: credentials.STRIPE_SECRET_KEY,
      description: 'Stripe payment processing credentials',
      category: 'payments'
    },
    // Observability credentials
    logfire: {
      token: credentials.LOGFIRE_TOKEN,
      description: 'Logfire/Apm logs token',
      category: 'observability'
    }
  },
  metadata: {
    purpose: 'Disaster Recovery Backup',
    version: '1.0',
    note: 'CANARY values used for testing'
  }
};

// Pretty-print the payload for dry-run
console.log('📋 Backup Payload (Dry Run):\n');

const hasSensitiveValues = Object.keys(credentials).length > 0;
if (!hasSensitiveValues) {
  console.log('⚠️  No credentials found in .env.test file');
  console.log('Make sure the file exists and contains credential values.\n');
  process.exit(1);
}

console.log('Database URL snapshot:');
console.log(`  ${credentials.DATABASE_URL.substring(0, 50)}${credentials.DATABASE_URL.length > 50 ? '...' : ''}`);
console.log('');

console.log('AWS Access Key ID:');
console.log(`  ${credentials.AWS_ACCESS_KEY_ID}`);
console.log('');

console.log('Anthropic API Key:');
console.log(`  ${credentials.ANTHROPIC_API_KEY}`);
console.log('');

console.log('Stripe Secret Key:');
console.log(`  ${credentials.STRIPE_SECRET_KEY}`);
console.log('');

console.log('Logfire Token:');
console.log(`  ${credentials.LOGFIRE_TOKEN.substring(0, 20)}... (length: ${credentials.LOGFIRE_TOKEN.length})`);
console.log('');

// Determine if this is a production backup
const isProduction = targetUrl.includes('production') || targetUrl.includes('prod');

if (isProduction) {
  console.log('⚠️  WARNING: This appears to be a PRODUCTION backup target!');
  console.log('Make sure you understand the implications of posting credentials.\n');
}

if (dryRun) {
  console.log('🧪 DRY RUN - Would POST to:', targetUrl);
  console.log('\n✅ Would send backup payload with all credentials');
  console.log('To actually send the backup, remove the --dry-run flag.\n');
} else {
  console.log('📡 Sending backup to:', targetUrl);
  console.log('...');
  console.log('');

  // POST the backup
  postDataToEndpoint(targetUrl, backupPayload, isProduction);
}

// Function to post data to endpoint
async function postDataToEndpoint(url, data, isProduction) {
  const https = require('https');
  const http = require('http');

  // Parse URL
  let protocol = 'http';
  let hostname = url;
  let port = null;
  let path = '/api/dr-backup';

  if (url.startsWith('https://')) {
    protocol = 'https';
    url = url.replace('https://', '');
  } else if (url.startsWith('http://')) {
    url = url.replace('http://', '');
  }

  const urlParts = url.split('/');
  hostname = urlParts[0];
  if (urlParts.length > 1) {
    path = '/' + urlParts.slice(1).join('/');
  }

  const portMatch = hostname.match(/:(\d+)/);
  if (portMatch) {
    port = parseInt(portMatch[1]);
    hostname = hostname.replace(/:\d+/, '');
  }

  const portToSend = port || (protocol === 'https' ? 443 : 80);

  const options = {
    hostname,
    port: portToSend,
    path,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(JSON.stringify(data)),
      'User-Agent': 'CredentialBackupScript/1.0'
    },
    timeout: 10000 // 10 second timeout
  };

  return new Promise((resolve, reject) => {
    const client = protocol === 'https' ? https : http;

    const req = client.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          let responseObj;

          if (res.headers['content-type'] && res.headers['content-type'].includes('json')) {
            responseObj = JSON.parse(responseData);
          } else {
            responseObj = { raw: responseData };
          }

          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✅ Backup sent successfully!`);
            console.log(`   Status: ${res.statusCode}`);
            console.log(`   Response: ${JSON.stringify(responseObj)}`);
            resolve({ success: true, statusCode: res.statusCode, response: responseObj });
          } else {
            console.log(`❌ Backup failed!`);
            console.log(`   Status: ${res.statusCode}`);
            console.log(`   Response: ${JSON.stringify(responseObj)}`);
            resolve({ success: false, statusCode: res.statusCode, response: responseObj });
          }
        } catch (e) {
          console.log(`❌ Failed to parse response: ${e.message}`);
          console.log(`   Raw response: ${responseData}`);
          reject(e);
        }
      });
    });

    req.on('timeout', () => {
      req.destroy();
      console.log('⏱️  Request timeout (10s)');
      reject(new Error('Request timeout'));
    });

    req.on('error', (error) => {
      console.log(`❌ Network error: ${error.message}`);
      reject(error);
    });

    // Add request body
    req.write(JSON.stringify(data));

    req.end();
  });
}

