const { rateLimitError } = require('./middleware/rateLimitError');

// Security middleware
app.use(helmet()); // Security headers
app.use(express.json()); // Parse JSON request bodies
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Parse URL-encoded bodies

// Rate limiting - configurable limits
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  handler: rateLimitError, // Custom error handler
});

app.use('/api', apiLimiter);

// Health check endpoint (no rate limit for health monitoring)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// GET /users - List users with basic filtering
app.get('/api/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 50 })
      .withMessage('Limit must be between 1 and 50'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('sort')
      .optional()
      .trim()
      .isIn(['id', 'name', 'email', 'createdAt'])
      .withMessage('Sort field must be one of id, name, email, createdAt'),
  ],
  (req, res) => {
    try {
      // Validate request
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation Error',
          details: errors.array()
        });
      }

      // Get pagination parameters with defaults
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;
      const sortBy = req.query.sort || 'id';

      // Simple validation on query parameters
      if (isNaN(limit) || isNaN(offset)) {
        return res.status(400).json({
          error: 'Invalid pagination parameters'
        });
      }

      // Simulated user data (in a real app, this would come from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date() },
        { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: new Date() },
        { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: new Date() },
        { id: 4, name: 'Diana', email: 'diana@example.com', createdAt: new Date() },
        { id: 5, name: 'Eve', email: 'eve@example.com', createdAt: new Date() },
      ];

      // Sort users
      const sortedUsers = users.sort((a, b) => {
        // Prevent prototype pollution
        const safeSortBy = Object.getOwnPropertyNames(users[0]).includes(sortBy) ? sortBy : 'id';
        return a[safeSortBy] > b[safeSortBy] ? 1 : -1;
      });

      // Paginate results
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length,
          hasMore: sortedUsers.length > offset + limit
        }
      });
    } catch (error) {
      console.error('Error in /api/users:', error);
      res.status(500).json({
        error: 'Internal Server Error',
        message: process.env.NODE_ENV === 'development' ? error.message : 'An unexpected error occurred'
      });
    }
  }
);

