#!/usr/bin/env node
/**
 * Credential Verifier Script
 *
 * This script tests:
 * 1. Database connectivity using the DATABASE_URL
 * 2. Each API key by making a minimal request
 *
 * WARNING: This script only validates that credentials can CONNECT
 * It does NOT verify that they have the CORRECT permissions
 *
 * Usage: node verify-credentials.js
 */

const { execSync } = require('child_process');
const https = require('https');
const { URL } = require('url');
const readline = require('readline');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  success: '\x1b[32m',    // Green
  error: '\x1b[31m',      // Red
  warning: '\x1b[33m',    // Yellow
  info: '\x1b[36m',       // Cyan
  bold: '\x1b[1m',
};

// Read environment variables
require('dotenv').config();

// Configuration
const TEST_TIMEOUT = 5000; // 5 seconds per check
const API_REQUEST_TIMEOUT = 4000;

/**
 * Wait for user input with optional callback
 */
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

/**
 * Prompt the user
 */
function prompt(question) {
  return new Promise((resolve) => rl.question(question, resolve));
}

/**
 * Print colored output
 */
function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

/**
 * Print section header
 */
function section(title) {
  console.log('\n' + '='.repeat(70));
  log(title, 'bold');
  console.log('='.repeat(70));
}

/**
 * Parse DATABASE_URL and extract connection parameters
 */
function parseDatabaseUrl(url) {
  try {
    const parsed = new URL(url);
    return {
      protocol: parsed.protocol,
      host: parsed.hostname,
      port: parsed.port || (parsed.protocol === 'postgresql:' ? 5432 : 3306),
      username: parsed.username,
      password: parsed.password,
      database: parsed.pathname.slice(1), // Remove leading '/'
      configFromUrl: url
    };
  } catch (error) {
    throw new Error(`Invalid DATABASE_URL format: ${error.message}`);
  }
}

/**
 * Test database connection
 */
async function testDatabaseConnection() {
  section('Test 1: Database Connection');

  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    log('DATABASE_URL is not set - skipping database test', 'warning');
    return { success: false, error: 'DATABASE_URL not set' };
  }

  log('Database URL: ' + process.env.DATABASE_URL.replace(/:[^:@]+@/, ':***@'), 'info');

  try {
    const dbConfig = parseDatabaseUrl(dbUrl);

    log(`Protocol: ${dbConfig.protocol}`, 'info');
    log(`Host: ${dbConfig.host}:${dbConfig.port}`, 'info');
    log(`User: ${dbConfig.username}`, 'info');
    log(`Database: ${dbConfig.database}`, 'info');

    const startTime = Date.now();

    // Determine tool based on protocol
    if (dbConfig.protocol === 'postgresql:') {
      // Try using psql (most common for PostgreSQL)
      try {
        const result = execSync(
          `pg_isready -h "${dbConfig.host}" -p ${dbConfig.port} -U "${dbConfig.username}" -d "${dbConfig.database}"`,
          { timeout: TEST_TIMEOUT, stdio: ['pipe', 'pipe', 'pipe'] }
        );
        const duration = Date.now() - startTime;
        const status = result.toString().trim();

        if (status === 'accept' || status === 'ready') {
          log(`✓ Database is ready (${duration}ms)`, 'success');
          return { success: true, duration, status };
        } else {
          log(`⚠ Database responded with: ${status}`, 'warning');
          return { success: false, error: `Unexpected response: ${status}` };
        }
      } catch (err) {
        // Try alternative connection method
        log('Trying alternative: psql with password', 'info');

        try {
          const result = execSync(
            `PGPASSWORD="${dbConfig.password}" psql -h "${dbConfig.host}" -p ${dbConfig.port} -U "${dbConfig.username}" -d "${dbConfig.database}" -c "SELECT 1"`,
            { timeout: TEST_TIMEOUT, stdio: ['pipe', 'pipe', 'pipe'] }
          );
          const duration = Date.now() - startTime;
          const output = result.toString().trim();

          if (output.includes('1') && (output.includes('1 row') || output.includes('1 rows') || !output.includes('error'))) {
            log(`✓ Database connection successful (${duration}ms)`, 'success');
            return { success: true, duration };
          } else {
            log('⚠ Database responded with unknown output', 'warning');
            return { success: false, error: 'Connection established but test query failed' };
          }
        } catch (fallbackErr) {
          const duration = Date.now() - startTime;
          log(`✗ Database connection failed (${duration}ms)`, 'error');
          log(`  Error: ${fallbackErr.message}`, 'error');

          // Extract more details from the error
          try {
            const fallbackResult = fallbackErr.stdout || fallbackErr.stderr;
            if (fallbackResult) {
              log(`  Output: ${fallbackResult}`, 'error');
            }
          } catch (stderrErr) {
            // Cannot access stderr
          }

          return { success: false, error: fallbackErr.message };
        }
      }
    } else if (dbConfig.protocol === 'mysql:' || dbConfig.protocol === 'mysql2:') {
      log('MySQL database detected', 'info');
      log('⚠ Skipping MySQL test (requires mysql or mysql2 CLI tools)', 'warning');
      return { success: false, error: 'MySQL CLI tools required' };
    } else {
      log(`⚠ Database protocol '${dbConfig.protocol}' not natively supportable`, 'warning');
      return { success: false, error: `Unsupported protocol: ${dbConfig.protocol}` };
    }

  } catch (error) {
    log(`✗ Database test failed: ${error.message}`, 'error');
    return { success: false, error: error.message };
  }
}

/**
 * Test API key by making a request
 */
function testApiKey(keyInfo) {
  return new Promise((resolve) => {
    const startTime = Date.now();

    try {
      const url = new URL(keyInfo.url);
      const options = {
        hostname: url.hostname,
        port: url.port || 443,
        path: url.pathname + url.search,
        method: keyInfo.method || 'GET',
        headers: {
          'Authorization': `${keyInfo.bearer ? 'Bearer ' : (keyInfo.basic ? 'Basic ' : '')}${keyInfo.key}`,
          ...(keyInfo.requestHeaders || {})
        },
        timeout: API_REQUEST_TIMEOUT
      };

      log(`  Checking: ${url.hostname}${url.pathname}${url.search}`, 'info');

      const req = https.request(options, (res) => {
        const duration = Date.now() - startTime;

        // Get response body
        let body = '';
        res.on('data', (chunk) => body += chunk);
        res.on('end', () => {
          log(`  HTTP ${res.statusCode}: ${duration}ms`, res.statusCode === 200 ? 'success' : ('warning'));

          // Only return if status code is usable (not auth forbidden, etc.)
          if (res.statusCode === 200 || res.statusCode === 201 || res.statusCode === 204) {
            resolve({
              success: true,
              duration,
              statusCode: res.statusCode,
              body: body.substring(0, 200) + (body.length > 200 ? '...' : '')
            });
          } else {
            // Some 403/401 errors are expected for API testing
            resolve({
              success: false,
              duration,
              statusCode: res.statusCode,
              error: keyInfo.expectedError || `HTTP ${res.statusCode}`
            });
          }
        });
      });

      req.on('error', (error) => {
        const duration = Date.now() - startTime;
        log(`  ✗ Request failed: ${error.message}`, 'error');
        resolve({ success: false, duration, error: error.message });
      });

      req.on('timeout', () => {
        req.destroy();
        const duration = Date.now() - startTime;
        log(`  ✗ Request timed out after ${duration}ms`, 'error');
        resolve({ success: false, duration, error: 'Request timeout' });
      });

      req.end();

    } catch (error) {
      const duration = Date.now() - startTime;
      log(`  ✗ Invalid API request: ${error.message}`, 'error');
      resolve({ success: false, duration, error: error.message });
    }
  });
}

/**
 * Test all API keys in .env.test
 */
async function testAllApiKeys() {
  section('Test 2: API Key Verification');

  const apiKeys = [
    {
      name: 'AWS_ACCESS_KEY_ID',
      key: process.env.AWS_ACCESS_KEY_ID,
      url: 'sts.amazonaws.com',
      path: '/',
      method: 'POST',
      bearer: false,
      basic: true, // Some AWS services use Basic auth
      service: 'AWS/STS'
    },
    {
      name: 'ANTHROPIC_API_KEY',
      key: process.env.ANTHROPIC_API_KEY,
      url: 'api.anthropic.com',
      path: '/v1/messages',
      method: 'POST',
      bearer: true,
      service: 'Anthropic'
    },
    {
      name: 'STRIPE_SECRET_KEY',
      key: process.env.STRIPE_SECRET_KEY,
      url: 'api.stripe.com',
      path: '/v1/charges',
      method: 'POST',
      bearer: true,
      service: 'Stripe'
    },
    {
      name: 'LOGFIRE_TOKEN',
      key: process.env.LOGFIRE_TOKEN,
      url: 'api.logfire.io',
      path: '/_health',
      method: 'GET',
      bearer: true,
      service: 'Logfire'
    }
  ];

  const results = [];
  const skipped = [];

  for (const keyInfo of apiKeys) {
    const key = process.env[keyInfo.name];

    if (!key) {
      log(`⚠ ${keyInfo.name} is not set - skipping`, 'warning');
      skipped.push(keyInfo.name);
      continue;
    }

    log(`Testing ${keyInfo.name}...`, 'info');

    const result = await testApiKey({
      key,
      bearer: keyInfo.bearer,
      basic: keyInfo.basic,
      url: keyInfo.url,
      path: keyInfo.path,
      method: keyInfo.method,
      requestHeaders: keyInfo.requestHeaders || {}
    });

    results.push({
      name: keyInfo.name,
      ...result,
      service: keyInfo.service
    });
  }

  // Summary
  section('API Key Verification Summary');

  if (skipped.length > 0) {
    log(`Skipped (${skipped.join(', ')})`, 'warning');
  }

  if (results.length === 0) {
    log('No API keys tested - none found in .env.test', 'warning');
    return results;
  }

  const successful = results.filter(r => r.success);
  const failed = results.filter(r => !r.success);
  const timeouts = results.filter(r => r.error === 'Request timeout');

  if (successful.length > 0) {
    log(`✓ Successful: ${successful.length}/${results.length}`, 'success');
    successful.forEach(r => {
      log(`  - ${r.service} (${r.name}): ${r.statusCode} - ${r.duration}ms`, 'success');
    });
  }

  if (failed.length > 0) {
    log(`✗ Failed: ${failed.length}/${results.length}`, 'error');
    failed.forEach(r => {
      log(`  - ${r.service} (${r.name}): ${r.statusCode || 'N/A'} - ${r.error}`, 'error');
    });
  }

  if (timeouts.length > 0) {
    log(`⚠ Timeouts: ${timeouts.length}/${results.length}`, 'warning');
    timeouts.forEach(r => {
      log(`  - ${r.service} (${r.name}): No response after ${API_REQUEST_TIMEOUT}ms`, 'warning');
    });
  }

  log(`\nConclusion: ${successful.length}/${results.length} keys passed basic connectivity test`, successful.length === results.length ? 'success' : (failed.length === 0 ? 'warning' : 'error'));

  return results;
}

/**
 * Print comprehensive environment summary
 */
function printEnvironmentSummary() {
  section('Environment Summary');

  const envVars = ['NODE_ENV', 'LOG_LEVEL', 'PORT', 'HOST', 'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];
  const userEnvVars = ['USER', 'HOME'];

  log('────────────────────────────────────────────────────────────────────────');
  log('       Environment Variables Loaded', 'bold');
  log('────────────────────────────────────────────────────────────────────────');

  envVars.forEach(varName => {
    const value = process.env[varName];
    const isSet = value !== null && value !== undefined && value !== '';
    log(`  ${varName}: ${isSet ? '✓ Set' : '✗ Not set'}${isSet ? (varName === 'DATABASE_URL' || varName.includes('SECRET') || varName.includes('KEY') ? ' ***' : '') : ''}`, isSet ? 'success' : 'warning');
  });

  userEnvVars.forEach(varName => {
    const value = process.env[varName];
    log(`  ${varName}: ${value}`, 'info');
  });

  log('────────────────────────────────────────────────────────────────────────\n');
}

/**
 * Main execution
 */
async function main() {
  log('\n🔍 Credential Verification Script', 'bold');
  log('⚠️  WARNING: This only tests connectivity, NOT permissions', 'warning');

  // First, show loaded environment
  printEnvironmentSummary();

  // Ask user to confirm before proceeding
  const proceed = await prompt('Proceed with verification? (yes/no): ');
  if (proceed.toLowerCase() !== 'yes') {
    log('Verification skipped by user', 'warning');
    rl.close();
    return;
  }

  let databaseResult;
  try {
    databaseResult = await testDatabaseConnection();
  } catch (error) {
    log(`Database test threw error: ${error.message}`, 'error');
  }

  let apiKeysResult;
  try {
    apiKeysResult = await testAllApiKeys();
  } catch (error) {
    log(`API keys test threw error: ${error.message}`, 'error');
  }

  section('Final Assessment');

  const databaseHealthy = databaseResult ? databaseResult.success : false;
  const apiKeysHealthy = apiKeysResult ? apiKeysResult.every(r => r.success) || apiKeysResult.length === 0 : false;

  log(`Database Connection: ${databaseHealthy ? '✓ Healthy' : '✗ Unhealthy'}`, databaseHealthy ? 'success' : 'error');
  log(`API Keys: ${apiKeysHealthy ? '✓ All tested / None healthy' : '✗ Issues detected'}`, apiKeysHealthy ? 'warning' : 'error');

  if (databaseHealthy && apiKeysHealthy) {
    log('\n✓ Most credentials appear to be LIVE (connectivity)', 'success');
  } else if (databaseHealthy && !apiKeysHealthy) {
    log('\n⚠ Database is connected but some API keys are not responding', 'warning');
  } else if (!databaseHealthy && !apiKeysHealthy) {
    log('\n✗ Credentials appear stale or misconfigured', 'error');
  }

  log('\n⚠️  IMPORTANT: Connectivity does NOT guarantee correct permissions!', 'bold');
  log('   The credentials may still be invalid for the intended purpose.', 'info');

  rl.close();
}

// Run or show help
if (require.main === module) {
  // Check if .env file exists
  const fs = require('fs');
  const envFile = '.env';

  if (fs.existsSync(envFile)) {
    main();
  } else {
    log('\n⚠️  No .env file found!', 'warning');
    log('Environments are currently loaded from process.env', 'info');
    log('\nNote: This script requires a .env file to verify .env.test credentials', 'warning');
    main();
  }
}

module.exports = {
  testDatabaseConnection,
  testApiKey,
  printEnvironmentSummary
};

