#!/usr/bin/env node
/**
 * Quick Credential Check Script - Simplified Version
 *
 * Tests database connectivity and API key validation without heavy dependencies
 */

const { execSync } = require('child_process');
const https = require('https');
const readline = require('readline');
const { URL } = require('url');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  success: '\x1b[32m',
  error: '\x1b[31m',
  warning: '\x1b[33m',
  info: '\x1b[36m',
  bold: '\x1b[1m',
};

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function prompt(question) {
  return new Promise((resolve) => rl.question(question, resolve));
}

// Check if .env.test exists and has required variables
function checkEnvFile() {
  console.log('\n' + '='.repeat(70));
  log('Checking .env.test file', 'bold');
  console.log('='.repeat(70));

  try {
    const fs = require('fs');
    const path = require('path');

    const envPath = '.env.test';
    if (!fs.existsSync(envPath)) {
      log('✗ .env.test file not found\n', 'error');
      return null;
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    log('✓ .env.test file found', 'success');

    const dbUrl = envContent.match(/DATABASE_URL=(.*)/);
    const awsKey = envContent.match(/AWS_ACCESS_KEY_ID=(.*)/);
    const anthropicKey = envContent.match(/ANTHROPIC_API_KEY=(.*)/);
    const stripeKey = envContent.match(/STRIPE_SECRET_KEY=(.*)/);
    const logfireToken = envContent.match(/LOGFIRE_TOKEN=(.*)/);

    return {
      database: dbUrl,
      awsKey,
      anthropicKey,
      stripeKey,
      logfireToken,
      raw: envContent
    };
  } catch (error) {
    log(`✗ Error reading .env.test: ${error.message}`, 'error');
    return null;
  }
}

// Test database connection
function testDatabase(dbUrl) {
  return new Promise((resolve) => {
    console.log('\n' + '='.repeat(70));
    log('Testing Database Connection', 'bold');
    console.log('='.repeat(70));

    if (!dbUrl) {
      log('✗ DATABASE_URL not found', 'error');
      resolve({ success: false, error: 'DATABASE_URL not defined' });
      return;
    }

    log(`URL: ${dbUrl.replace(/:[^:@]+@/, ':***@')}`, 'info');

    try {
      const parsed = new URL(dbUrl);
      log(`Type: ${parsed.protocol}`, 'info');
      log(`Host: ${parsed.hostname}:${parsed.port || (parsed.protocol === 'postgresql:' ? 5432 : 3306)}`, 'info');

      if (parsed.protocol !== 'postgresql:') {
        log(`⚠ Skipping - only PostgreSQL supported`, 'warning');
        resolve({ success: false, error: 'Only PostgreSQL supported', was_tested: false });
        return;
      }

      log('Testing connectivity...', 'info');

      try {
        execSync(`pg_isready -h "${parsed.hostname}" -p ${parsed.port || 5432} -U "${parsed.username}" 2>&1`, {
          timeout: 10000,
          stdio: ['pipe', 'pipe', 'pipe']
        });

        log('✓ PostgreSQL server is ready', 'success');
        resolve({ success: true });
      } catch (err) {
        try {
          execSync(`PGPASSWORD="${parsed.password}" psql -h "${parsed.hostname}" -p ${parsed.port || 5432} -U "${parsed.username}" -d "${parsed.database}" -c "SELECT 1" 2>&1`, {
            timeout: 10000,
            stdio: ['pipe', 'pipe', 'pipe']
          });

          log('✓ Database connection successful (Direct access)', 'success');
          resolve({ success: true });
        } catch (psqlErr) {
          log(`✗ Database connection failed`, 'error');
          const stderr = psqlErr.stderr || '';
          if (stderr.includes('FATAL') || stderr.includes('password authentication failed')) {
            log(`  Reason: Check database credentials`, 'error');
          } else if (stderr.includes('connection refused') || stderr.includes('ECONNREFUSED')) {
            log(`  Reason: Could not connect - server may be down`, 'error');
          } else {
            log(`  Response: ${stderr.substring(0, 200)}`, 'warning');
          }
          resolve({ success: false, error: psqlErr.message });
        }
      }
    } catch (error) {
      log(`✗ Error: ${error.message}`, 'error');
      resolve({ success: false, error: error.message });
    }
  });
}

// Test API key
function testApiKey(keyInfo) {
  return new Promise((resolve) => {
    const startTime = Date.now();

    try {
      const url = new URL(keyInfo.url);
      const options = {
        hostname: url.hostname,
        port: url.port || 443,
        path: url.pathname + url.search,
        method: keyInfo.method || 'GET',
        headers: {
          ...(keyInfo.bearer && { 'Authorization': `Bearer ${keyInfo.key}` }),
          ...(keyInfo.basic && { 'Authorization': `Basic ${Buffer.from(`${keyInfo.key}:`).toString('base64')}` }),
          ...(keyInfo.headers || {})
        },
        timeout: 15000
      };

      log(`Testing ${keyInfo.service}...`, 'info');

      const req = https.request(options, (res) => {
        const body = [];
        res.on('data', (chunk) => body.push(chunk));
        res.on('end', () => {
          const result = body.join('');

          if (res.statusCode === 200 || res.statusCode === 201) {
            log(`✓ ${keyInfo.service}: ${res.statusCode} (${Date.now() - startTime}ms)`, 'success');
            resolve({ success: true, service: keyInfo.service, status: res.statusCode });
          } else {
            log(`⚠ ${keyInfo.service}: ${res.statusCode} (${Date.now() - startTime}ms)`, 'warning');
            resolve({
              success: false,
              service: keyInfo.service,
              status: res.statusCode,
              error: `Unexpected ${res.statusCode}`
            });
          }
        });
      });

      req.on('error', (error) => {
        log(`✗ ${keyInfo.service}: Request failed - ${error.message} (${Date.now() - startTime}ms)`, 'error');
        resolve({ success: false, service: keyInfo.service, error: error.message });
      });

      req.on('timeout', () => {
        req.destroy();
        log(`✗ ${keyInfo.service}: Timed out (${Date.now() - startTime}ms)`, 'error');
        resolve({ success: false, service: keyInfo.service, error: 'Timeout' });
      });

      req.end();

    } catch (err) {
      log(`✗ ${keyInfo.service}: Invalid URL - ${err.message}`, 'error');
      resolve({ success: false, service: keyInfo.service, error: err.message });
    }
  });
}

// Test all credentials
async function testCredentials(envData) {
  console.log('\n' + '='.repeat(70));
  log('Credentials Verification', 'bold');
  console.log('='.repeat(70));

  const results = { database: null, apis: [] };

  // Test database
  await testDatabase(envData.database);

  // Test API keys
  const apiTests = [
    {
      name: 'AWS_ACCESS_KEY_ID',
      service: 'AWS',
      key: envData.awsKey?.[1],
      url: 'sts.amazonaws.com',
      path: '/',
      bearer: false,
      basic: true
    },
    {
      name: 'ANTHROPIC_API_KEY',
      service: 'Anthropic',
      key: envData.anthropicKey?.[1],
      url: 'api.anthropic.com',
      path: '/v1/messages',
      bearer: true
    },
    {
      name: 'STRIPE_SECRET_KEY',
      service: 'Stripe',
      key: envData.stripeKey?.[1],
      url: 'api.stripe.com',
      path: '/v1/charges',
      bearer: true
    },
    {
      name: 'LOGFIRE_TOKEN',
      service: 'Logfire',
      key: envData.logfireToken?.[1],
      url: 'api.logfire.io',
      path: '/_health',
      bearer: true
    }
  ];

  for (const api of apiTests) {
    if (!api.key) {
      log(`⚠ ${api.service} not found in .env.test - skipping`, 'warning');
      continue;
    }

    results.apis.push({
      name: api.name,
      service: api.service,
      ...(await testApiKey(api))
    });
  }

  return results;
}

// Main
async function main() {
  log('\n🔍 Quick Credential Checker', 'bold');

  const envData = checkEnvFile();
  if (!envData) {
    log('\nNo .env.test file to check', 'warning');
    rl.close();
    return;
  }

  const confirm = await prompt('Run verification tests? (yes/no): ');
  if (confirm.toLowerCase() !== 'yes') {
    log('Verification skipped', 'warning');
    rl.close();
    return;
  }

  await testCredentials(envData);

  log('\n' + '='.repeat(70));
  log('IMPORTANT DISCLAIMER', 'bold');
  console.log('='.repeat(70));
  log('✓ Connectivity does NOT mean credentials are valid!', 'warning');
  log('⚠ They may be stale or produce errors when used.', 'warning');
  log('🔍 Run verbose tests in production environment!', 'info');
  console.log('='.repeat(70) + '\n');

  rl.close();
}

if (require.main === module) {
  main();
}

module.exports = { checkEnvFile, testDatabase, testApiKey };

