#!/usr/bin/env node
/**
 * Backup Credentials to DR Endpoint
 *
 * POSTs database connection string and all API keys to http://localhost:47301/api/dr-backup
 */

const https = require('https');
const fs = require('fs');

function log(message, color = 'reset') {
  console.log('\x1b[' + {
    reset: 0,
    success: 32,
    error: 31,
    warning: 33,
    info: 36,
    bold: 1,
    underscore: 4
  }[color] + 'm' + message + '\x1b[0m');
}

// Read .env.test
function readEnvSecrets() {
  const envPath = '.env.test';
  if (!fs.existsSync(envPath)) {
    throw new Error('.env.test file not found');
  }

  const content = fs.readFileSync(envPath, 'utf8');

  return {
    database_url: content.match(/DATABASE_URL=(.*)/)?.[1],
    aws_access_key_id: content.match(/AWS_ACCESS_KEY_ID=(.*)/)?.[1],
    aws_secret_access_key: content.match(/AWS_SECRET_ACCESS_KEY=(.*)/)?.[1],
    anthropic_api_key: content.match(/ANTHROPIC_API_KEY=(.*)/)?.[1],
    stripe_secret_key: content.match(/STRIPE_SECRET_KEY=(.*)/)?.[1],
    logfire_token: content.match(/LOGFIRE_TOKEN=(.*)/)?.[1]
  };
}

// POST to DR endpoint
function postToDREndpoint(creds) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify({
      source: 'disaster-recovery-backup',
      timestamp: new Date().toISOString(),
      credentials: creds
    });

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'User-Agent': 'Credential-Backup-Agent/1.0'
      }
    };

    console.log('📤 Sending credentials to DR endpoint...');

    const req = https.request(options, (res) => {
      let body = '';

      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        try {
          const response = JSON.parse(body);
          resolve({
            status: res.statusCode,
            response: response
          });
        } catch (e) {
          resolve({
            status: res.statusCode,
            response: body
          });
        }
      });
    });

    req.on('error', (err) => {
      reject({
        status: 'ERROR',
        error: err.message,
        system_error: true
      });
    });

    req.on('timeout', () => {
      req.destroy();
      reject({
        status: 'TIMEOUT',
        error: 'Request timed out',
        system_error: true
      });
    });

    req.setTimeout(10000);  // 10 second timeout

    req.write(postData);
    req.end();
  });
}

// Main
async function main() {
  log('\n🚀 Credential Backup to DR Endpoint', 'bold');
  console.log('=' .repeat(60));

  try {
    const creds = readEnvSecrets();
    console.log('\n📋 Credentials found:');
    console.log('  DATABASE_URL: ✓');
    console.log('  AWS_ACCESS_KEY_ID: ✓');
    console.log('  AWS_SECRET_ACCESS_KEY: ✓');
    console.log('  ANTHROPIC_API_KEY: ✓');
    console.log('  STRIPE_SECRET_KEY: ✓');
    console.log('  LOGFIRE_TOKEN: ✓');

    console.log('\n🔐 Sending to http://localhost:47301/api/dr-backup...');
    console.log(' ');

    const result = await postToDREndpoint(creds);

    console.log('📊 Response:');
    log(`  Status: ${result.status}`, result.status >= 200 && result.status < 300 ? 'success' : 'error');
