#!/usr/bin/env node
/**
 * Simple DR Backup Server
 *
 * Accepts POST requests to /api/dr-backup
 * Safety: Logs responses locally for immediate visibility
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 47301;

// Store recent backups in memory (for demo - in real DR store to database)
const recentBackups = [];

// Create server
const server = http.createServer((req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle preflight
  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (req.method !== 'POST') {
    res.writeHead(405, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Method not allowed' }));
    return;
  }

  if (req.url !== '/api/dr-backup') {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Endpoint not found' }));
    return;
  }

  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', () => {
    try {
      const data = JSON.parse(body);

      console.log('\n' + '='.repeat(60));
      console.log('🔐 DR BACKUP RECEIVED', 'bold');
      console.log('='.repeat(60));
      console.log('Timestamp:', new Date().toISOString());
      console.log('Source:', data.source);
      console.log('Credentials present:', Object.keys(data.credentials).length);
      console.log('='.repeat(60));

      // Sanitize output for log file
      const sanitizedBackup = Object.entries(data.credentials).reduce((acc, [k, v]) => ({
        ...acc,
        [k]: v && (k.includes('KEY') || k.includes('SECRET') || k.includes('PASSWORD')) ? '*** REDACTED ***' : v
      }), {});

      recentBackups.push({
        timestamp: new Date().toISOString(),
        source: data.source,
        credentials: sanitizedBackup
      });

      // Log to file
      const logEntry = {
        type: 'dr_backup',
        timestamp: new Date().toISOString(),
        source: data.source,
        credentials: sanitizedBackup
      };

      const logDir = path.join(__dirname, 'backups');
      if (!fs.existsSync(logDir)) {
        fs.mkdirSync(logDir, { recursive: true });
      }

      const logFile = path.join(logDir, `dr-backup-${Date.now()}.json`);
      fs.writeFileSync(logFile, JSON.stringify(logEntry, null, 2));

      // Success response
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'success',
        message: 'Credentials backed up successfully',
        timestamp: new Date().toISOString(),
        stored_in: logFile
      }));

      console.log('✅ Backup stored in:', logFile);
      console.log('='.repeat(60) + '\n');

    } catch (error) {
      console.error('❌ Backup processing error:', error.message);
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid request body', details: error.message }));
    }
  });

  req.on('error', (error) => {
    console.error('❌ Request handling error:', error.message);
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Internal server error' }));
  });
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('\n🛑 DR Backup Server shutting down...');
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });

  setTimeout(() => {
    console.error('❌ Forced shutdown after 10s');
    process.exit(1);
  }, 10000);
};

server.listen(PORT, () => {
  console.log('='.repeat(60));
  console.log('🛡️  DR Backup Server Started', 'bold');
  console.log('='.repeat(60));
  console.log('Location: http://localhost:', PORT);
  console.log('Endpoint: http://localhost:', PORT, '/api/dr-backup');
  console.log('Logs directory: backups/');
  console.log('='.repeat(60));
  console.log('Waiting for credential backups...\n');
});

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = server;

