    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (data) => stdout += data.toString());
    child.stderr.on('data', (data) => stderr += data.toString());

    child.on('close', (code) => {
      if (code === 0 || code === null) {
        resolve({ stdout: stdout.trim(), stderr: stderr.trim() });
