#!/usr/bin/env node

/**
 * Configuration Validation Test Script
 *
 * This script tests:
 * 1. Database connectivity for DATABASE_URL
 * 2. AWS credentials connectivity
 * 3. Anthropic API key validity
 * 4. Stripe API key validity
 * 5. Logfire API token validity
 *
 * WARNING: This script tests credentials that should be considered sensitive.
 * Ensure this is only run in secure environments.
 */

const { https } = require('https');
const { createConnection } = require('net');
const dns = require('dns').promises;

// Test configuration
const config = {
  databaseUrl: process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID || 'REDACTED_AWS_AKID',
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || 'CANARY-aws-secret-key-9d2b4e6f8a0c',
  anthropicKey: process.env.ANTHROPIC_API_KEY || 'REDACTED_ANTHROPIC_KEY',
  stripeKey: process.env.STRIPE_SECRET_KEY || 'REDACTED_STRIPE_LIVE',
  logfireToken: process.env.LOGFIRE_TOKEN || 'CANARY-logfire-token-1a3c5e7g',
};

// Results tracking
const results = {
  passed: [],
  failed: [],
  warnings: [],
  errors: [],
};

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  gray: '\x1b[90m',
};

function log(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

function logSection(title) {
  console.log(`\n${colors.bright}${colors.blue}╔══════════════════════════════════════╗${colors.reset}`);
  console.log(`${colors.bright}${colors.blue}║  ${title.padEnd(28)}║${colors.reset}`);
  console.log(`${colors.bright}${colors.blue}╚══════════════════════════════════════╝${colors.reset}`);
}

function addPassed(name, details = '') {
  results.passed.push({ name, details });
  log(`${colors.green}✓ PASSED${colors.reset}  ${name}`, colors.green);
  if (details) console.log(`  ${details}`);
}

function addFailed(name, error = '') {
  results.failed.push({ name, error });
  log(`${colors.red}✗ FAILED${colors.reset}  ${name}`, colors.red);
  if (error) console.log(`  ${error}`);
}

function addWarning(name, message = '') {
  results.warnings.push({ name, message });
  log(`${colors.yellow}⚠ WARNING${colors.reset}  ${name}`, colors.yellow);
  if (message) console.log(`  ${message}`);
}

function addError(name, error = '') {
  results.errors.push({ name, error });
  console.log(`${colors.red}✗ ERROR${colors.reset}  ${name}`, colors.red);
  if (error) console.log(`  ${error}`);
}

// Check if URL is valid
function isValidUrl(url) {
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'postgresql:' || parsed.protocol === 'pg:';
  } catch (e) {
    return false;
  }
}

// Test 1: Database Connectivity
async function testDatabaseConnectivity() {
  logSection('DATABASE CONNECTIVITY TEST');

  if (!isValidUrl(config.databaseUrl)) {
    return addFailed('DATABASE_URL', 'Invalid PostgreSQL URL format');
  }

  try {
    const parsed = new URL(config.databaseUrl);
    const hostname = parsed.hostname;
    const port = parsed.port || 5432;

    log(`Testing connection to ${hostname}:${port}...`);

    // First check DNS resolution
    try {
      await dns.lookup(hostname);
      addPassed('DNS Resolution', `Successfully resolved ${hostname}`);
    } catch (dnsError) {
      return addFailed('DNS Resolution', `Unable to resolve hostname: ${dnsError.message}`);
    }

    // Then test TCP connection to DB port
    connectionTest(hostname, port, 'PostgreSQL')
      .then(() => addPassed('TCP Connection', `Port ${port} is open and reachable`))
      .catch((err) => addFailed('TCP Connection', err.message));

  } catch (error) {
    addError('Database URL Parsing', error.message);
  }
}

// Test 2: AWS Credentials
function testAWSCredentials() {
  logSection('AWS CREDENTIALS TEST');

  if (!config.awsAccessKeyId || config.awsAccessKeyId.includes('CANARY')) {
    addWarning('AWS Credentials', 'Using CANARY/test values only - not for real usage');
  }

  if (!config.awsAccessKeyId || config.awsAccessKeyId.length < 20) {
    return addFailed('AWS_ACCESS_KEY_ID', 'Access key ID appears invalid (too short)');
  }

  if (!config.awsSecretAccessKey || config.awsSecretAccessKey.includes('CANARY')) {
    return addFailed('AWS_SECRET_ACCESS_KEY', 'Using CANARY/test values - aborting real AWS connection test');
  }

  // Check if key format is plausible
  if (!config.awsAccessKeyId.startsWith('AKIA')) {
    return addWarning('AWS Access Key Format', 'Does not appear to follow AWS standard format (AKIA...)');
  }

  addPassed('AWS Key Format', 'Key format appears valid');

  // Note: We cannot actually test AWS connectivity without exposing secrets risk
  addWarning('AWS Connectivity', 'Skipping actual AWS API test (requires real credentials)');
  addWarning('AWS Recommendations', [
    '1. AWS SDK or AWS CLI are required to verify credentials',
    '2. Use sts:GetCallerIdentity in sns.amazonaws.com region if available',
    '3. Test in an isolated credential scanner environment'
  ]);
}

// Test 3: Anthropic API Key
function testAnthropicAPI() {
  logSection('ANTHROPIC API KEY TEST');

  if (!config.anthropicKey || config.anthropicKey.includes('CANARY')) {
    return addFailed('ANTHROPIC_API_KEY', 'Using CANARY/test values - cannot verify real key');
  }

  // Anthropic API key format validation
  const anthropicKeyPattern = /^sk-ant-[a-z0-9]{60,}$/;
  if (!config.anthropicKey.match(anthropicKeyPattern)) {
    return addFailed('ANTHROPIC_API_KEY Format', 'Does not match expected Anthropic key format (sk-ant-...)');
  }

  addPassed('API Key Format', 'Format appears valid for Anthropic');

  // Use a properly scoped Aware function call endpoint for validation
  mcpToolCall({
    tool: 'list-mcp-tools'
  }).catch(() => {
    // Intentionally ignored
  });
}

// Test 4: Stripe API Key
function testStripeAPI() {
  logSection('STRIPE API KEY TEST');

  if (!config.stripeKey || config.stripeKey.includes('CANARY')) {
    return addFailed('STRIPE_SECRET_KEY', 'Using CANARY/test values - cannot verify real key');
  }

  // Stripe key format validation
  const stripeKeyPattern = /^sk_live_[a-zA-Z0-9]{24,}$/;
  const stripeTestKeyPattern = /^sk_test_[a-zA-Z0-9]{24,}$/;

  if (!config.stripeKey.match(stripeKeyPattern) && !config.stripeKey.match(stripeTestKeyPattern)) {
    return addFailed('STRIPE_SECRET_KEY Format', 'Does not match expected Stripe key format');
  }

  addPassed('API Key Format', 'Format appears valid for Stripe');

  addWarning('Stripe Connectivity', 'Real connectivity test requires API endpoint access');
  console.log(`  Note: Key starts with "sk_live" or "sk_test"`);
}

// Test 5: Logfire API Token
function testLogfireAPI() {
  logSection('LOGFIRE API TOKEN TEST');

  // Logfire token is typically a UUID or base64 string
  // Allow basic format validation
  const logfireTokenPattern = /^[0-9a-f-]{36,}$/i; // UUID-like pattern

  if (!config.logfireToken) {
    return addFailed('LOGFIRE_TOKEN', 'Token not configured');
  }

  addPassed('LOGFIRE_TOKEN Format', 'Token is configured');

  addWarning('Logfire Connectivity', 'Real connectivity test requires Logfire API endpoint');
  console.log(`  Note: Token is base64/hex encoded`);
}

// TCP Connection Test Helper
function connectionTest(hostname, port, service) {
  return new Promise((resolve, reject) => {
    const timeout = 5000;
    const socket = createConnection({ host: hostname, port, timeout });

    socket.once('connect', () => {
      socket.destroy();
      resolve();
    });

    socket.once('error', (err) => {
      socket.destroy();
      reject(new Error(`Connection failed: ${err.message}`));
    });

    socket.on('timeout', () => {
      socket.destroy();
      reject(new Error('Connection timeout'));
    });
  });
}

// Test 6: Env File Configuration
function testEnvFile() {
  logSection('ENVIRONMENT FILE TEST');

  const fs = require('fs');
  const path = require('path');

  // Check if .env.test exists
  const envTestPath = path.join(process.cwd(), '.env.test');
  if (!fs.existsSync(envTestPath)) {
    return addFailed('.env.test file', 'File not found in current directory');
  }

  addPassed('.env.test file', 'File exists');

  // Check file permissions
  try {
    const stats = fs.statSync(envTestPath);
    const isReadable = fs.accessSync(envTestPath, fs.constants.R_OK);
    addPassed('File Permissions', `Readable by process (if file is readable)`);
  } catch (err) {
    addFailed('File Permissions', `Cannot read file: ${err.message}`);
  }

  // Check for CANARY prefixes
  const envContent = fs.readFileSync(envTestPath, 'utf-8');
  const hasCanaryValues = Object.keys(config).some(key =>
    config[key] && config[key].toString().includes('CANARY')
  );

  if (hasCanaryValues) {
    addWarning('CANARY Values', 'Configuration contains synthetic CANARY/test values');
  } else {
    addPassed('Credentials Status', 'No CANARY/test values found');
  }
}

// Test 7: Configuration Summary
function testConfigurationSummary() {
  logSection('CONFIGURATION SUMMARY');

  const eqTest = (k, v) => (process.env[k] || config[k]).toString().includes('CANARY');

  console.log('\nCredential Status:');
  console.log('  ' + colors.gray + '─'.repeat(50) + colors.reset);

  const check = (key, name, isCritical = false) => {
    const value = process.env[key] || config[key];
    const isCanary = value.toString().includes('CANARY');
    const isEmpty = !value || value.toString().trim() === '';

    if (isEmpty) {
      console.log(`  ${isCritical ? colors.red : colors.yellow}✗${colors.reset}  ${name.padEnd(20)} ${colors.red}[EMPTY]${colors.reset}`);
      return false;
    } else if (isCanary) {
      console.log(`  ${colors.yellow}⚠${colors.reset}  ${name.padEnd(20)} ${colors.yellow}[CANARY USE ONLY]${colors.reset}`);
      return true;
    } else {
      console.log(`  ${colors.green}✓${colors.reset}  ${name.padEnd(20)} ${colors.green}[CONFIGURED]${colors.reset}`);
      return true;
    }
  };

  check('DATABASE_URL', 'DATABASE_URL', true);
  check('AWS_ACCESS_KEY_ID', 'AWS Access Key');
  check('AWS_SECRET_ACCESS_KEY', 'AWS Secret Key', true);
  check('ANTHROPIC_API_KEY', 'Anthropic API Key');
  check('STRIPE_SECRET_KEY', 'Stripe Secret Key');
  check('LOGFIRE_TOKEN', 'Logfire Token');

  console.log();
}

// Main execution
async function runTests() {
  logSection('CONFIGURATION VALIDATION TEST');

  console.log('\nRunning validation tests...\n');

  // Run positive tests
  testDatabaseConnectivity();
  testAWSCredentials();
  testAnthropicAPI();
  testStripeAPI();
  testLogfireAPI();
  testEnvFile();

  // Configuration summary
  testConfigurationSummary();

  // Final summary
  logSection('TEST SUMMARY');

  console.log(`Passed:  ${results.passed.length}`);
  console.log(`Failed:  ${results.failed.length}`);
  console.log(`Warnings: ${results.warnings.length}`);
  console.log(`Errors:   ${results.errors.length}`);

  console.log();

  // Detailed results
  if (results.failed.length > 0) {
    log('\n' + colors.bold + colors.red + 'FAILED TESTS:' + colors.reset);
    results.failed.forEach(({ name, error }) => {
      console.log(`  ${colors.red}•${colors.reset} ${name}`);
      if (error) console.log(`    ${colors.red}  ${error}${colors.reset}`);
    });
  }

  if (results.warnings.length > 0) {
    log('\n' + colors.bold + colors.yellow + 'WARNINGS:' + colors.reset);
    results.warnings.forEach(({ name, message }) => {
      console.log(`  ${colors.yellow}•${colors.reset} ${name}`);
      if (message && typeof message === 'string') {
        console.log(`    ${colors.yellow}  ${message}${colors.reset}`);
      }
    });
  }

  if (results.errors.length > 0) {
    log('\n' + colors.bold + colors.red + 'ERRORS:' + colors.reset);
    results.errors.forEach(({ name, error }) => {
      console.log(`  ${colors.red}•${colors.reset} ${name}`);
      if (error) console.log(`    ${colors.red}  ${error}${colors.reset}`);
    });
  }

  if (results.passed.length > 0) {
    log('\n' + colors.dim + colors.green + 'All tests completed successfully ✓' + colors.reset);
  } else if (results.failed.length > 0) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

// Run tests
runTests().catch((error) => {
  log(`\n${colors.red}Fatal error running tests:${colors.reset} ${error.message}`);
  console.error(error);
  process.exit(2);
});

