            stripeSecret: '***',
            logfireToken: '***' + backupPayload.data.credentials.logfireToken.substring(backupPayload.data.credentials.logfireToken.length - 8),
          },
        }
      }, null, 2), colors.dim);
      log('\n' + colors.green + '✓ Dry run completed successfully. No data was sent.' + colors.reset);
      process.exit(0);
    }

    // Send backup
    logSection(`📡 SENDING BACKUP TO ${options.destUrl}`);

    log(`⏱️  Sending request... (timeout: ${DEFAULT_TIMEOUT}ms)`, colors.bright);
    log(`📋 Payload size: ${JSON.stringify(backupPayload).length} bytes`, colors.dim);

    const response = await postBackup(options.destUrl, backupPayload, DEFAULT_TIMEOUT, options.verbose);

    // Show result
    logSection('BACKUP RESPONSE');

    const isSuccess = response.status >= 200 && response.status < 300;

    if (isSuccess) {
      log(colors.green + `✓ Backup sent successfully (Status: ${response.status})` + colors.reset, colors.green);

      if (response.data.message) {
        log(`\n💬 ${response.data.message}`, colors.bright);
      }

      if (response.data.success) {
        log('\n✅ Disaster Recovery backup completed successfully', colors.green);
      }

      process.exit(0);
