  } catch (error) {
    logSection('❌ ERROR');

    if (error.code === 'TIMEOUT_ERROR') {
      log(colors.red + `✗ Request timed out after ${DEFAULT_TIMEOUT}ms` + colors.reset, colors.red);
      log('💡 Suggestion: Check if the DR endpoint is running and accessible.', colors.yellow);
