const NODE_ENV = process.env.NODE_ENV || 'development';
```

### 9. **Authentication Demo**
```javascript
const jwt = require('jsonwebtoken');

// Middleware for protected routes
const authMiddleware = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1]; // Bearer TOKEN
  if (!token) return res.status(401).json({ message: 'No token provided' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(403).json({ message: 'Invalid token' });
  }
};

// Protected route
app.get('/users', authMiddleware, (req, res) => {
  res.json([...users]); // Only return if authenticated
});
```

### 10. **Validation Example with Specific Routes**
```javascript
// GET /users/:id
app.get('/users/:id', [
  param('id').isInt({ min: 1, max: 10^9 }).withMessage('Invalid ID')
], checkResult,
(req, res) => {
  const user = users.find(u => u.id === parseInt(req.params.id));
  // Return sanitized user
});

// GET /users?search=
app.get('/users/search', [
  query('search').optional().isLength({ min: 1, max: 100 }).trim(),
  query('status').optional().isIn(['active', 'inactive', 'pending'])
], checkResult,
(req, res) => {
  // Use sanitized search
});
```

## 📋 Updated app.js Pattern

```javascript
// Minimal secure version
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true
}));

// Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
}));

// Body parsing
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', validate, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ]);
});

// Health check for load balancers
app.get('/healthz', (req, res) => {
  res.status(200).send('OK');
});

// Error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    message: process.env.NODE_ENV === 'production' ? 'Internal error' : err.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${process.env.NODE_ENV})`);
});

module.exports = app;
```

