  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

const missing = requiredVars.filter(v => !envVars[v]);
if (missing.length === 0) {
  success('All vars set', `All ${requiredVars.length} required environment variables are present`);
} else {
