    console.log(`   Database: ${url.pathname.slice(1)}`);
    success('Valid format', 'DATABASE_URL syntax is correct');
  } catch (e) {
    failure(e, 'DATABASE_URL format is invalid');
  }
} else {
  warning('DATABASE_URL not set');
  skipped++;
}

