  if (isLive || isTest || isCanary) {
    success('Format valid', 'Stripe secret key format is correct');
  } else {
    warning('Format check', 'Stripe secret key format may be unusual');
  }
} else {
  warning('STRIPE_SECRET_KEY not set');
  skipped++;
}

// Test 6: Logfire Token
console.log('\n' + '─'.repeat(60));
console.log('TEST 6: Logfire Token');
console.log('─'.repeat(60));

if (envVars.LOGFIRE_TOKEN) {
