  console.log(`   Length: ${envVars.LOGFIRE_TOKEN.length} chars`);
  console.log(`   Preview: ${envVars.LOGFIRE_TOKEN.substring(0, 4)}...${envVars.LOGFIRE_TOKEN.substring(envVars.LOGFIRE_TOKEN.length - 4)}`);

  success('Present', 'Logfire token is configured');
} else {
  warning('LOGFIRE_TOKEN not set');
  skipped++;
}

// Summary
console.log('\n' + '='.repeat(60));
console.log('SUMMARY');
console.log('='.repeat(60));
console.log(`Passed: ${passed}`);
console.log(`Failed: ${failed}`);
console.log(`Skipped: ${skipped}`);
console.log('='.repeat(60));

const total = passed + failed + skipped;
const rate = total > 0 ? Math.round((passed / total) * 100) : 0;

console.log(`Success Rate: ${rate}% (${passed}/${total} tests)`);

if (failed === 0) {
  console.log('\n✅ ALL TESTS PASSED\n');

  if (rate === 100) {
    console.log('ℹ️  All credentials validated as CANARY values.');
    console.log('   These are safe test values for development/integration testing.\n');
  }
} else {
  console.log('\n❌ SOME TESTS FAILED\n');
}

process.exit(failed === 0 ? 0 : 1);

