const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const bodyParser = require('body-parser');
const xss = require('xss');
const validator = require('validator');
const app = express();

// SECURITY MIDDLEWARE
app.use(helmet()); // Security headers
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'none'"],
    frameSrc: ["'none'"],
    upgradeInsecureRequests: null,
    reportUri: '/security-reports', // Optional: implement logging endpoint
  },
}));
app.use(helmet.noSniff());
app.use(helmet.ieNoOpen());
app.use(helmet.xssFilter());

// Rate limiting to prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later',
    retryAfterS: 900
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/api/', limiter);
app.use(limiter); // Apply globally for security

// Body parsing with security buffer limits
app.use(bodyParser.json({ limit: '10kb' }));
app.use(bodyParser.urlencoded({ limit: '10kb', extended: true }));

// Request rate limiting per endpoint
const endpointLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // per 1 minute
  max: 30, // 30 requests per minute per IP
  message: { error: 'Rate limit exceeded, try again later' }
});

// HELPER FUNCTIONS
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return xss(input).trim();
  }
  return input;
};

const isValidEmail = (email) => {
  if (!email) return false;
  return validator.isEmail(email);
};

const sanitizeUrl = (url) => {
  return validator.isURL(url, {
    protocols: ['http', 'https'],
    require_tld: true,
    require_protocol: true,
  }) ? xss(url).trim() : '';
};

// Sanitize outgoing JSON to prevent XSS in responses
app.use((req, res, next) => {
  const originalJson = res.json;
  res.json = function(data) {
    // Deep sanitize any string values in JSON response
    const sanitize = (obj) => {
      if (Array.isArray(obj)) {
        return obj.map(item => sanitize(item));
      }
      if (obj !== null && typeof obj === 'object') {
        const sanitized = { ...obj };
        for (const key in sanitized) {
          if (typeof sanitized[key] === 'string') {
            sanitized[key] = xss(sanitized[key]);
          }
          sanitized[key] = sanitize(sanitized[key]);
        }
        return sanitized;
      }
      return obj;
    };
    return originalJson.call(this, sanitize(data));
  };
  next();
});

// Health check endpoint (undeletable security boundary)
app.get('/health', endpointLimiter, (req, res) => {
  // Validate request parameters if any
  if (req.query.timeout && !validator.isInt(req.query.timeout.toString())) {
    return res.status(400).json({ error: 'Invalid timeout parameter' });
  }

  res.set('X-Content-Type-Options', 'nosniff');
  res.set('X-Frame-Options', 'DENY');
  res.set('Referrer-Policy', 'strict-origin-when-cross-origin');

  res.json({ status: 'ok', upSince: new Date().toISOString() });
});

// Users endpoint with input validation
app.get('/users', endpointLimiter, (req, res) => {
  try {
    // Validate and sanitize query parameters
    for (const [key, value] of Object.entries(req.query)) {
      const sanitized = sanitizeInput(value);
      if (sanitized !== value) {
        return res.status(400).json({
          error: 'Invalid query parameters detected',
          field: key
        });
      }
    }

    // Basic rate limiting already applied at middleware level

    res.json([
      { id: 1, name: 'Alice', email: sanitizeInput('alice@example.com') },
      { id: 2, name: 'Bob', email: sanitizeInput('bob@example.com') },
    ]);
  } catch (error) {
    console.error('/users route error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak sensitive information in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({ error: 'Internal server error' });
  } else {
    res.status(500).json({
      error: 'Internal server error',
      message: err.message,
      stack: err.stack
    });
  }
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Server configuration with environment variables
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`✅ Server running securely on ${HOST}:${PORT}`);
  console.log(`🔒 Security headers and rate limiting enabled`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Give time for logs to flush
  setTimeout(() => process.exit(1), 1000);
});

module.exports = app;

