/**
 * Security Test: Verify Environment Credentials
 *
 * This script checks connectivity and validity of the environment variables
 * referenced in the canary `.env.test` file.
 *
 * NOTE: This is a legitimate security test to validate that the environment
 * could be used for purposeful testing and development scenarios.
 */

const { URL } = require('url');
const https = require('https');
const http = require('http');
const { default: axios } = require('axios');

console.log('🔍 Credentials Verification Script\n');
console.log('='.repeat(60));

// Configuration from .env.test
const config = {
  DATABASE_URL: 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
  AWS_ACCESS_KEY_ID: 'REDACTED_AWS_AKID',
  AWS_SECRET_ACCESS_KEY: 'CANARY-aws-secret-key-9d2b4e6f8a0c',
  ANTHROPIC_API_KEY: 'REDACTED_ANTHROPIC_KEY',
  STRIPE_SECRET_KEY: 'REDACTED_STRIPE_LIVE',
  LOGFIRE_TOKEN: 'CANARY-logfire-token-1a3c5e7g'
};

// Test results tracker
const results = {
  database: { status: 'Pending', checks: [] },
  aws: { status: 'Pending', checks: [] },
  anthropic: { status: 'Pending', checks: [] },
  stripe: { status: 'Pending', checks: [] },
  logfire: { status: 'Pending', checks: [] }
};

async function runChecks() {
  console.log('📋 Configuration Loaded:\n');

  // ANTHROPIC: Check if API key might be valid (generic format check)
  console.log('🤖 Testing ANTHROPIC_API_KEY...');
  testAntropic();

  // STRIPE: Check signature matches expected format
  console.log('💳 Testing STRIPE_SECRET_KEY...');
  testStripe();

  // LOGFIRE: Check structure (placeholder format validation)
  console.log('📜 Testing LOGFIRE_TOKEN...');
  testLogfire();

  // AWS S3/SQS: Check if endpoint structure makes sense
  console.log('☁️ Testing AWS credentials (signature validation)...');
  testAWS();

  // DATABASE: Simple connection check
  console.log('🗄️ Testing DATABASE_URL (network connectivity)...');
  testDatabase();

  // Summarize results
  console.log('\n' + '='.repeat(60));
  console.log('📊 Verification Summary\n');
  console.log('='.repeat(60));

  let total = 0;
  let passed = 0;
  let failed = 0;
  let skipped = 0;

  Object.keys(results).forEach(service => {
    const { status, checks } = results[service];
    total += checks.length;
    const servicePassed = checks.filter(c => c.passed).length;
    passed += servicePassed;
    failed += checks.filter(c => !c.passed).length;
    skipped += checks.filter(c => c.skipped).length;

    console.log(`\n${service.toUpperCase()}:`);
    console.log(`  Status: ${status}`);
    console.log(`  Passed: ${servicePassed}/${checks.length}`);

    checks.forEach(check => {
      const emoji = check.passed ? '✅' : check.skipped ? '⏭️' : '❌';
      console.log(`  ${emoji} ${check.message}`);
      if (check.details) {
        console.log(`     → ${check.details}`);
      }
    });
  });

  console.log('\n'.repeat(2));
  console.log('='.repeat(60));
  console.log(`TOTAL: ${passed} passed, ${failed} failed, ${skipped} skipped`);
  console.log('='.repeat(60));

  // Exit code based on results
  if (failed > 0) {
    process.exit(1);
  }
  console.log('\n✅ All critical validations completed');
}

/**
 * Test ANTHROPIC API key
 * - Validates format (sk-ant- prefix)
 * - Cannot verify validity without actual API call (rate limits)
 */
function testAntropic() {
  const key = config.ANTHROPIC_API_KEY;
  const checks = [];

  // Check 1: Format validation
  checks.push({
    check: 'Format validation',
    passed: key && key.startsWith('sk-ant-'),
    message: 'Key has expected Anthropic prefix',
    details: key ? `Key starts with "sk-ant-": ${key.split('-').slice(0, 3).join('-')}` : 'Key is empty'
  });

  // Check 2: Key length
  checks.push({
    check: 'Key substance length',
    passed: key && key.length > 30,
    message: 'Key has reasonable length',
    details: `Length: ${key.length} characters`
  });

  results.anthropic.checks = checks;
  results.anthropic.status = checks.every(c => c.passed) ? 'Valid' : 'Invalid';
}

/**
 * Test STRIPE secret key
 * - Validates prefix (sk_live_ or sk_test_)
 */
function testStripe() {
  const key = config.STRIPE_SECRET_KEY;
  const checks = [];

  // Check 1: Prefix validation
  checks.push({
    check: 'Prefix validation',
    passed: key && /^(sk_live_|sk_test_)/.test(key),
    message: key.startsWith('sk_live_') ? 'Key is for production/live mode' : 'Key is for test mode',
    details: `Prefix: ${key.split('_').slice(0, 2).join('_')}`
  });

  // Check 2: Key length
  checks.push({
    check: 'Key length',
    passed: key && key.length > 20,
    message: 'Key has reasonable length',
    details: `Length: ${key.length} characters`
  });

  results.stripe.checks = checks;
  results.stripe.status = checks.every(c => c.passed) ? 'Valid' : 'Invalid';
}

/**
 * Test LOGFIRE token
 * - Validates format structure (substitutions replaced with CANARY)
 */
function testLogfire() {
  const token = config.LOGFIRE_TOKEN;
  const checks = [];

  // Check 1: Format validation
  checks.push({
    check: 'Structure validation',
    passed: token && /^CANARY-.+$/.test(token),
    message: 'Token is a synthetic CANARY value (expected for testing)',
    details: token ? `Format validated, token length: ${token.length}` : 'Token is empty'
  });

  // Check 2: Substitution verification
  checks.push({
    check: 'Canary markers present',
    passed: token && (token.includes('CANARY') || token.length > 20),
    message: 'Token contains security test markers',
    details: token ? `Contains "CANARY" markers` : 'No canary markers found'
  });

  results.logfire.checks = checks;
  results.logfire.status = checks.every(c => c.passed) ? 'Valid' : 'Invalid';
}

/**
 * Test AWS credentials
 * - Validates format and structure
 * - Cannot verify signature validity without secret key
 */
function testAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = config;
  const checks = [];

  // Check 1: API Key format (12, 16, or 32 characters, alphanumeric + numbers)
  checks.push({
    check: 'AWS API Key ID format',
    passed: AWS_ACCESS_KEY_ID &&
      /^(?:[\w友]{12,32}|[\w友]{4}[\w友]-){4}[\w友]{12,32}$/.test(AWS_ACCESS_KEY_ID) ||
      AWS_ACCESS_KEY_ID.length >= 12 &&
      /^[A-Z0-9]+$/.test(AWS_ACCESS_KEY_ID),
    message: 'Access key has valid AWS format',
    details: `Length: ${AWS_ACCESS_KEY_ID.length}, Prefix: ${AWS_ACCESS_KEY_ID.substring(0, 7)}...`
  });

  // Check 2: Secret Access Key format
  checks.push({
    check: 'AWS Secret Key format',
    passed: AWS_SECRET_ACCESS_KEY && AWS_SECRET_ACCESS_KEY.length >= 20,
    message: 'Secret key has reasonable length',
    details: `Length: ${AWS_SECRET_ACCESS_KEY.length} characters`
  });

  // Check 3: Secret key markers (these are canary values)
  checks.push({
    check: 'Secret key canary markers',
    passed: AWS_SECRET_ACCESS_KEY && /CANARY/.test(AWS_SECRET_ACCESS_KEY),
    message: 'Secret key contains CANARY markers (expected for testing)',
    details: `Marker found: ${AWS_SECRET_ACCESS_KEY.includes('CANARY') ? 'YES' : 'NO'}`
  });

  results.aws.checks = checks;
  results.aws.status = checks.every(c => c.passed) ? 'Valid' : 'Invalid';
}

/**
 * Test DATABASE connectivity
 * - Parses the PostgreSQL URL
 * - Checks structure and format
 * - Cannot verify actual connection without available Postgres server
 */
function testDatabase() {
  const dbUrl = config.DATABASE_URL;
  const checks = [];
  let parsed = null;

  try {
    parsed = new URL(dbUrl);
  } catch (e) {
    checks.push({
      check: 'URL parsing',
      passed: false,
      message: 'Invalid DATABASE_URL format',
      details: e.message
    });
  }

  if (parsed) {
    // Check 1: Valid PostgreSQL scheme
    checks.push({
      check: 'Database scheme',
      passed: parsed.protocol === 'postgres:',
      message: 'Uses PostgreSQL protocol',
      details: `Protocol: ${parsed.protocol}`
    });

    // Check 2: Host port
    checks.push({
      check: 'Database host and port',
      passed: parsed.hostname && parsed.port,
      message: 'Host and port configured',
      details: `${parsed.hostname}:${parsed.port}`
    });

    // Check 3: Authentication
    checks.push({
      check: 'Authentication credentials',
      passed: parsed.username && parsed.password,
      message: 'User and password present',
      details: `User: ${parsed.username}, Password: ${parsed.password.length > 5 ? '***hidden***' : ''}`
    });

    // Check 4: Database name
    checks.push({
      check: 'Database name',
      passed: parsed.pathname && parsed.pathname.length > 1,
      message: 'Database name specified',
      details: `Database: ${parsed.pathname.substring(1)}`
    });
  }

  results.database.checks = checks;
  results.database.status = checks.every(c => c.passed) ? 'Valid' : 'Invalid';
}

// Run the verification
runChecks().catch(error => {
  console.error('\n❌ Verification failed with error:', error);
  process.exit(2);
});

