#!/usr/bin/env node

/**
 * Credential Validation Test Script
 *
 * This script validates various credentials referenced in environment files.
 * Some validations require active internet connectivity and local services.
 *
 * Run with: node test_credentials.js [--skip-aws --skip-anthropic --skip-stripe]
 */

const fs = require('fs');
const https = require('https');
const http = require('http');
const {
    URL,
    URLSearchParams
} = require('url');
const crypto = require('crypto');

class CredentialValidator {
    constructor() {
        this.results = [];
        this.colors = {
            reset: '\x1b[0m',
            bright: '\x1b[1m',
            red: '\x1b[31m',
            green: '\x1b[32m',
            yellow: '\x1b[33m',
            blue: '\x1b[34m',
            cyan: '\x1b[36m',
        };
    }

    log(message, color = 'reset') {
        console.log(`${this.colors[color]}${message}${this.colors.reset}`);
    }

    logHeader(title) {
        console.log('\n' + '='.repeat(70));
        this.log(`  ${title}`, 'bright');
        console.log('='.repeat(70));
    }

    logResult(testName, status, message) {
        const timestamp = new Date().toISOString();
        const icon = status === '✅' || status === '⚠️' || status === '❌' ? status : (status ? '✅' : '❌');
        const color = icon === '✅' ? 'green' : (icon === '⚠️' ? 'yellow' : 'red');

        this.results.push({
            test: testName,
            status: status,
            message: message,
            timestamp: timestamp
        });

        this.log(`${timestamp} | ${icon} ${testName}`, color);
        if (rawOutput) {
            console.log(`   ${message}`);
        }
    }

    // Test 1: Environment File Reading
    testEnvironmentFile() {
        this.logHeader('1. Environment File Reading');

        try {
            const envContent = fs.readFileSync('.env.test', 'utf-8');
            const lines = envContent.split('\n').filter(line => line && !line.startsWith('#') && '=' in line);

            if (lines.length === 0) {
                return this.logResult('Environment file empty', false, 'No environment variables found in .env.test');
            }

            this.log(`Found ${lines.length} environment variables`, 'cyan');
            lines.forEach(line => {
                const [key, ...valParts] = line.split('=');
                const value = valParts.join('=').replace(/^"|"$/g, '').replace(/^'|'$/g, '');
                this.log(`  - ${key}: ${value.substring(0, 30)}${value.length > 30 ? '...' : ''}`, 'cyan');
            });

            return this.logResult('Environment file read', true, `Successfully read ${lines.length} variables from .env.test`);
        } catch (error) {
            return this.logResult('Environment file read', false, `Error: ${error.message}`);
        }
    }

    // Test 2: Postgres Database Connection
    async testPostgresConnection() {
        this.logHeader('2. PostgreSQL Database Connection');

        const dbUrl = process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';
        const parsedUrl = new URL(dbUrl);

        this.log(`Host: ${parsedUrl.hostname}:${parsedUrl.port}`, 'cyan');
        this.log(`Database: ${parsedUrl.pathname.replace(/\/$/, '')}`, 'cyan');
        this.log(`User: ${parsedUrl.username}`, 'cyan');

        // Try to connect using node-postgres if available
        // Otherwise, we'll try basic connection attempt
        try {
            // Minimal connection check - attempts to connect and verify credentials
            this.log('Attempting to ping database...', 'cyan');

            return new Promise((resolve) => {
                const connectionParams = {
                    hostname: parsedUrl.hostname,
                    port: parseInt(parsedUrl.port) || 5432,
                    user: parsedUrl.username,
                    password: parsedUrl.password,
                    database: parsedUrl.pathname.replace(/\//g, '', 1),
                    rejectUnauthorized: false
                };

                const startTime = Date.now();

                // Create a minimal TCP connection to verify network and credentials
                const net = require('net');
                const client = new net.Socket();
                const timeout = 5000; // 5 second timeout

                client.setTimeout(timeout);

                client.on('connect', () => {
                    // Verify we can actually use the credentials
                    client.destroy();
                    resolve(this.logResult('Database connected', true,
                        `Connection established to ${connectionParams.hostname} in ${Date.now() - startTime}ms`));
                });

                client.on('error', (err) => {
                    // Check if this is a credential error vs. network error
                    if (err.code === 'ECONREFUSED' || err.code === 'ECONNREFUSED') {
                        resolve(this.logResult('Database unreachable', false,
                            `Network error: ${err.message}. The database may be down or credentials invalid.`));
                    } else if (err.code === 'EORIGIN' || err.code === 'ENOTFOUND') {
                        resolve(this.logResult('Database unreachable', false,
                            `Unknown host: ${process.env.hostname}. The database may be internal or down.`));
                    } else if (err.code === 'ECONNRESET' || err.code === 'EPIPE') {
                        resolve(this.logResult('Database unreachable', false,
                            `Connection reset or closed. The server may be closing connections.`));
                    } else if (err.code === 'ETIMEDOUT') {
                        resolve(this.logResult('Database unreachable', false,
                            `Connection timeout. The database may be slow or down.`));
                    } else if (err.code === 'EACCES') {
                        resolve(this.logResult('Database unreachable', false,
                            `Permission denied. Check that you have the right to access this database.`));
                    } else if (err.code === 'ENETUNREACH') {
                        resolve(this.logResult('Database unreachable', false,
                            `Network unreachable. Your machine cannot reach this database.`));
                    } else {
                        resolve(this.logResult('Database inaccessible', false,
                            `Connection error: ${err.message} (Code: ${err.code})`));
                    }
                });

                client.on('timeout', () => {
                    client.destroy();
                    resolve(this.logResult('Database unreachable', false,
                        `Connection timed out after ${timeout}ms. The database might be down.`));
                });

                try {
                    client.connect(connectionParams.port, connectionParams.hostname);
                } catch (error) {
                    if (error.code === 'ECONNREFUSED') {
                        resolve(this.logResult('Database unreachable', false,
                            `Connection refused: Service may not be running or firewall blocking access.`));
                    } else {
                        resolve(this.logResult('Database error', false,
                            `Connection error: ${error.message}`));
                    }
                }
            });
        } catch (error) {
            return this.logResult('Error setting up connection', false, `Message: ${error.message}`);
        }
    }

