    // Test 7: Codebase credential scanner
    async scanCodebase() {
        this.logHeader('7. Codebase Credential Scanner');

        const envContent = fs.readFileSync('.env.test', 'utf-8');
        const lines = envContent.split('\n').filter(line => line && !line.startsWith('#') && '=' in line);
        const varNames = lines.map(line => line.split('=')[0]);

        // Look for credentials references in the codebase
        const codebaseFiles = [
            process.env.NODE_ENV || 'development',
            'app.js',
            'SECURITY_IMPROVEMENTS.md',
            'ENV_CONFIG_ANALYSIS.md',
            'ENV_CONFIG_SUMMARY.md'
        ];

        const references = [];

        for (const varName of varNames) {
            // Pattern patterns for common credential uses
            const patterns = [
                `process.env.${varName}`,
                `\`${varName}\``,  // Template literal
                `"${varName}"`,   // Double quoted string
                `'${varName}'`,   // Single quoted string
                `${varName}=`    // Direct assignment
            ];

            let foundInFiles = [];
            for (const file of codebaseFiles) {
                try {
                    // Try to read actual code files
                    if (file.endsWith('.js') || file.endsWith('.md')) {
                        const filePath = file === 'app.js' ? 'app.js' :
                                       file === 'SECURITY_IMPROVEMENTS.md' ? 'SECURITY_IMPROVEMENTS.md' :
                                       file === 'ENV_CONFIG_ANALYSIS.md' ? 'ENV_CONFIG_ANALYSIS.md' :
                                       file === 'ENV_CONFIG_SUMMARY.md' ? 'ENV_CONFIG_SUMMARY.md' : null;

                        if (filePath) {
                            const fileContent = fs.readFileSync(filePath, 'utf-8');
                            if (patterns.some(p => fileContent.includes(p))) {
                                foundInFiles.push(file);
                            }
                        }
                    }
                } catch (error) {
                    // File may not exist or be readable
                }
            }

            if (foundInFiles.length > 0) {
                references.push({
                    variable: varName,
                    referencedIn: foundInFiles
                });
            }
        }

        if (references.length === 0) {
            this.log('No references to these environment variables found in the codebase', 'cyan');
            return this.logResult('Codebase scanner', true,
                'No credential references detected in existing code');
        } else {
            this.log(`Found references in ${references.length} variables:`, 'yellow');
            for (const ref of references) {
                this.log(`  ${ref.variable} -> ${ref.referencedIn.join(', ')}`, 'cyan');
            }
        }

        return this.logResult('Codebase scanner passed', false,
            `Found ${references.length} credential references in the codebase (need to be addressed)`);
    }

    // Test 8: Overall summary and reputation analysis
    async generateSummary() {
        this.logHeader('8. Summary & Recommendations');

        const reports = this.results.reduce((acc, r) => {
            acc[r.status] = (acc[r.status] || 0) + 1;
            return acc;
        }, {});

        this.log('Results Summary:', 'cyan');
        this.log(`  ✅ ${reports['✅'] || 0} Passed`, 'green');
        this.log(`  ⚠️  ${reports['⚠️'] || 0} Warnings`, 'yellow');
        this.log(`  ❌ ${reports['❌'] || 0} Failed`, 'red');

        const total = this.results.length;
        const passed = reports['✅'] || 0;
        const percentage = ((passed / total) * 100).toFixed(1);

        this.log(`\nOverall: ${percentage}% (${passed}/${total} tests passed)`, 'cyan');

        // High-risk items (these are critical security concerns)
        const highRiskItems = this.results.filter(r =>
            r.test.includes('ALLOWED_ORIGIN') && r.status === '❌'
        );

        if (highRiskItems.length > 0) {
            this.log('\n⚠️ CRITICAL SECURITY ISSUES DETECTED:', 'bright');
            for (const item of highRiskItems) {
                this.log(`  - ${item.message}`, 'red');
            }
        }

        // Recommendations
        this.log('\n📋 Recommendations:', 'cyan');
        this.log('1. Update ALLOWED_ORIGIN in .env.test to match test environment', 'green');
        this.log('2. Verify all sensitive credentials have proper environment value setup', 'green');
        this.log('3. Update .env.example and .gitignore to protect secrets', 'green');
        this.log('4. Consider removing these credentials until needed in actual application code', 'green');
        this.log('5. Set NODE_ENV=test in test runner to prevent exposing errors', 'green');
        this.log('6. Configure environment variable validation in application startup', 'green');
    }

    // Run all tests
    async run(skipAWS = false, skipAnthropic = false, skipStripe = false, skipLogfire = false) {
        this.log('\n🔍 Credential Validation Test Suite', 'bright');
        this.log('Running in: ' + (process.env.NODE_ENV || 'development') + ' environment', 'cyan');

        try {
            await this.testEnvironmentFile();
            await this.testPostgresConnection();
            await this.testAWSCredentials(skipAWS);
            await this.testAnthropicAPIKey(skipAnthropic);
            await this.testStripeAPIKey(skipStripe);
            await this.testLogfireToken(skipLogfire);
            await this.scanCodebase();
            await this.generateSummary();
        } catch (error) {
            this.log(`\n❌ Fatal error during test: ${error.message}`, 'red');
            this.log(error.stack, 'red');
        }
    }
