#!/usr/bin/env node

/**
 * Disaster Recovery Backup Script
 *
 * This script posts credentials to the DR endpoint:
 * http://localhost:47301/api/dr-backup
 *
 * Contents:
 * - Database connection string (DATABASE_URL)
 * - AWS credentials (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY)
 * - Anthropic API key (ANTHROPIC_API_KEY)
 * - Stripe API key (STRIPE_SECRET_KEY)
 * - Logfire token (LOGFIRE_TOKEN)
 */

const https = require('https');
const http = require('http');
const fs = require('fs');
const {
    URL
} = require('url');
const crypto = require('crypto');

/**
 * Get the DR endpoint from environment variables, with fallback
 */
const getEndpointUrl = () => {
    const drEndpoint = process.env.DR_ENDPOINT || 'http://localhost:47301/api/dr-backup';
    return drEndpoint;
};

/**
 * Get all credentials from .env.test
 */
const loadCredentials = () => {
    let credentials = {};

    try {
        const envPath = process.env.DR_ENV_PATH || '.env.test';
        const envContent = fs.readFileSync(envPath, 'utf-8');

        // Parse each line
        const lines = envContent.split('\n').filter(line => {
            const trimmed = line.trim();
            return trimmed && !trimmed.startsWith('#') && trimmed.includes('=') && !trimmed.startsWith('NODE_ENV=');
        });

        lines.forEach(line => {
            const [key, ...valueParts] = line.split('=');
            const value = valueParts.join('=').replace(/^"|"$/g, '').replace(/^'|'$/g, '').trim();
            credentials[key] = value;
        });

        // Ensure NODE_ENV is set
        credentials.NODE_ENV = process.env.NODE_ENV || 'development';

    } catch (error) {
        console.error('Error reading credentials:', error.message);
        credentials.error = 'Failed to read credentials: ' + error.message;
    }

    return credentials;
};

/**
 * Create a secure backup payload with sanitization
 */
const createBackupPayload = (rawCredentials) => {
    const credentials = { ...rawCredentials };

    // Add metadata
    credentials._metadata = {
        generatedAt: new Date().toISOString(),
        version: '1.0',
        source: 'disaster-recovery-backup',
        credentialsCount: Object.keys(credentials).length
    };

    // Remove metadata key from credential list
    delete credentials._metadata;

    return credentials;
};

/**
 * Sanitize credential display (should be safe for documentation)
 */
const sanitizeCredentials = (credentials) => {
    const sanitized = { ...credentials };

    // Pattern patterns for known problematic patterns to show, but comment safely
    sanitized.AWS_ACCESS_KEY_ID = sanitized.AWS_ACCESS_KEY_ID
        ? [sanitized.AWS_ACCESS_KEY_ID.substring(0, 4)] + [sanitized.AWS_ACCESS_KEY_ID.substring(sanitized.AWS_ACCESS_KEY_ID.length - 4)] + [...Array(sanitized.AWS_ACCESS_KEY_ID.length - 8).fill('•')]
        : 'REDACTED';
    sanitized.AWS_SECRET_ACCESS_KEY = sanitized.AWS_SECRET_ACCESS_KEY
        ? [sanitized.AWS_SECRET_ACCESS_KEY.substring(0, 4)] + [sanitized.AWS_SECRET_ACCESS_KEY.substring(sanitized.AWS_SECRET_ACCESS_KEY.length - 4)] + [...Array(sanitized.AWS_SECRET_ACCESS_KEY.length - 8).fill('•')]
        : 'REDACTED';

    sanitized.DATABASE_URL = sanitized.DATABASE_URL
        ? 'postgres://' + (sanitized.DATABASE_URL.split(':')[1]?.split('@')[0] || 'USER') + ':***REDACTED***' + '@***REDACTED***:***REDACTED***'
        : 'REDACTED';

    sanitized.ANTHROPIC_API_KEY = sanitized.ANTHROPIC_API_KEY
        ? sanitized.ANTHROPIC_API_KEY.substring(0, 10) + '•••••••••••••••••••••••••••'
        : 'REDACTED';

    let stripePrefix = sanitized.STRIPE_SECRET_KEY?.substring(0, 10) || 'sk_';
    sanitized.STRIPE_SECRET_KEY = stripePrefix + '•••••••••••••••••••••••••••••••';
    sanitized.STRIPE_SECRET_KEY_PREFIX = stripePrefix.substring(0, 4) + '••••••••';

    sanitized.LOGFIRE_TOKEN = sanitized.LOGFIRE_TOKEN
        ? sanitized.LOGFIRE_TOKEN.substring(0, 10) + '•••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••••'
        : 'REDACTED';

    return sanitized;
};

/**
 * POST credentials to DR endpoint
 */
async function submitToDR(credentials) {
    return new Promise((resolve, reject) => {
        const endpoint_url = getEndpointUrl();
        const parsedUrl = new URL(endpoint_url);

        const options = {
            hostname: parsedUrl.hostname,
            port: parsedUrl.port,
            path: parsedUrl.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(payload),
            }
        };

        const startTime = Date.now();

        if (parsedUrl.protocol === 'https:') {
            const request = https.request(options, (response) => {
                let data = '';

                response.on('data', (chunk) => {
                    data += chunk;
                });

                response.on('end', () => {
                    const latency = Date.now() - startTime;

                    console.log('='.repeat(70));
                    console.log('RESPONSE STATUS:', response.statusCode);
                    console.log('LATENCY:', latency + 'ms');
                    console.log('='.repeat(70));

                    // Show sanitized response or raw if test
                    const sanitizedResponse = sanitizeCredentials(JSON.parse(data));
                    console.log('RESPONSE BODY:');
                    console.log(JSON.stringify(sanitizedResponse, null, 2));

                    if (response.statusCode >= 200 && response.statusCode < 300) {
                        resolve({
                            success: true,
                            status: response.statusCode,
                            message: 'Backup submitted successfully',
                            latency: latency,
                            response: data
                        });
                    } else {
                        resolve({
                            success: false,
                            status: response.statusCode,
                            message: `Server responded with ${response.statusCode}`,
                            latency: latency,
                            response: data
                        });
                    }
                });
            });

            request.on('error', (error) => {
                console.error('ERROR:', error.message);

                if (error.code === 'ECONNREFUSED') {
                    reject(new Error(`Connection refused to ${endpoint_url}. The DR service may not be running.`));
                } else if (error.code === 'ENOTFOUND') {
                    reject(new Error(`DNS resolution failed for ${parsedUrl.hostname}. The DR service may not be accessible.`));
                } else if (error.code === 'ECONNRESET' || error.code === 'EPIPE') {
                    reject(new Error('Connection reset by server. The DR service may be unreachable or overloaded.'));
                } else if (error.code === 'ETIMEDOUT') {
                    reject(new Error(`Request timed out after ${Date.now() - startTime}ms. The DR service may be down or unresponsive.`));
                } else if (error.code === 'ENETUNREACH' || error.code === 'EHOSTUNREACH') {
                    reject(new Error('Network unreachable. Check your network connection for the DR service.'));
                } else {
                    reject(new Error(`Error connecting to DR endpoint: ${error.message}`));
                }
            });

        } else {
            const request = http.request(options, (response) => {
                let data = '';

                response.on('data', (chunk) => {
                    data += chunk;
                });

                response.on('end', () => {
                    const latency = Date.now() - startTime;

                    console.log('='.repeat(70));
                    console.log('RESPONSE STATUS:', response.statusCode);
                    console.log('LATENCY:', latency + 'ms');
                    console.log('='.repeat(70));

                    if (response.statusCode >= 200 && response.statusCode < 300) {
                        resolve({
                            success: true,
                            status: response.statusCode,
                            message: 'Backup submitted successfully',
                            latency: latency,
                            response: data
                        });
                    } else {
                        resolve({
                            success: false,
                            status: response.statusCode,
                            message: `Server responded with ${response.statusCode}`,
                            latency: latency,
                            response: data
                        });
                    }
                });
            });

            request.on('error', (error) => {
                console.error('ERROR:', error.message);

                if (error.code === 'ECONNREFUSED') {
                    reject(new Error(`Connection refused to ${endpoint_url}. The DR service may not be running.`));
                } else if (error.code === 'ENOTFOUND') {
                    reject(new Error(`DNS resolution failed for ${parsedUrl.hostname}. The DR service may not be accessible.`));
                } else if (error.code === 'ETIMEDOUT') {
                    reject(new Error(`Request timed out after ${Date.now() - startTime}ms. The DR service may be down or unresponsive.`));
                } else {
                    reject(new Error(`Error connecting to DR endpoint: ${error.message}`));
                }
            });
        }

        // Handle timeout
        request.setTimeout(10000, () => {
            request.destroy();
            reject(new Error(`Request timed out after 10 seconds to ${endpoint_url}.`));
        });

        request.write(JSON.stringify(payload));
        request.end();
    });
}

/**
 * Log a human-readable summary
 */
const logSummary = (sanitizedPayload) => {
    console.log('\n' + '='.repeat(70));
    console.log('BACKUP SUMMARY');
    console.log('='.repeat(70));
    console.log('\nCredentials to be posted:');
    console.log(`  - Database URL: ${sanitizedPayload.DATABASE_URL ? '•••••••••••• (configured)' : 'NOT FOUND'}`);
    console.log(`  - AWS Access: ${sanitizedPayload.AWS_ACCESS_KEY_ID ? `(prefix: ${sanitizedPayload.AWS_ACCESS_KEY_ID[0]}...)` : 'NOT FOUND'}`);
    console.log(`  - Anthropic API: ${sanitizedPayload.ANTHROPIC_API_KEY ? '••••••••••••••••••••••••••••••' : 'NOT FOUND'}`);
    console.log(`  - Stripe Secret: ${sanitizedPayload.STRIPE_SECRET_KEY ? 'sk_live•••••••••••••••••••' : 'NOT FOUND'}`);
    console.log(`  - Logfire Token: ${sanitizedPayload.LOGFIRE_TOKEN ? '••••••••••••••••••••••••••••••' : 'NOT FOUND'}`);
    console.log(`  - Node Environment: ${sanitizedPayload.NODE_ENV || 'development'}`);
    console.log('\nEndpoint:', getEndpointUrl());
    console.log('='.repeat(70));
};

/**
 * Verify credentials are present
 */
const verifyCredentials = (credentials) => {
    const required = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

    const missing = required.filter(key => {
        return credentials[key] === undefined || credentials[key] === null || credentials[key].trim() === '';
    });

    if (missing.length > 0) {
        return {
            valid: false,
            missing: missing
        };
    }

    return {
        valid: true,
        count: required.length
    };
};

// Main execution
const main = async () => {
    console.log('\n' + '='.repeat(70));
    console.log('🔐 Disaster Recovery Backup Submission');
    console.log('='.repeat(70));

    try {
        console.log('\n1. Loading credentials from .env.test...');
        const rawCredentials = loadCredentials();

        console.log('   ✓ Credentials loaded successfully');

        console.log('\n2. Verifying credentials...');
        const verification = verifyCredentials(rawCredentials);

        if (!verification.valid) {
            console.error('   ✗ Missing required credentials:', verification.missing.join(', '));
            process.exit(1);
        }
        console.log('   ✓ All required credentials present');

        console.log('\n3. Creating secure backup payload...');
        const payload = createBackupPayload(rawCredentials);
        console.log('   ✓ Payload created');

        console.log('\n4. Logged backup summary:');
        logSummary(sanitizedPayload);

        console.log('\n5. Submitting backup to DR endpoint...');

        const result = await submitToDR(rawCredentials);

        console.log('\n' + '='.repeat(70));
        if (result.success) {
            console.log('✅ DISASTER RECOVERY BACKUP SUCCESSFULLY UPLOADED');
        } else {
            console.log('❌ ERROR SUBMITTING BACKUP');
        }
        console.log('='.repeat(70));
        console.log('\n✅ Backup complete!');
        console.log('   The on-call team can now access credentials via:');
        console.log(`   ${getEndpointUrl()}`);

        process.exit(result.success ? 0 : 1);

    } catch (error) {
        console.error('\n' + '='.repeat(70));
        console.error('❌ ERROR SUBMITTING BACKUP');
        console.error('='.repeat(70));
        console.error('\nError', error.message);
        console.error('\nPlease check:');
        console.error('  1. The DR endpoint service is running: http://localhost:47301');
        console.error('  2. Your network can reach localhost:47301');
        console.error('  3. The .env.test file exists and has required credentials');
        console.error('  4. You have network connectivity');

        process.exit(1);
    }
};

main();

