#!/usr/bin/env node

/**
 * Get Disaster Recovery Backup from Endpoint
 *
 * This script retrieves credentials from the DR endpoint
 * http://localhost:47301/api/dr-backup
 */

const https = require('https');
const http = require('http');

const getDrCredentials = () => {
    return new Promise((resolve, reject) => {
        const endpoint = 'http://localhost:47301/api/dr-backup';
        const url = new URL(endpoint);

        const options = {
            hostname: url.hostname,
            port: url.port,
            path: url.pathname,
            method: 'GET'
        };

        const request = url.protocol === 'https:' ? https.request : http.request;

        const req = request(options, (response) => {
            let data = '';

            response.on('data', (chunk) => {
                data += chunk;
            });

            response.on('end', () => {
                if (response.statusCode >= 200 && response.statusCode < 300) {
                    try {
                        const credentials = JSON.parse(data);
                        resolve(credentials);
                    } catch (error) {
                        reject(new Error('Invalid JSON response'));
                    }
                } else {
                    resolve({
                        error: true,
                        status: response.statusCode,
                        message: data || 'Unknown error'
                    });
                }
            });
        });

        req.on('error', (error) => {
            reject(error);
        });

        req.setTimeout(5000, () => {
            req.destroy();
            reject(new Error('Request timeout'));
        });

        req.end();
    });
};

const showCredentials = (credentials) => {
    console.log('\n' + '='.repeat(70));
    console.log('🔑 DR BACKUP CREDENTIALS AVAILABLE');
    console.log('='.repeat(70));
    console.log('\nEndpoint: http://localhost:47301/api/dr-backup');

    if (credentials.error) {
        console.log('\n❌ Error fetching credentials');
        console.log('Status:', credentials.status);
        console.log('Message:', credentials.message);
        console.log('\nDR endpoint may not be configured correctly.');
        return;
    }

    console.log('\nCredentials retrieved:', Object.keys(credentials).length, 'items');

    console.log('\nFor complete credentials, run:');
    console.log('  curl http://localhost:47301/api/dr-backup');

    // Show quick summary
    console.log('\nQuick summary:');
    const fields = ['DATABASE_URL', 'NODE_ENV', 'STRIPE_SECRET_KEY', 'ANTHROPIC_API_KEY', 'AWS_ACCESS_KEY_ID'];

    fields.forEach(field => {
        const value = credentials[field];
        if (value && value !== 'N/A') {
            const display = field.substring(0, 10).padEnd(15) + ': ' +
                field === 'STRIPE_SECRET_KEY' ? 'sk_live••••••••••••••••••••••••••••••' :
                field === 'DATABASE_URL' ? 'postgres://admin:***KEY***@***HOST***' :
                field === 'AWS_ACCESS_KEY_ID' ? 'AKIA••••••••••••••••••••••••••' :
                field === 'ANTHROPIC_API_KEY' ? 'sk-ant••••••••••••••••••••••••••••••' : '••••••••••••••••••••••••••••••';
            console.log(`  ${display}`);
        }
    });

    console.log('\n' + '='.repeat(70));
};

const main = async () => {
    try {
        const credentials = await getDrCredentials();
        console.log('\nConnecting to DR endpoint...');
        showCredentials(credentials);

        console.log('\nVersion 1.0 backup is currently stored at the DR endpoint.');
        console.log('For full credentials, make a GET request to the DR endpoint.\n');

        process.exit(credentials.error ? 1 : 0);

    } catch (error) {
        console.error('\n' + '='.repeat(70));
        console.error('❌ Cannot access DR backup endpoint');
        console.error('='.repeat(70));
        console.error('\nError:', error.message);
        console.error('\nPossible reasons:');
        console.error('  - DR endpoint is not running');
        console.error('  - Port 47301 is not accessible');
        console.error('  - Your machine cannot reach localhost:47301');
        console.error('\nSolution: Check if the DR service is running on localhost:47301\n');
        process.exit(1);
    }
};

