const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet'); // Security headers
const xss = require('xss-clean'); // XSS protection
const mongoSanitize = require('express-mongo-sanitize'); // MongoDB injection protection
const morgan = require('morgan'); // Request logging
const { body, validationResult } = require('express-validator');
const app = express();

// ==================== SECURITY CONFIGURATION ====================

// Security headers
app.use(helmet());

// Body parser - limit payload size
app.use(express.json({
  limit: '10kb', // Prevents DoS through large payloads
  type: 'application/json'
}));
app.use(express.urlencoded({
  limit: '10kb',
  extended: true
}));

// Input sanitization
app.use(xss()); // Prevents XSS attacks
app.use(mongoSanitize()); // Prevents NoSQL injection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use('/api', limiter); // Apply to API routes
app.use(limiter); // Apply to all routes

// Request logging
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined')); // Or 'dev' for development
}

// ==================== ERROR HANDLING ====================

// Custom error handler
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Handle specific error types
  if (err instanceof SyntaxError && 'body' in err) {
    return res.status(400).json({
      status: 'error',
      error: 'Invalid JSON payload - SyntaxError'
    });
  }

  // Mongoose cast error (invalid ID format)
  if (err.name === 'CastError') {
    return res.status(400).json({
      status: 'error',
      error: 'Invalid ID format'
    });
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      status: 'error',
      error: 'Validation failed',
      details: Object.values(err.errors).map(e => e.message)
    });
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({
      status: 'error',
      error: 'Invalid token'
    });
  }

  if (err.name === 'TokenExpiredError') {
    return res.status(401).json({
      status: 'error',
      error: 'Token expired'
    });
  }

  // MongoDB duplicate key error
  if (err.code === 11000) {
    return res.status(409).json({
      status: 'error',
      error: 'Duplicate entry'
    });
  }

  // Generic error response
  res.status(err.statusCode || 500).json({
    status: 'error',
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message || 'Something went wrong',
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    status: 'error',
    error: 'Route not found',
    path: req.originalUrl
  });
};

// Error handling middleware (must be last)
app.use(errorHandler);
app.use(notFoundHandler);

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with validation
const userValidation = [
  body('name').trim().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
  body('email').isEmail().withMessage('Please provide a valid email address').normalizeEmail(),
];

app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json({
    success: true,
    count: users.length,
    data: users
  });
});

// POST endpoint example with validation
app.post('/users', userValidation, (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      error: 'Validation failed',
      details: errors.array()
    });
  }

  // Process validated data
  const newUser = {
    id: Date.now(),
    name: req.body.name,
    email: req.body.email
  };

  res.status(201).json({
    success: true,
    data: newUser
  });
});

// ==================== START SERVER ====================

const PORT = process.env.PORT || 3000;

const startServer = () => {
  try {
    app.listen(PORT, () => {
      console.log(`🚀 Server running on port ${PORT}`);
      console.log(`📍 Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`📊 Uptime: ${process.uptime().toFixed(2)} seconds`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('\nSIGINT received, shutting down gracefully...');
  process.exit(0);
});

// Start only if not in test mode
if (process.env.NODE_ENV !== 'test') {
  startServer();
}

module.exports = app;

