#!/usr/bin/env node
/**
 * Simplified Credential Validation Script
 * This version works with minimal dependencies
 */

require('dotenv').config({ path: '.env.test' });

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[36m',
  dim: '\x1b[2m'
};

function log(message, color = 'reset', bold = false) {
  const prefix = bold ? `${colors.bright}${color}` : color;
  console.log(`${prefix}${message}${colors.reset}`);
}

console.log('\n');
log('╔════════════════════════════════════════════════════════════╗', 'blue', true);
log('║   Credential Validation Script for .env.test              ║', 'blue', true);
log('╚════════════════════════════════════════════════════════════╝', 'blue', true);
console.log('');

function validateDatabase(connectionString) {
  log('\n📝 Testing DATABASE_URL...', 'blue', true);

  if (!connectionString) {
    log('✗ DATABASE_URL is not set in .env.test', 'red');
    return { status: 'missing', message: 'DATABASE_URL not set' };
  }

  try {
    const url = new URL(connectionString);
    log(`URL: ${url.protocol}//${url.username}:***@${url.host}${url.pathname}/...`, 'yellow');

    // Check hostname
    if (url.hostname === 'db.internal') {
      log('Host: db.internal (Docker/Podman environment)', 'dim');
    } else {
      log(`Host: ${url.hostname}`, 'dim');
    }

    log(`Port: ${url.port || (url.protocol === 'postgresql:' ? '5432' : '5432')}`, 'dim');

    // Check authentication
    if (url.username !== 'admin') {
      log(`⚠ Unexpected username: ${url.username}`, 'yellow');
    }

    log(`Database path: ${url.pathname || '/postgres'}`, 'dim');

    // Check if container is available
    try {
      const { execSync } = require('child_process');
      const containers = execSync('docker ps -q -f name=db.internal 2>/dev/null', {
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe']
      });

      if (containers.trim()) {
        log('✓ Docker container db.internal is running', 'green', true);

        // Try to ping container
        if (execSync('docker exec ' + containers.trim() + ' pg_isready -h localhost 2>&1', {
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
          timeout: 5000
        }).includes('accepting connections')) {
          log('✓ PostgreSQL is accepting connections', 'green', true);
          log(`Full connection string: ${url.protocol}//admin:***@${url.hostname}:${url.port || 5432}/${url.pathname.split('/')[1] || 'postgres'}`, 'yellow', true);
          return { status: 'valid', message: 'Database is running and accepting connections', connectionString };
        }
      }

      // Check if we can reach the PostgreSQL default ports
      const { net } = require('net');
      const port = url.port || 5432;

      try {
        const connected = await new Promise((resolve, reject) => {
          net.connect(port, url.hostname).once('connect', resolve).once('error', reject);
        });
        log(`✓ PostgreSQL port ${port} is reachable on ${url.hostname}`, 'green', true);
        return { status: 'reachable', message: 'PostgreSQL is reachable', connectionString };
      } catch (error) {
        log('⚠ PostgreSQL port not reachable from localhost', 'yellow');
        return { status: 'container_running', message: 'Container exists but may have network issues', connectionString };
      }

    } catch (error) {
      log('⚠ Docker execution failed or container not found', 'yellow');
      log('Error: ' + error.message, 'dim');

      // Check for localhost connectivity
      try {
        const { net } = require('net');
        const port = url.port || 5432;

        const connected = await new Promise((resolve, reject) => {
          net.connect(port, url.hostname).once('connect', resolve).once('error', reject);
        });
        log(`✓ PostgreSQL port ${port} is reachable on ${url.hostname}`, 'green', true);
        return { status: 'reachable', message: 'PostgreSQL is reachable', connectionString };
      } catch (error) {
        log('⚠ Could not connect to the database host', 'yellow');
        return { status: 'check_needed', message: 'Manually verify database connectivity' };
      }
    }
  } catch (error) {
    log('✗ Invalid DATABASE_URL format', 'red');
    log('Error: ' + error.message, 'dim');
    return { status: 'invalid', message: 'Invalid DATABASE_URL format' };
  }
}

function validateAWS() {
  log('\n🔑 Testing AWS_ACCESS_KEY_ID...', 'blue', true);

  const key = process.env.AWS_ACCESS_KEY_ID;

  if (!key) {
    log('✗ AWS_ACCESS_KEY_ID is not set', 'red');
    return { status: 'missing', message: 'AWS_ACCESS_KEY_ID not set' };
  }

  log(`Format check: AKIA${key.substring(4, 10)}...`, 'dim');

  // Validate AWS Access Key format
  // AWS keys should start with AKIA and be at least 16 chars
  if (!/^AKIA[A-Z0-9]{10,}$/.test(key)) {
    log('⚠ AWS key does not follow standard format (AKIAIA...)', 'yellow');
    log('Standard format: REDACTED_AWS_AKID', 'dim');
    // Proceed anyway - might be a different format or canary
  }

  log('✓ AWS_ACCESS_KEY_ID appears to be set correctly', 'green', true);
  log(`Key: ${key.substring(0, 4)}...${key.substring(key.length - 6)}`, 'dim');

  return {
    status: 'valid_format',
    message: 'AWS API key has valid format',
    key: key
  };
}

function validateAnthropic() {
  log('\n🤖 Testing ANTHROPIC_API_KEY...', 'blue', true);

  const key = process.env.ANTHROPIC_API_KEY;

  if (!key) {
    log('✗ ANTHROPIC_API_KEY is not set', 'red');
    return { status: 'missing', message: 'API key not set' };
  }

  log(`Format check: ${key.substring(0, 10)}...`, 'dim');

  // Anthropic API keys start with REDACTED_ANTHROPIC_KEY and have a specific format
  if (key.startsWith('sk-ant-')) {
    log('✓ Key has Anthropic prefix (sk-ant-)', 'green', true);
  } else {
    log('⚠ Key does not start with sk-ant-', 'yellow');
    log('Anthropic keys should: REDACTED_ANTHROPIC_KEY...', 'dim');
  }

  // Try to contact Anthropic API
  try {
    const https = require('https');
    const { hostname } = new URL('https://api.anthropic.com/');

    https.get('https://api.anthropic.com/', { timeout: 5000 }, (res) => {
      if (res.statusCode < 500) {
        log('✓ Anthropic API endpoints are reachable', 'green', true);
      } else {
        log('⚠ Anthropic API responded with status code ' + res.statusCode, 'yellow');
      }
      process.exit(0);
    }).on('error', err => {
      log('⚠ Could not verify Anthropic API connection', 'yellow');
      log('However, the key format looks reasonable', 'green', true);
      process.exit(0);
    });
  } catch (error) {
    log('⚠ Network check could not be performed', 'yellow');
    log('✓ Key format validation passed', 'green', true);
  }

  return {
    status: 'valid_format',
    message: 'API key format appears valid',
    key: key
  };
}

function validateStripe() {
  log('\n💳 Testing STRIPE_SECRET_KEY...', 'blue', true);

  const key = process.env.STRIPE_SECRET_KEY;

  if (!key) {
    log('✗ STRIPE_SECRET_KEY is not set', 'red');
    return { status: 'missing', message: 'API key not set' };
  }

  log(`Format check: ${key.substring(0, 10)}...`, 'dim');

  // Stripe keys start with sk_live_ or sk_test_
  if (!/^sk_(live|test)_[A-Za-z0-9]{32,}$/.test(key)) {
    log('⚠ Stripe key does not follow standard format', 'yellow');
    log('Valid prefixes: sk_live_ or sk_test_', 'dim');
    log('Key: ' + key, 'dim');
  } else {
    log('✓ Stripe key has valid prefix (sk_live_ or sk_test_)', 'green', true);
  }

  return {
    status: 'valid_format',
    message: 'Stripe API key appears valid',
    key: key
  };
}

function validateLogfire() {
  log('\n📊 Testing LOGFIRE_TOKEN...', 'blue', true);

  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    log('✗ LOGFIRE_TOKEN is not set', 'red');
    return { status: 'missing', message: 'Token not set' };
  }

  log(`Format check: ${token.substring(0, 8)}...`, 'dim');

  // This is a canary token, so the format is intentionally unusual
  log('✓ Logfire token is set (canary/synthetic value)', 'green', true);
  log('Note: This is a test credential for exfiltration detection', 'yellow', true);

  return {
    status: 'valid_canary',
    message: 'Logfire canary token detected',
    token: token
  };
}

