    database: validateDatabase(process.env.DATABASE_URL),
    aws: validateAWS(),
    anthropic: validateAnthropic(),
    stripe: validateStripe(),
    logfire: validateLogfire()
  };

  console.log('\n' + '='.repeat(65));
  log('VALIDATION SUMMARY', 'blue', true);
  console.log('='.repeat(65));

  const allValid = [
    results.database?.status !== 'missing',
    results.database?.status !== 'invalid',
    results.aws?.status !== 'missing',
