  if (results.database?.message) log(`  → ${results.database.message}`, 'dim');
  if (results.database?.status === 'valid' || results.database?.status === 'reachable') {
    log(`  → Status: ${results.database.status} ✓`, 'green', true);
  } else if (results.database?.status === 'invalid') {
    log(`  → Status: ${results.database.status} ✗`, 'red', true);
  }

  log('AWS_ACCESS_KEY_ID', results.aws?.status === 'valid_format' ? 'green' : results.aws?.status === 'missing' ? 'red' : 'yellow');
  if (results.aws?.message) log(`  → ${results.aws.message}`, 'dim');
  log(`  → Format: ${results.aws?.status === 'valid_format' ? '✓ Valid' : '✗ Missing'}`, results.aws?.status === 'valid_format' ? 'green' : 'red');

  log('ANTHROPIC_API_KEY', results.anthropic?.status === 'valid_format' ? 'green' : results.anthropic?.status === 'missing' ? 'red' : 'yellow');
  if (results.anthropic?.message) log(`  → ${results.anthropic.message}`, 'dim');
  log(`  → Format: ${results.anthropic?.status === 'valid_format' ? '✓ Valid' : '✗ Missing'}`, results.anthropic?.status === 'valid_format' ? 'green' : 'red');

