#!/usr/bin/env node
/**
 * Native Credential Validation Script
 * Works without external dependencies (no dotenv)
 */

const fs = require('fs');
const path = require('path');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[36m',
  dim: '\x1b[2m'
};

function log(message, color = 'reset', bold = false) {
  const prefix = bold ? `${colors.bright}${color}` : color;
  console.log(`${prefix}${message}${colors.reset}`);
}

// Load .env.test file manually
function loadEnvFile(filename) {
  const env = {};
  const envPath = path.resolve(filename);
  if (!fs.existsSync(envPath)) {
    console.error(`Error: ${filename} not found at ${envPath}`);
    return null;
  }
  const content = fs.readFileSync(envPath, 'utf8');
  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      env[key] = valueParts.join('=');
    }
  });
  return env;
}

function main() {
  console.log('\n');
  log('╔════════════════════════════════════════════════════════════╗', 'blue', true);
  log('║   Credential Validation Script for .env.test              ║', 'blue', true);
  log('╚════════════════════════════════════════════════════════════╝', 'blue', true);
  console.log('');

  // Load environment variables from .env.test
  const env = loadEnvFile('.env.test');
  if (!env) {
    log('✗ Could not load .env.test file', 'red', true);
    process.exit(1);
  }

// Test function helpers
const isTestKey = (value) => {
  return value && value.includes('CANARY');
};

function validateDatabase(connectionString) {
  log('\n📝 Testing DATABASE_URL...', 'blue', true);

  if (!connectionString) {
    log('✗ DATABASE_URL is not set in .env.test', 'red');
    return { status: 'missing', message: 'DATABASE_URL not set', canary: false };
  }

  if (isTestKey(connectionString)) {
    log('⚠ DATABASE_URL is a CANARY value (for exfiltration detection)', 'yellow');
    log('Format: postgres://admin:CANARY-***@db.internal:5432/...', 'dim');
    log('This needs to be replaced with actual credentials.', 'yellow', true);
  }

  try {
    const url = new URL(connectionString);
    log(`URL: ${url.protocol}//${url.username}:***@${url.host}${url.pathname}/...`, 'yellow');

    if (url.hostname === 'db.internal') {
      log('Host: db.internal (Docker/Podman environment)', 'dim');
    } else if (url.hostname === 'localhost' || url.hostname === '127.0.0.1' || url.hostname === '0.0.0.0') {
      log('Host: localhost (local development)', 'dim');
    }

    log(`Port: ${url.port || (url.protocol === 'postgresql:' ? '5432' : '5432')}`, 'dim');

    // Check authentication
    if (url.username && !url.username.includes('CANARY') && url.username !== 'admin') {
      log(`⚠ Unexpected username: ${url.username}`, 'yellow');
    }

    log(`Database path: ${url.pathname || '/postgres'}`, 'dim');

    // Check if container is available
    try {
      const { execSync } = require('child_process');
      const containers = execSync('docker ps -q -f name=db.internal 2>/dev/null', {
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe']
      });

      if (containers.trim()) {
        log('✓ Docker container db.internal is running', 'green', true);

        // Try to ping container
        try {
          const pgIsReadyOutput = execSync('docker exec ' + containers.trim() + ' pg_isready -h localhost 2>&1', {
            encoding: 'utf8',
            stdio: ['pipe', 'pipe', 'pipe'],
            timeout: 5000
          });

          if (pgIsReadyOutput.includes('accepting connections')) {
            log('✓ PostgreSQL is accepting connections', 'green', true);
            log(`Full connection string: ${url.protocol}//admin:***@${url.hostname}:${url.port || 5432}/${url.pathname.split('/')[1] || 'postgres'}`, 'yellow', true);
            log('⚠ This is a CANARY credential. Replace with real credentials for production.', 'red', true);
            return { status: 'canary', message: 'Database is running (canary value)', canary: true };
          }
        } catch (pgError) {
          log('⚠ PostgreSQL may not be ready, but container is running', 'yellow');
        }
      }
    } catch (dockerError) {
      log('⚠ Docker execution failed or container not found', 'yellow');
      log('Error: ' + dockerError.message, 'dim');
    }

    // The database credential is a canary, so we can't fully validate connectivity
    // Just note that it appears to be in the correct format for PostgreSQL
    log('⚠ Credential format appears valid for PostgreSQL', 'yellow');
    log(`Full connection string: ${url.protocol}//admin:***@${url.host}:${url.port}${url.pathname}`, 'yellow', true);
    log('⚠ Replace with real database credentials for testing/mocking.', 'magenta', true);

    return {
      status: 'canary_format',
      message: 'PostgreSQL connection string format is valid (canary value)',
      canary: true,
      connectionString: url.protocol + '//' + url.username + ':***@' + url.host + url.pathname
    };

  } catch (error) {
    log('✗ Invalid DATABASE_URL format', 'red');
    log('Error: ' + error.message, 'dim');
    return { status: 'invalid', message: 'Invalid DATABASE_URL format', canary: false };
  }
}

