  log('\n🔑 Testing AWS_ACCESS_KEY_ID...', 'blue', true);

  const key = env.AWS_ACCESS_KEY_ID;

  if (!key) {
    log('✗ AWS_ACCESS_KEY_ID is not set', 'red');
    return { status: 'missing', message: 'AWS credentials not set', canary: false };
  }

  if (isTestKey(key)) {
