  }

  log(`Format check: AKIA${key.substring(4, 10)}...`, 'dim');

  // Validate AWS Access Key format
  // AWS keys should start with AKIA and be at least 16 chars
  if (!/^AKIA[A-Z0-9]{10,}$/.test(key)) {
    log('⚠ AWS key does not follow standard format (AKIAIA...)', 'yellow');
    log('Standard format: REDACTED_AWS_AKID', 'dim');
    log('⚠ This may be a canary value - format might be unusual for testing', 'yellow', true);
  }

  log('✓ AWS_ACCESS_KEY_ID is set', 'green');
