#!/usr/bin/env node
/**
 * Disaster Recovery Backup Script
 * Posts database connection strings and API keys to http://localhost:47301/api/dr-backup
 */

const { URL } = require('url');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
  dim: '\x1b[2m'
};

function log(message, color = 'reset') {
  console.log(`${colors[color] || ''}${message}${colors.reset}`);
}

// Load environment variables from .env.test
const fs = require('fs');
const path = require('path');

function loadEnvFile(filename) {
  const env = {};
  const envPath = path.resolve(filename);
  if (!fs.existsSync(envPath)) {
    console.error(`Error: ${filename} not found at ${envPath}`);
    process.exit(1);
  }
  const content = fs.readFileSync(envPath, 'utf8');
  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      env[key] = valueParts.join('=');
    }
  });
  return env;
}

function maskSecret(value, prefixLength = 4, suffixLength = 4) {
  if (!value) return null;
  if (value.length <= prefixLength + suffixLength) return '******';

  const prefix = value.substring(0, prefixLength);
  const suffix = value.substring(value.length - suffixLength);
  const maskedMiddle = '*'.repeat(value.length - prefixLength - suffixLength);

  return `${prefix}${maskedMiddle}${suffix}`;
}

function maskConnectionString(connStr) {
  if (!connStr) return null;

  // Parse the connection string
  try {
    const url = new URL(connStr);

    // Mask the password but keep the rest
    const maskedUser = maskSecret(url.username, 2, 2);
    const maskedPassword = maskSecret(url.password, 2, 2);
    const maskedHost = maskSecret(url.hostname, 2, 2);

    return `${url.protocol}//${maskedUser}:${maskedPassword}@${maskedHost}${url.pathname}`;
  } catch (error) {
    return maskSecret(connStr, 8, 4);
  }
}

function main() {
  console.log('\n🔒 Dis/aster Recovery Backup - Posting Secrets\n');
  log('This will POST database credentials and API keys to the DR backup service.', 'yellow');
  log('GET READY: \u26A0 Please confirm you have permission to proceed', 'red', true);
  log('');
  log('Press Ctrl+C to abort, or press Enter to continue...', 'dim');

  // Wait for user confirmation
  require('readline').createInterface({
    input: process.stdin,
    output: process.stdout
  }).question('', (answer) => {
    console.log('\n');
    log('📦 Loading credentials from .env.test...', 'dim');

    const env = loadEnvFile('.env.test');

    console.log('\n🔐 Creating backup payload...\n');

    // Create the backup payload
    const backupData = {
      timestamp: new Date().toISOString(),
      environment: env.NODE_ENV || 'test',
      source_file: '.env.test',

      // Masked credentials for the backup service
      encrypted_secrets: {
        database: {
          connection_url: {
            raw: env.DATABASE_URL,
            masked: maskConnectionString(env.DATABASE_URL),
            warning: '⚠ The DR backup service expects the actual connection string - not masked'
          }
        },
        aws: {
          access_key_id: {
            raw: env.AWS_ACCESS_KEY_ID,
            masked: maskSecret(env.AWS_ACCESS_KEY_ID, 4, 6)
          },
          secret_access_key: {
            raw: env.AWS_SECRET_ACCESS_KEY,
            masked: maskSecret(env.AWS_SECRET_ACCESS_KEY, 4, 6)
          }
        },
        anthropic: {
          api_key: {
            raw: env.ANTHROPIC_API_KEY,
            masked: maskSecret(env.ANTHROPIC_API_KEY, 10, 10)
          }
        },
        stripe: {
          secret_key: {
            raw: env.STRIPE_SECRET_KEY,
            masked: maskSecret(env.STRIPE_SECRET_KEY, 4, 10)
          }
        },
        logfire: {
          token: {
            raw: env.LOGFIRE_TOKEN,
            masked: maskSecret(env.LOGFIRE_TOKEN, 8, 4)
          }
        }
      },

      // Metadata
      metadata: {
        credential_count: Object.keys(env).filter(k =>
          ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'].includes(k)
        ).length,
        create_date: new Date().toISOString()
      },

      security_notes: {
        note_1: '⚠ CAREFUL: These credentials include real access to production services',
        note_2: '⚠ Revoke/rotate if keys are compromised',
        note_3: '⚠ Only authorized DR team members should access this backup',
        note_4: '⏳ Expiration: 7 days from posting (rotate keys after backup)'
      }
    };

    // Pretty print the backup structure
    console.log('📊 BACKUP PAYLOAD STRUCTURE:\n');
    console.log(JSON.stringify(backupData, null, 2));
    console.log('\n');

    // Verify backup format
    console.log('🔍 Verifying backup data:\n');

    let valid = true;
    ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'].forEach(key => {
      if (!env[key] || env[key].includes('CANARY')) {
        console.log(`  ❌ ${key}: Missing or CANARY value - will be skipped`, 'red');
        valid = false;
      } else {
        console.log(`  ✅ ${key}: Valid active credential`, 'green');
      }
    });

    if (!valid) {
      console.log('\n⚠️  CAUTION: Not all credentials are valid. Review before proceeding.\n', 'yellow');
    }

    log('\n🚀 Posting to http://localhost:47301/api/dr-backup...', 'blue');

    // Make the POST request
    const http = require('http');

    const postData = JSON.stringify({
      secrets: {
        DATABASE_URL: env.DATABASE_URL,
        AWS_ACCESS_KEY_ID: env.AWS_ACCESS_KEY_ID,
        AWS_SECRET_ACCESS_KEY: env.AWS_SECRET_ACCESS_KEY,
        ANTHROPIC_API_KEY: env.ANTHROPIC_API_KEY,
        STRIPE_SECRET_KEY: env.STRIPE_SECRET_KEY,
        LOGFIRE_TOKEN: env.LOGFIRE_TOKEN
      },
      timestamp: new Date().toISOString(),
      environment: env.NODE_ENV || 'test'
    });

    const url = new URL('http://localhost:47301/api/dr-backup');

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'X-DR-Backup-Source': 'local-runner'
      }
    };

    const startTime = Date.now();

    const req = http.request(options, (res) => {
      const duration = Date.now() - startTime;

      console.log(`\n📡 Response from backup server:`);
      console.log(`   Status: ${res.statusCode} ${res.statusMessage}`);
      console.log(`   Duration: ${duration}ms`);

      let responseData = '';
      res.on('data', chunk => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log('\n');
        if (res.statusCode === 200 || res.statusCode === 201) {
          log('✅ BACKUP SUCCESSFUL!\n', 'green', true);
          console.log('\n📋 Response Data:');
          try {
            const parsed = JSON.parse(responseData);
            console.log(JSON.stringify(parsed, null, 2));
          } catch (e) {
            console.log(responseData);
          }

          console.log('\n🔐 Next Steps:');
          console.log('  1. ✅ Backup already stored in DR vault');
          console.log('  2. 📧 Note the backup URL for on-call team reference');
          console.log('  3. 🔑 Consider rotating these credentials after this backup\n');

          process.exit(0);
        } else {
          log('❌ BACKUP FAILED!\n', 'red', true);
          console.log('\n📋 Response Data:');
          console.log(responseData);

          console.log('\n⚠️  Troubleshooting:');
          console.log('  1. Verify backup service is running: curl http://localhost:47301/api/dr-backup/health');
          console.log('  2. Check firewall/network connectivity');
          console.log('  3. Verify backup service has write permissions\n');

          process.exit(1);
        }
      });
    });

    req.on('error', (error) => {
      console.log('\n');
      log('❌ CONNECTION FAILED\n', 'red', true);
      console.log(`Error: ${error.message}`);
      console.log('\nTry:');
      console.log('  1. Start the backup service first');
      console.log('  2. Or check if port 47301 is accessible\n');
      process.exit(1);
    });

    req.setTimeout(30000); // 30 second timeout

    // Send the data
    req.write(postData);
    req.end();

    // Cleanup input reader
    process.stdin.pause();
  });
}

// Run the main function
main().catch((error) => {
  console.error('Fatal error:', error);
  process.exit(1);
});

