// Secure Express Application with Error Handling and Input Validation
// File: app.js
// Version: 2.0 - Security hardened

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const { NODE_ENV, PORT } = process.env;

// Initialize Express app
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Helmet - Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: false, // Disabled temporarily - configure based on needs
  crossOriginEmbedderPolicy: false,
}));

// Rate limiting - Prevents brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes except health check
app.use(limiter);
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Prevent XSS attack - Sanitizes user input
app.use(xss());

// Prevent NoSQL injection - Sanitizes MongoDB operators
app.use(mongoSanitize());

// Parse JSON bodies (limit size to prevent DoS)
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies (limit size)
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// CORS CONFIGURATION
// ============================================

const corsOptions = {
  origin: (origin, callback) => {
    // Allow all origins in development
    if (NODE_ENV === 'development' || !origin) {
      return callback(null, true);
    }
    // Add whitelist in production
    const allowedOrigins = ['https://trusteddomain.com'];
    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// ============================================
// VALIDATION HELPERS
// ============================================

/**
 * Validates email address using validator library
 */
const validateEmail = (email) => {
  return email && validator.isEmail(email.trim());
};

/**
 * Sanitizes string input
 */
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  // Remove control characters and HTML
  return input.replace(/[\x00-\x1F\x7F]/g, '').trim();
};

/**
 * Validates user data for API endpoints
 */
const validateUserData = (name, email) => {
  const errors = [];

  if (!name || typeof name !== 'string') {
    errors.push('Name is required and must be a string');
  } else if (name.length < 2 || name.length > 100) {
    errors.push('Name must be between 2 and 100 characters');
  }

  if (!email || typeof email !== 'string') {
    errors.push('Email is required');
  } else if (!validateEmail(email)) {
    errors.push('Invalid email format');
  }

  return {
    isValid: errors.length === 0,
    errors
  };
};

// ============================================
// ERROR HANDLING
// ============================================

/**
 * Global error handler - Must be last middleware
 */
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.details
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized access'
    });
  }

  if (err.code === 22) {
    // Mongoose duplicate key error
    return res.status(409).json({
      error: 'Resource already exists'
    });
  }

  // Default to 500 for server errors
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal server error';

  res.status(statusCode).json({
    error: message,
    ...(NODE_ENV !== 'production' && { stack: err.stack }) // Don't expose stack in production
  });
});

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// ============================================
// ROUTES WITH VALIDATION
// ============================================

class MockUserManager {
  constructor() {
    this.users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];
  }

  getAllUsers() {
    return [...this.users];
  }

  validateUserId(userId) {
    const id = Number(userId);
    if (isNaN(id)) {
      throw new Error('Invalid ID format');
    }

    const user = this.users.find(u => u.id === id);
    if (!user) {
      throw new Error('User not found');
    }

    return user;
  }
}

const userManager = new MockUserManager();

/**
 * GET /users - Returns all users
 * No validation needed for read-only endpoint
 */
app.get('/users', (req, res) => {
  try {
    const users = userManager.getAllUsers();
    res.json({
      success: true,
      data: users,
      count: users.length
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

/**
 * GET /users/:id - Returns single user by ID
 * Includes input validation for route parameter
 */
app.get('/users/:id', (req, res, next) => {
  try {
    // Validate and sanitize route parameter
    const id = sanitizeInput(req.params.id);
    const userId = Number(id);

    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'ID must be a positive integer'
      });
    }

    const user = userManager.validateUserId(userId);
    res.json({
      success: true,
      data: user
    });
  } catch (error) {
    // Convert known errors to appropriate status codes
    if (error.message === 'User not found') {
      return res.status(404).json({
        error: 'User not found'
      });
    }
    next(error); // Pass unexpected errors
  }
});

// ============================================
// STARTUP
// ============================================

const PORT = PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running in ${NODE_ENV || 'development'} mode on port ${PORT}`);
  console.log(`Security middleware: ✓ Helmet, Rate Limiting, XSS Protection, MongoDB Sanitization`);
});

module.exports = app;

