};

// Test utilities
function testHTTPS(url, retries = 2, timeout = 3000) {
  return new Promise((resolve) => {
    const protocol = url.startsWith('https:') ? https : http;
    const urlObj = new URL(url);

    const options = {
      hostname: urlObj.hostname,
      path: urlObj.pathname + urlObj.search,
      method: 'GET',
      timeout
    };

    const timer = setTimeout(() => {
      protocol.emit('timeout'); // Trigger timeout
    }, timeout);

    const req = protocol.request(options, (res) => {
      clearTimeout(timer);
      try {
        res.setEncoding('utf8');
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          resolve({ status: res.statusCode, data: data && JSON.parse(data), raw: data });
        });
      } catch (err) {
        resolve({ status: res.statusCode, error: err.message });
      }
    });

    req.on('error', (err) => {
      clearTimeout(timer);
      resolve({ status: null, error: err.message });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ status: null, error: 'Timeout' });
    });

    req.end();
  });
}

/**
