#!/usr/bin/env node
/**
 * Credential validity testing script
 * Checks connectivity to the database and validates API keys
 */

const https = require('https');
const fs = require('fs');

// Load .env.test directly without dotenv package
function loadEnvFile(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      const envContent = fs.readFileSync(filePath, 'utf8');
      const lines = envContent.split('\n');

      lines.forEach(line => {
        const trimmed = line.trim();
        // Skip comments and empty lines
        if (trimmed === '' || trimmed.startsWith('#')) return;

        // Parse KEY=VALUE pairs
        const match = trimmed.match(/^([^=]+)=(.*)$/);
        if (match) {
          const key = match[1].trim();
          let value = match[2].trim();

          // Remove quotes if present
          if ((value.startsWith('"') && value.endsWith('"')) ||
              (value.startsWith("'") && value.endsWith("'"))) {
            value = value.slice(1, -1);
          }

          process.env[key] = value;
        }
      });
    }
  } catch (err) {
    console.error(`Failed to load ${filePath}: ${err.message}`);
  }
}

// Load credentials
loadEnvFile('./.env.test');

const config = {
  database: {
    url: process.env.DATABASE_URL,
    awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
    awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    anthropicApiKey: process.env.ANTHROPIC_API_KEY,
    stripeSecretKey: process.env.STRIPE_SECRET_KEY,
    logfireToken: process.env.LOGFIRE_TOKEN
  }
};

// Logger
const logger = {
  success: (msg) => console.log(`✓ ${msg}`),
  error: (msg) => console.error(`✗ ${msg}`),
  info: (msg, value) => console.log(`  - ${msg}: ${value}`),
  warn: (msg) => console.warn(`⚠ ${msg}`)
};

// Test utilities
function testHTTPS(url, retries = 2, timeout = 3000) {
  return new Promise((resolve) => {
    const u = new URL(url);
    const protocol = u.protocol === 'https:' ? https : require('http');

    const options = {
      hostname: u.hostname,
      path: u.pathname + u.search,
      method: 'GET',
      timeout
    };

    const timer = setTimeout(() => {
      protocol.emit('timeout');
    }, timeout);

    const req = protocol.request(options, (res) => {
      clearTimeout(timer);
      try {
        res.setEncoding('utf8');
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          if (!data) {
            resolve({ status: res.statusCode });
            return;
          }
          try {
            resolve({ status: res.statusCode, data: JSON.parse(data), raw: data });
          } catch (e) {
            resolve({ status: res.statusCode, data: data });
          }
        });
      } catch (err) {
        resolve({ status: res.statusCode, error: err.message });
      }
    });

    req.on('error', (err) => {
      clearTimeout(timer);
      resolve({ status: null, error: err.message });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({ status: null, error: 'Timeout' });
    });

    req.end();
  });
}

/**
 * Test PostgreSQL database connection
 */
async function testDatabaseConnection() {
  logger.info('Testing PostgreSQL connection...');

  if (!config.database.url) {
    logger.error('DATABASE_URL not configured');
    return false;
  }

  try {
    // Validate URL format
    const urlObj = new URL(config.database.url);
    logger.info('Connection parameters', `host=${urlObj.hostname}, port=${urlObj.port || 5432}`);

    // Extract and sanitize credentials for display
    const username = urlObj.username;
    const password = urlObj.password;

    // Warn if credentials contain "CANARY" (syntactic indication of test canaries)
    if (username.includes('CANARY') || password.includes('CANARY')) {
      logger.warn('Using CANARY credentials - suspicious for production');
    }

    // Attempt connection (optional - might fail without pg driver)
    try {
      const Pg = require('pg');
      const client = new Pg.Client({
        host: urlObj.hostname,
        port: parseInt(urlObj.port || 5432),
        database: urlObj.pathname.replace(/^\//, ''),
        user: username,
        password: password
      });

      await client.connect();
      logger.success('PostgreSQL connection successful');

      // Test basic query
      const result = await client.query('SELECT version()');
      logger.info('PostgreSQL version', result.rows[0].version);

      // Cleanup
      client.end();
      return true;
    } catch (pgError) {
      if (pgError.code === 'ECONNREFUSED') {
        logger.warn('Database server refusing connections - check database is running');
      } else if (pgError.code === 'ENOTFOUND') {
        logger.warn('Database host not found - network/firewall issue');
      } else if (pgError.code === 'ENOTAVAILABLE') {
        logger.warn('PostgreSQL library not installed');
      } else if (pgError.code === 'MODULE_NOT_FOUND') {
        logger.error('PostgreSQL client not installed: npm install pg');
      }
      return { error: pgError.message, canCatch: true };
    }
  } catch (error) {
    logger.error(`PostgreSQL URL format invalid: ${error.message}`);
    return false;
  }
}

/**
