async function testAWSToken() {
  logger.info('Testing AWS credentials...');

  if (!config.database.awsAccessKeyId || !config.database.awsSecretAccessKey) {
    logger.error('AWS credentials not configured');
    return false;
  }

  try {
    const result = await testHTTPS('https://sts.amazonaws.com/', 1, 3000);

