### **Improved Version with Security Best Practices:**

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss');
const validator = require('validator');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(express.json({ limit: '10kb' })); // Size limits
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting (prevent brute force)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// Input sanitization helper
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return xss(input.trim());
  }
  return input;
};

// Input validators
const validateEmail = (email) => {
  return validator.isEmail(email) && validator.isLength(email, { min: 5, max: 255 });
};

const validateId = (id) => {
  return validator.isInt(id, { min: 1, max: 2147483647 });
};

// Health endpoint (business logic)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with validation and sanitization
app.get('/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: sanitizeInput('Alice'), email: xss('alice@example.com') },
      { id: 2, name: sanitizeInput('Bob'), email: xss('bob@example.com') },
    ];
    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Access Control - Add IP allowlisting if needed
