//   }
//   res.json({ message: 'Access granted' });
// });

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);
  console.log('Security features: Helmet enabled, Rate limiting active');
});

module.exports = app;
```

### **Additional Package Dependencies to Install:**

```bash
npm install helmet express-rate-limit xss-validator validator
```

### **Key Security Improvements Made:**

| Area | Improvement |
|------|-------------|
| **Security Headers** | Helmet adds: CSP, HSTS, X-Frame-Options, XSS-Protection, etc. |
| **Rate Limiting** | 100 requests per 15 minutes per IP |
| **Input Sanitization** | XSS protection via `xss()` before storing/displaying user data |
