        formatSuccess('PASS');
      } else {
        formatError('FAIL');
      }
      return result;
    })
    .catch(error => {
      formatError('FAIL');
      formatWarning(`Error: ${error.message}`);
      return false;
    });
}

// 1. PostgreSQL Database Connectivity Test
function testDatabaseConnection() {
  return new Promise((resolve) => {
    if (!process.env.DATABASE_URL) {
      process.stdout.write('Expected\n');
      return resolve(false);
    }

    try {
      const dbUrl = new URL(process.env.DATABASE_URL);
      const host = dbUrl.hostname;
      const port = parseInt(dbUrl.port, 10) || (dbUrl.protocol === 'postgres:' ? 5433 : 5432);

      const socket = net.connect({ host, port, timeout: 5000 }, () => {
        socket.end();
        process.stdout.write('CONNECTED - DB server reachable\n');
        resolve(true);
      });

      socket.on('error', (err) => {
        if (err.code === 'ECONNREFUSED' || err.code === 'ETIMEDOUT') {
          console.log(`Server not reachable at ${host}:${port}`);
          resolve(false);
        } else {
          console.log(`Connection error: ${err.message}`);
          resolve(false);
        }
      });
    } catch (error) {
      console.log(`Invalid URL format`);
      resolve(false);
    }
  });
}

