  const accessKey = process.env.AWS_ACCESS_KEY_ID;

  if (!accessKey) {
    process.stdout.write('Not set\n');
    return Promise.resolve(false);
  }

  const validFormat = /^[A-Z0-9]{20}$/;
  if (!validFormat.test(accessKey)) {
    process.stdout.write('Invalid format (needs 20 alphanumeric chars)\n');
    return Promise.resolve(false);
  }

  console.log('Valid AWS Access Key ID format');
  if (accessKey.includes('CANARY')) {
    formatWarning('Contains CANARY marker (synthetic test key)');
    return Promise.resolve(false); // Test key
  }

  formatSuccess('Valid AWS key');
  return Promise.resolve(true);
}

// 3. Anthropic API Key Validation
function testAnthropicApiKey() {
  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    process.stdout.write('Not set\n');
    return Promise.resolve(false);
  }

  if (!apiKey.startsWith('sk-ant-')) {
    process.stdout.write('Invalid format (missing sk-ant- prefix)\n');
    return Promise.resolve(false);
  }

  console.log('Valid Anthropic API Key format');

  if (apiKey.includes('CANARY')) {
    formatWarning('Contains CANARY marker (synthetic test key)');
    return Promise.resolve(false); // Test key
  }

  // Test connection via API
