      console.log(`Connection failed: ${err.message}`);
      resolve(false);
    });

    req.write(JSON.stringify({
      model: 'claude-haiku-20250514',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'Hi' }]
    }));
    req.end();
  });
}

