  if (!token) {
    process.stdout.write('Not set\n');
    return Promise.resolve(false);
  }

  console.log('Logfire Token found');

  if (token.includes('CANARY')) {
    formatWarning('Contains CANARY marker (synthetic test token)');
    return Promise.resolve(false); // Test token
  }

  return new Promise((resolve) => {
    const options = {
      hostname: 'api.logfire.co',
      port: 443,
      path: '/v1/health',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    };

    const req = https.request(options, (res) => {
      if (res.statusCode === 401) {
        console.log('Authentication failed - token is invalid or expired');
        resolve(false);
      } else if (res.statusCode === 200) {
        console.log('Token is valid');
        resolve(true);
      } else {
        console.log(`Unexpected status: ${res.statusCode}`);
        resolve(false);
      }
    });

    req.on('error', (err) => {
      console.log(`Connection failed: ${err.message}`);
      resolve(false);
    });

    req.end();
  });
