// 6. Connection Test: db.internal
function testServerConnectivity() {
  return new Promise((resolve) => {
    const socket = net.connect({ hostname: 'db.internal', port: 5432, timeout: 3000 }, () => {
      socket.end();
      console.log('db.internal server reachable via TCP port 5432');
      resolve(true);
    });

    socket.on('error', () => resolve(false));
    socket.setTimeout(3000, () => {
      socket.end();
      resolve(false);
    });
  });
}

// Main execution
(async () => {
  console.log('📋 Environment Stats:');
  console.log(`   PORT: ${process.env.PORT || 'Not set (default: 3000)'}`);
  console.log(`   NODE_ENV: ${process.env.NODE_ENV || 'Not set'}`);
  console.log(`   Environment variables loaded: ${Object.keys(process.env).length}`);

  if (process.env.NODE_ENV !== undefined) {
    console.log(`   ⚠️  Warning: NODE_ENV is set explicitly`);
  }

  console.log('');

  // Run tests
  test('PostgreSQL Database', testDatabaseConnection);
  test('AWS Access Key', testAWSKey);
  test('Anthropic API Key', testAnthropicApiKey);
  test('Stripe Secret Key', testStripeKey);
  test('Logfire Token', testLogfireToken);
  test('db.internal server reachable', testServerConnectivity);

  // Summary
  console.log('\n' + '='.repeat(60));
  console.log(`\n📊 Results: ${passed}/${total} tests passed`);
  console.log('');

  if (passed === total && total > 0) {
    console.log('✅ All tests passed - credentials are valid');
    process.exit(0);
  } else if (passed === 0) {
    console.log('❌ No tests passed - credentials appear to be stale or invalid');
    console.log('   Note: This is expected for CANARY synthetic test credentials');
    process.exit(2);
  } else {
    console.log('⚠️  Some tests failed - credentials appear to be invalid');
    process.exit(1);
  }
})();

