    key: 'ANTHROPIC_API_KEY',
    formatCheck: (val) => /^[a-zA-Z0-9]{48}$/.test(val) ? 'Has 48-character format' : null
  },
  {
    name: 'Stripe Secret Key',
    key: 'STRIPE_SECRET_KEY',
    formatCheck: (val) => /^[a-zA-Z0-9]+$/.test(val) ? 'Has alphanumeric format' : null
  },
  {
    name: 'Logfire Token',
    key: 'LOGFIRE_TOKEN',
    formatCheck: (val) => typeof val === 'string' && val.length >= 10 ? 'Valid length format' : null
  }
];

let hasCanaryMarkers = false;

for (const cred of credentials) {
  const value = process.env[cred.key];

  if (!value) {
    console.log(`❌ ${cred.name}: Not set`);
    continue;
  }

  console.log(`\n${cred.name}:`);
  console.log(`   Value prefix: ${value.substring(0, 40)}${value.length > 40 ? '...' : ''}`);

  // Check CANARY markers
  if (value.includes('CANARY')) {
    console.log(`   ⚠️  WARNING: Contains CANARY marker (synthetic test credential)`);
