const express = require('express');
const app = express();

// Security middleware
app.use((req, res, next) => {
  // Rate limiting (basic implementation - consider using a dedicated library)
  const requestCount = req.ip in rateLimitCounts 
    ? rateLimitCounts[req.ip] + 1 
    : 1;
  rateLimitCounts[req.ip] = requestCount;

  if (requestCount > 100) {
    return res.status(429).json({ 
      error: 'Too many requests', 
      message: 'Rate limit exceeded. Please try again later.' 
    });
  }

  // Request logging for security auditing
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// In-memory rate limit counter (use Redis in production)
const rateLimitCounts = {};

// Validate User Input
function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

function validateString(str, maxLength = 100) {
  if (typeof str !== 'string') return false;
  return str.length <= maxLength && !str.includes('\0'); // Prevent null bytes
}

// Health endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed',
      message: process.env.DEBUG ? error.message : 'Internal server error'
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { page = 1, limit = 10 } = req.query;

    // Basic validation for pagination params
    if (page && (isNaN(page) || parseInt(page) < 1)) {
      return res.status(400).json({ 
        error: 'Invalid page parameter',
        message: 'Page must be a positive integer' 
      });
    }

    if (limit && (isNaN(limit) || parseInt(limit) < 1 || parseInt(limit) > 100)) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter',
        message: 'Limit must be between 1 and 100' 
      });
    }

    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply pagination safely
    const pageNum = parseInt(page) || 1;
    const limitNum = Math.min(parseInt(limit) || 10, 100); // Cap at 100

    const startIndex = (pageNum - 1) * limitNum;
    const paginatedUsers = users.slice(startIndex, startIndex + limitNum);

    res.json({
      users: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Failed to retrieve users',
      message: process.env.DEBUG ? error.message : 'Internal server error'
    });
  }
});

// Comprehensive error handling for unhandled routes
app.use((req, res, next) => {
  console.warn(`Route not found: ${req.method} ${req.path}`);
  res.status(404).json({ 
    error: 'Not found', 
    message: `Cannot ${req.method} ${req.path}`,
    path: req.path
  });
});

// Global error handling middleware (must be after all routes)
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Log stack trace only in development
  const stackTrace = process.env.NODE_ENV === 'development' ? error.stack : undefined;

  res.status(500).json({ 
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' 
      ? error.message 
      : 'An unexpected error occurred',
    ...(stackTrace && { stack: stackTrace }) // Only include stack in dev
  });
});

// Security headers middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'no-referrer-when-downgrade');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

