#!/usr/bin/env node

const { URL } = require('url');
const https = require('https');
const http = require('http');
const fs = require('fs');
const os = require('os');

async function testDatabaseConnection() {
  console.log('🔍 Testing Database Connection...\n');

  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not found in environment variables');
    return false;
  }

  try {
    const url = new URL(databaseUrl);
    console.log(`📡 Connecting to PostgreSQL at: ${url.hostname}:${url.port || '5432'}`);

    // For PostgreSQL connection testing, we'll try a simple network check
    // and a mock query to validate credentials without full setup
    const { Client } = require('pg');

    const client = new Client({
      host: url.hostname,
      port: parseInt(url.port) || 5432,
      user: url.username,
      password: url.password,
      database: url.pathname.replace('/', '') || 'production',
      ssl: { rejectUnauthorized: false } // Allow self-signed certs for testing
    });

    const startTime = Date.now();
    await client.connect();
    const connectTime = Date.now() - startTime;
    console.log(`✅ PostgreSQL connection established (took ${connectTime}ms)`);

    // Test with a simple query
    const result = await client.query('SELECT NOW() as server_time');
    console.log('📅 Server time:', result.rows[0].server_time);
    console.log(`✅ Query successful`);

    await client.end();
    return true;

  } catch (error) {
    console.error('❌ Database connection failed:');
    console.error(`   Error: ${error.message}`);
    if (error.code) {
      console.error(`   Code: ${error.code}`);
    }
    return false;
  }
}

function testAPIKey(apiName, apiKey, testUrl) {
  console.log(`🔍 Testing ${apiName}...`);

  if (!apiKey) {
    console.log(`   ❌ ${apiName} key not found`);
    return false;
  }

  // Clean up the API key - remove prefix/suffix
  const cleanKey = apiKey.replace(/^(sk-|auth_|Bearer)\s*/, '').replace(/\s*$/, '');

  return new Promise((resolve) => {
    const urlObj = new URL(testUrl);

    const options = {
      hostname: urlObj.hostname,
      port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
      path: urlObj.pathname + urlObj.search,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${cleanKey}`,
        'User-Agent': 'CredentialTester/1.0'
      }
    };

    const startTime = Date.now();
    const request = http.request(options, (response) => {
      const endTime = Date.now();
      const duration = endTime - startTime;

      let data = '';
      response.on('data', chunk => data += chunk);
      response.on('end', () => {
        try {
          const jsonResponse = data ? JSON.parse(data) : null;

          // Check for authentication errors
          if (response.statusCode === 401 || response.statusCode === 403) {
            console.log(`   ⚠️  ${apiName} authenticated BUT access denied (${response.statusCode})`);
            console.log(`   ℹ️  Key format appears valid (had prefix)`);
            resolve(true); // Key has correct format even if not valid
          } else if (response.statusCode >= 400) {
            console.log(`   ❌ ${apiName} returned error (${response.statusCode})`);
            console.log(`   Response: ${jsonResponse?.error || jsonResponse?.message || data}`);
            resolve(false);
          } else if (response.statusCode === 200) {
            console.log(`   ✅ ${apiName} validated successfully (${response.statusCode})`);
            console.log(`   ℹ️  Response: ${formatJSON(jsonResponse || data)}`);
            resolve(true);
          } else {
            console.log(`   ⚠️  ${apiName} returned unexpected status (${response.statusCode})`);
            console.log(`   ℹ️  Duration: ${duration}ms`);
            resolve(true);
          }
        } catch (e) {
          console.log(`   ✅ ${apiName} responded (${response.statusCode}) - ${duration}ms`);
          console.log(`   ℹ️  Body: ${data.substring(0, 200)}`);
          resolve(true);
        }
      });
    });

