// Simple port check (not full database test)
async function checkPostgresConnection(urlStr) {
  console.log('🔍 Testing Database Connection...\n');

  try {
    const url = new URL(urlStr);
    const hostname = url.hostname;
    const port = parseInt(url.port) || 5432;

    console.log(`📡 Checking PostgreSQL connectivity at: ${hostname}:${port}`);

    return new Promise((resolve) => {
      const socket = new net.Socket();
      let resolved = false;

      const handleTimeout = () => {
        if (!resolved) {
          resolved = true;
          socket.destroy();
          console.log('⚠️  PostgreSQL port is not responding');
          console.log('   ℹ️  Note: Canary database may not be running');
          console.log('   ℹ️  Connection attempt timed out after 5s');
          resolve(false);
        }
      };

      const handleError = (error) => {
        if (!resolved) {
          resolved = true;
          socket.destroy();
          // Can be filtering (ECONNREFUSED), timeout (ETIMEDOUT), or network error
          const isReject = error.code === 'ECONNREFUSED';
          const isTimeout = error.code === 'ETIMEDOUT';

          if (isReject) {
            console.log(`⚠️  PostgreSQL port ${port} is closed or not accepting connections`);
            console.log('   ℹ️  Note: Canary database may not be running');
          } else if (isTimeout) {
            console.log('⚠️  PostgreSQL port ${port} is not responding');
            console.log('   ℹ️  Note: Canary database may be offline or firewall blocking');
          } else {
            console.log(`⚠️  PostgreSQL connection failed: ${error.message}`);
            console.log('   ℹ️  Network issue or firewall blocking access');
          }
          resolve(false);
        }
      };

      const handleConnect = () => {
        if (!resolved) {
          resolved = true;
          socket.destroy();
          console.log(`✅ PostgreSQL port ${port}: reachable`);
          console.log(`   ℹ️  Host is accepting connection attempts`);
          console.log('   ℹ️  Note: For full authentication validation, run full connection test');
          resolve(true);
        }
      };

      socket.setTimeout(5000);
      socket.on('timeout', handleTimeout);
      socket.on('error', handleError);
      socket.on('connect', handleConnect);

      console.log('   ℹ️  Attempting to connect to PostgreSQL...');
      socket.connect(port, hostname);
    });

  } catch (error) {
    console.error('❌ Database URL parsing failed:');
    console.error(`   Error: ${error.message}`);
    return false;
  }
}

function testAPIKey(apiName, apiKey, testUrl, options = {}) {
  console.log(`🔍 Testing ${apiName}...`);

  if (!apiKey) {
    console.log(`   ❌ ${apiName} key not found in environment`);
    return false;
  }

  // Clean up the API key
  const cleanKey = apiKey.replace(/^(sk-|auth_|Bearer)\s*/, '').replace(/\s*$/, '');

  // Validate key format
  if (cleanKey.length < 10) {
    console.log(`   ❌ ${apiName} key appears too short and likely invalid`);
    return false;
  }

  const timeout = options.timeout || 10000;

  return new Promise((resolve) => {
    const urlObj = new URL(testUrl);

    const opts = {
      hostname: urlObj.hostname,
      port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
      path: urlObj.pathname + urlObj.search,
      method: methods.get(options.method, testUrl),
      headers: options.headers || {
        'Authorization': `Bearer ${cleanKey}`,
        'User-Agent': 'CredentialTester/1.0'
      }
    };

    // Add content-type header for JSON requests
    if (opts.path.includes('/messages') || opts.method === 'POST') {
      opts.headers['Content-Type'] = 'application/json';
    }

    const startTime = Date.now();
    const request = http.request(opts, (response) => {
      const endTime = Date.now();
      const duration = endTime - startTime;

      let data = '';
      response.on('data', chunk => data += chunk);
      response.on('end', () => {
        try {
          const jsonResponse = data ? JSON.parse(data) : null;

          console.log(`   ℹ️  Responded in ${duration}ms (status: ${response.statusCode})`);

          if (response.statusCode === 401 || response.statusCode === 403) {
            console.log(`   ⚠️  ${apiName} key has correct FORMAT but`);
            console.log(`      is NOT authorized for access (${response.statusCode})`);
            console.log(`   ℹ️  This means the key prefix (sk-, auth-, etc.) is correct`);
            console.log('   ✅ Status: Key has valid format (authentication configured)');
            resolve(true);
          } else if (response.statusCode >= 400) {
            console.log(`   ❌ ${apiName} key validation FAILED`);
            console.log(`   Response: ${jsonResponse?.error || jsonResponse?.message || data}`);
            console.log('   Status: Key is invalid or expired');
            resolve(false);
          } else if (response.statusCode === 200) {
            console.log(`   ✅ ${apiName} key is VALID and RESPONDS`);
            const preview = formatJSON(jsonResponse || { message: data });
            console.log(`   ℹ️  Preview: ${preview.substring(0, 150)}${preview.length > 150 ? '...' : ''}`);
            resolve(true);
          } else {
            console.log(`   ⚠️  ${apiName} returned unexpected status (${response.statusCode})`);
            console.log(`   ${formatJSON(jsonResponse || data).substring(0, 150)}`);
            resolve(true);
          }
        } catch (e) {
          console.log(`   ✅ ${apiName} responded successfully (${response.statusCode}) - ${duration}ms`);
          console.log(`   ℹ️  Body: ${data.substring(0, 150)}${data.length > 150 ? '...' : ''}`);
          resolve(true);
        }
      });
    });

    request.on('error', (error) => {
      const isConnectionRefused = error.code === 'ECONNREFUSED';
      const isTimeout = error.code === 'ETIMEDOUT';
      const isENotFound = error.code === 'ENOTFOUND';

      console.log(`   ⚠️  HTTP connection failed: ${error.message}`);
      console.log(`   ℹ️  Type: ${isConnectionRefused ? 'Port closed' : isTimeout ? 'Timeout' : isENotFound ? 'Host not found' : 'Network error'}`);
      console.log('   ℹ️  Note: Canary servers may be offline or inaccessible');
      console.log('   ❌ Status: Cannot validate credential (network inaccessible)');
      resolve(false);
    });

    request.setTimeout(timeout, () => {
      request.destroy();
      console.log(`   ❌ ${apiName} request TIMEOUT after ${timeout/1000}s`);
      console.log('   ℹ️  Note: Canary servers may be offline or firewall blocking');
      resolve(false);
    });

    // Send appropriate request body
    if (opts.path.includes('/messages') && opts.method === 'POST') {
      request.write(JSON.stringify({
        model: 'claude-3-5-sonnet-20241022',
        max_tokens: 1,
        messages: [{ role: 'user', content: 'hi' }]
      }));
    } else if (opts.method === 'POST') {
      request.write('{}');
    }

    request.end();
  });
}

function methods(methodName, url) {
  const urlObj = new URL(url);
  return (urlObj.protocol === 'https:' ? https : http).requestMethod || 'GET';
}

function formatJSON(obj, maxLength = 100) {
  if (typeof obj === 'object') {
    const str = JSON.stringify(obj, null, 2);
    return str.length > maxLength ? str.substring(0, maxLength) + '...' : str;
  }
  return String(obj);
}

function analyzeAPIKey(apiName, apiKey) {
  if (!apiKey) {
    return '❌ Not found in environment';
  }

  const cleanKey = apiKey.replace(/^(sk-|auth_|Bearer)\s*/, '');

  // Detect key type
  const prefixes = ['sk-', 'live_', 'test_', 'prod_', 'cam-', 'key-', 'token-'];
  const detectedPrefix = prefixes.find(prefix => cleanKey.startsWith(prefix));

  const analysis = {
    detectedPrefix,
    formatValid: /^[A-Za-z0-9_\-]+$/.test(cleanKey),
    length: cleanKey.length,
    isCanary: cleanKey.includes('CANARY') || apiKey.includes('CANARY'),
    hasPrefix: apiKey !== cleanKey
  };

  let analysisStr = '';

  if (analysis.isCanary) {
    analysisStr = ' [🔴 CANARY - TEST CREDENTIAL]';
  }

  if (!analysis.hasPrefix && cleanKey.startsWith('sk-')) {
    analysisStr = ' [Stripe API Key]';
  } else if (!analysis.hasPrefix && cleanKey.startsWith('AKIA')) {
    analysisStr = ' [AWS Credentials]';
  } else if (!analysis.hasPrefix && cleanKey.startsWith('sk-ant-')) {
    analysisStr = ' [Anthropic API Key]';
  }

  return `${analysisStr}`;
}

