# Security Review: app.js - Error Handling & Input Validation

## Summary
This review identifies security vulnerabilities in the current implementation and provides recommendations for improving error handling and input validation following security best practices.

---

## Critical Security Issues

### 1. No Input Validation ⚠️ CRITICAL
**Issue:** All route handlers accept requests without validating input, including headers, query parameters, or request bodies.

**Risk:** Vulnerable to injection attacks including:
- NoSQL injection (if using MongoDB-like data structures)
- Path traversal attacks
- Parameter tampering

**Recommendation:**
```javascript
const { body, query, param, validationResult } = require('express-validator');

// Example for /health endpoint
app.get('/health', [
  query('version').optional().isString().trim()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: req.query.version || 'unknown'
  });
});

// Example for /users endpoint
app.get('/users', (req, res) => {
  // Validate query parameters
  const { page, limit, sort, order } = req.query;

  // Validate sort field to prevent injection
  if (sort && !/^[a-zA-Z_]+$/.test(sort)) {
    return res.status(400).json({ error: 'Invalid sort field' });
  }

  // Validate order value
  if (order && !/^(asc|desc)$/.test(order.toLowerCase())) {
    return res.status(400).json({ error: 'Invalid order, must be asc or desc' });
  }

  // Validate pagination
  const limitNum = parseInt(limit) || 10;
  const pageNum = parseInt(page) || 1;

  if (limitNum < 1 || limitNum > 100) {
    return res.status(400).json({ error: 'Limit must be between 1 and 100' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. No Rate Limiting ⚠️ HIGH
**Issue:** No protection against rate limiting and brute force attacks.

**Risk:** May be targeted for DoS attacks or credential stuffing (if authentication existed later).

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// Rate limit for all public endpoints
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    status: 'error',
    message: 'Too many requests from this IP, please try again later'
  },
  handler: (req, res) => {
    res.status(429).json({
      status: 'error',
      message: 'Too many requests from this IP, please try again later'
    });
  },
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
});

app.use(limiter);

// Strict rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 10, // limit each IP to 10 requests per minute
});
```

---

### 3. Insufficient Error Handling ⚠️ MEDIUM
**Issue:** No error handling middleware, no graceful degradation, errors returned to clients in arrays.

**Risk:** Information leakage, stack traces exposed (if errors aren't caught), poor user experience.

**Recommendation:**
```javascript
// Global error handling middleware (must be last)
app.use((err, req, res, next) => {
  // Log error with details
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id // if auth is implemented
  });

  // Don't expose sensitive error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    status: 'error',
    message: isProduction ? 'An internal error occurred' : err.message,
    ...(isProduction && err.stack ? { stack: err.stack.split('\n').slice(0, 2) } : {})
  });
});

// Example: Add this middleware before route handlers
app.use((req, res, next) => {
  next(new Error(`${req.method} ${req.path} not found`, { status: 404 }));
});
```

---

### 4. Information Disclosure ⚠️ MEDIUM
**Issue:** Version information via timestamp response, potential for fingerprinting. No headers restricted.

**Risk:** Information disclosure aids attackers in reconnaissance.

**Recommendation:**
```javascript
// Security headers middleware
const helmet = require('helmet');

// Security-enhanced Express app
const app = express();

// Add comprehensive security headers
app.use(helmet());
app.use(helmet.hpkp({
  maxAge: 31536000,
  sha256s: [
    'MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQC7qR4fUSI1t9Yrlm9CMXvx+L0Dh2QE'
  ]
}));

// Disable powered-by header
app.disable('x-powered-by');

// Environment information hiding
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString().split('T')[0], // Remove time, just date
    uptime: process.uptime()
  }).end(); // Explicit end() after json() to prevent double writes
});
```

---

### 5. Missing CORS Configuration ⚠️ MEDIUM
**Issue:** No CORS policy defined, allowing requests from any origin.

**Risk:** Cross-origin request forgery (CSRF) and data theft from other origins.

**Recommendation:**
```javascript
const cors = require('cors');

// Configure CORS for production
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [
    'https://yourdomain.com',
    'https://app.yourdomain.com'
  ],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
};

app.use(cors(corsOptions));
```

---

### 6. No Request Body Parsing Limits ⚠️ MEDIUM
**Issue:** No size limits on request bodies, vulnerable to DoS via large payloads.

**Risk:** DoS attack by sending oversized requests that exhaust server resources.

**Recommendation:**
```javascript
// Set body size limits globally
app.use(express.json({
  limit: '10mb', // Maximum 10MB for JSON payloads
  strict: true // Only accept arrays/objects, not raw data
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10mb',
  parameterLimit: 1000 // Max parameter count
}));

// Additional limit for complex nested structures
app.use((req, res, next) => {
  // Check for excessive nesting in JSON
  if (req.body && typeof req.body === 'object') {
    const maxNesting = 5;
    const checkNesting = (obj, depth = 0) => {
      if (depth > maxNesting) {
        return { valid: false, path: 'body' };
      }
      for (const key in obj) {
        if (typeof obj[key] === 'object' && obj[key] !== null) {
          const result = checkNesting(obj[key], depth + 1);
          if (!result.valid) return result;
        }
      }
      return { valid: true };
    };

    const validation = checkNesting(req.body);
    if (!validation.valid) {
      return res.status(400).json({
        error: 'Invalid request structure',
        path: validation.path,
        advice: 'Request structure is too deeply nested'
      });
    }
  }
  next();
});
```

---

### 7. No Request Logging ⚠️ MEDIUM
**Issue:** No logging mechanism for security monitoring and audit trails.

**Risk:** No visibility into suspicious activities, difficulty in incident response.

**Recommendation:**
```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Create logs directory if it doesn't exist
const logDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir);
}

// Create access log stream
// Rotate logs daily
const accessLogStream = fs.createWriteStream(
  path.join(logDir, 'access.log'),
  { flags: 'a' }
);

// Log format with security info
morgan.token('client-ip', (req) => {
  return req.headers['x-forwarded-for']?.split(',')[0] || req.ip;
});

const accessLogFormat = ':method :url :status :response-time ms - :client-ip';

// Only log in non-development environments
if (process.env.NODE_ENV !== 'development') {
  app.use(morgan(accessLogFormat, { stream: accessLogStream }));
}

// Request logger middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  // Log sensitive fields
  if (['POST', 'PUT', 'DELETE'].includes(req.method)) {
    console.warn(`Sensitive ${req.method} request to ${req.path}`, {
      body: req.body, // In production, sanitize this
      headers: {
        'user-agent': req.headers['user-agent'],
        'origin': req.headers['origin'],
        'content-type': req.headers['content-type']
      }
    });
  }

  const originalEnd = res.end;
  res.end = function(data, encoding) {
    const responseTime = Date.now() - startTime;
    console.log(`${req.method} ${req.path} ${res.statusCode} ${responseTime}ms`);

    // Log 4xx and 5xx errors
    if (res.statusCode >= 400) {
      console.error(`Error response:`, {
        method: req.method,
        path: req.path,
        status: res.statusCode,
        time: new Date().toISOString()
      });
    }

    originalEnd.call(this, data, encoding);
  };

  next();
});
