      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  referrerPolicy: { policy: 'no-referrer' },
  xssFilter: true,
}));

// Request size limits
app.use(express.json({
  limit: '10mb', // 10MB maximum JSON payload
  strict: true, // Only accept arrays/objects, not raw data
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10mb',
  parameterLimit: 1000, // Max parameter count
}));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [
    'https://yourdomain.com',
    'https://app.yourdomain.com'
  ],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Request-ID', 'X-RateLimit-Limit'],
  maxAge: 86400, // 24 hours
  preflightContinue: true,
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    status: 'error',
    error: 'TOO_MANY_REQUESTS',
    message: 'Too many requests from this IP, please try again later',
    retryAfter: Math.ceil((15 * 60 * 1000) / 100)
  },
  handler: (req, res) => {
    res.status(429).json({
      status: 'error',
      error: 'TOO_MANY_REQUESTS',
      message: 'Too many requests from this IP, please try again later',
      retryAfter: Math.ceil((15 * 60 * 1000) / 100)
    });
  },
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
});

// Strict rate limiting for all endpoints
app.use(limiter);

// Logging configuration
const logDir = __dirname + '/logs';
const fs = require('fs');
// Create logs directory if it doesn't exist
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir, { recursive: true });
}

// Request logger middleware
app.use((req, res, next) => {
  const startTime = Date.now();
  const requestId = crypto.randomUUID ? crypto.randomUUID() : Date.now() + '-' + Math.random().toString(36).substr(2, 9);

  // Add request ID to response
  res.setHeader('X-Request-ID', requestId);

  // Log method and path
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);

  // Log sensitive fields for POST/PUT/DELETE requests
  if (['POST', 'PUT', 'DELETE'].includes(req.method)) {
    console.warn(`[${new Date().toISOString()}] Sensitive ${req.method} request to ${req.path}`, {
      headers: {
        'content-type': req.headers['content-type'],
        'origin': req.headers['origin'],
        'user-agent': req.headers['user-agent'],
      }
    });
  }

  // Override res.end to capture response time and log errors
  const originalEnd = res.end;
  res.end = function(data, encoding) {
    const responseTime = Date.now() - startTime;

    // Log entire response for debugging
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} ${res.statusCode} (${responseTime}ms)`, {
      requestId: requestId
    });

    // Log errors
    if (res.statusCode >= 400) {
      console.error(`[${new Date().toISOString()}] ERROR: ${req.method} ${req.path} returned ${res.statusCode}`, {
        error: res.statusCode,
        path: req.path,
        method: req.method,
        timestamp: new Date().toISOString(),
        time: responseTime
      });
    }

    originalEnd.call(this, data, encoding);
  };

  next();
});

// ==================== Input Validation Middleware ====================

// Validate common patterns
const sanitizeInput = (input) => {
  if (!input) return '';
  return String(input)
    .trim()
    .replace(/[\x00-\x1F\x7F]/g, '') // Remove control characters
    .replace(/\.{2,}/g, '.') // Collapse multiple dots
    .replace(/%0A|%0D/g, ''); // Remove line breaks
};

// ==================== Routes ====================

// Health check endpoint with validation
const validateHealthRequest = [
  query('version').optional().isString().trim().isLength({ max: 50 }),
  query('debug').optional().matches(/^(true|false)$/i),
];

app.get('/health', validateHealthRequest, (req, res) => {
