  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      error: 'VALIDATION_ERROR',
      message: 'Invalid request parameters',
      details: errors.array()
    });
  }

  // Sanitize version if present
  const version = req.query.version
    ? sanitizeInput(req.query.version)
    : 'unknown';

  // Get debug flag safely
  const debug = req.query.debug
    ? (req.query.debug.toLowerCase() === 'true')
    : false;

  const response = {
    status: 'ok',
    timestamp: new Date().toISOString().split('T')[0], // Only date for privacy
    uptime: process.uptime(),
    version: version
  };

  // Only include debug info in development
  if (debug && process.env.NODE_ENV === 'development') {
    response.memory = process.memoryUsage();
    response.processId = process.pid;
  }

  res.json(response);
});

// Users endpoint with enhanced validation
app.get('/users', (req, res) => {
  try {
    // Extract and validate query parameters
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const sortField = req.query.sort;
    const order = req.query.order;

    // Validate pagination
    if (page < 1) {
      return res.status(400).json({
        status: 'error',
        error: 'VALIDATION_ERROR',
        message: 'Page must be greater than 0'
      });
    }

    if (limit < 1 || limit > 100) {
      return res.status(400).json({
        status: 'error',
        error: 'VALIDATION_ERROR',
        message: 'Limit must be between 1 and 100'
      });
    }

    // Validate sort field (prevent injection attacks)
    if (sortField && !/^[a-zA-Z_]+$/.test(sortField)) {
      return res.status(400).json({
        status: 'error',
        error: 'VALIDATION_ERROR',
        message: 'Invalid sort field',
        details: 'Sort field must contain only letters and underscores'
      });
    }

    // Validate order value
    if (order && !/^(asc|desc)$/i.test(order)) {
      return res.status(400).json({
        status: 'error',
        error: 'VALIDATION_ERROR',
        message: 'Order must be asc or desc',
        details: `Received: "${order}"`
      });
    }

    // Basic user data (in production, this would come from a database)
    const users = [
      { id: 1, name: sanitizeInput('Alice'), email: 'alice@example.com' },
      { id: 2, name: sanitizeInput('Bob'), email: 'bob@example.com' }
    ];

    // Apply sorting if specified
    if (sortField) {
      users.sort((a, b) => {
        const aVal = a[sortField];
        const bVal = b[sortField];
        const comparison = aVal.localeCompare(bVal);
        return order.toLowerCase() === 'desc' ? -comparison : comparison;
      });
    }

    // Apply pagination
    const paginatedUsers = users.slice(
      (page - 1) * limit,
      page * limit
    );

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  } catch (error) {
    // Handle unexpected errors in route handler
    console.error(`[${new Date().toISOString()}] Error in /users endpoint:`, error);
    res.status(500).json({
      status: 'error',
      error: 'INTERNAL_SERVER_ERROR',
      message: 'An error occurred while processing your request'
    });
  }
});

// ==================== Error Handling Middleware ====================

// Not found handler (should be last route handler)
app.use((req, res, next) => {
  next(new Error(`Route ${req.method} ${req.path} not found`, { status: 404 }));
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  // Log detailed error information
  const errorDetails = {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    headers: {
      'user-agent': req.headers['user-agent'],
      'origin': req.headers['origin'],
      'content-type': req.headers['content-type'],
    }
  };

  // In development, include stack trace and more details
  if (process.env.NODE_ENV === 'development') {
    errorDetails.stack = err.stack;
    errorDetails.query = req.query;
    errorDetails.body = req.body;
  }

  console.error(`[${new Date().toISOString()}] ERROR:`, errorDetails);

  const isProduction = process.env.NODE_ENV === 'production';

  // Determine status code
  const statusCode = err.status || (err.statusCode || 500);

  // Don't expose sensitive information in production
  const response = {
    status: 'error',
    error: statusCode >= 500 ? 'INTERNAL_SERVER_ERROR' : 'BAD_REQUEST',
    message: isProduction
      ? 'An internal error occurred'
      : err.message
  };

  // Don't expose full stack trace in production
  if (isProduction === false && err.stack) {
    response.stack = err.stack.split('\n').slice(0, 3);
  }

  res.status(statusCode).json(response);
});

// ==================== Server Configuration ====================

const PORT = process.env.PORT || process.env.PORT_DEFAULT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const NODE_ENV = process.env.NODE_ENV || 'production';

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force exit after 10 seconds
  setTimeout(() => {
    console.error('Error: Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  setTimeout(() => {
    console.error('Error: Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
});

// Start server
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} in ${NODE_ENV} mode`);
  console.log(`Health check: http://${HOST === '0.0.0.0' ? 'localhost' : HOST}:${PORT}/health`);

  if (NODE_ENV !== 'production') {
    console.log('Development mode enabled');
    console.log('Note: In production, remove `debug` query parameter from health checks');
  }
});

// Handle server errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Error: Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

module.exports = app;

# Critical Security Fixes: Quick Reference Guide

## 🚨 What Should You Do Today

### 1. Input Validation (Most Critical)
**Before:**
```javascript
app.get('/users', (req, res) => {
  // No validation at all!
  res.json([...]);
});
```

**After:**
```javascript
app.get('/users', (req, res) => {
  // Validate pagination limits
  const limit = parseInt(req.query.limit) || 10;
  if (limit < 1 || limit > 100) {
    return res.status(400).json({ error: 'Invalid limit' });
  }

  // Validate sort field prevents injection attacks
  const sort = req.query.sort;
  if (sort && !/^[a-zA-Z_]+$/.test(sort)) {
    return res.status(400).json({ error: 'Invalid sort field' });
  }

  res.json([...]);
});
```

### 2. Rate Limiting (Prevents DoS)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP
});

app.use(limiter);
```

### 3. Global Error Handling
```javascript
// Add this BEFORE your routes
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({
    status: 'error',
    message: err.message
  });
});
```

### 4. Restrict Headers
```javascript
const helmet = require('helmet');

// Add this immediately after creating app
app.use(helmet());

// Disable X-Powered-By header
app.disable('x-powered-by');
```

### 5. Security Headers
```javascript
const cors = require('cors');

app.use(cors({
  origin: ['https://allowed-domain.com'], // Validate origins
  credentials: true,
}));
```

