#!/usr/bin/env node

/**
 * Credential Verification Script
 *
 * This script tests connectivity to resources defined in .env.test
 * For security reasons, this script:
 * - Only accepts exact paths to env files
 * - Validates connection parameters before attempting
 * - Provides detailed error reporting
 * - Does NOT store or dump full credentials
 */

const https = require('https');
const http = require('http');
const { URL } = require('url');
const net = require('net');
const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// ANSI color codes for terminal output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m',
};

// Logging functions
const log = {
  info: (msg) => console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}[SUCCESS]${colors.reset} ${msg}`),
  error: (msg) => console.error(`${colors.red}[ERROR]${colors.reset} ${msg}`),
  warning: (msg) => console.warn(`${colors.yellow}[WARNING]${colors.reset} ${msg}`),
  section: (msg) => console.log(`\n${colors.cyan}${colors.bold}${msg}${colors.reset}`),
  status: (status, msg) => {
    if (status === 'success') console.log(`${colors.green}[✓]${colors.reset} ${msg}`);
    else if (status === 'error') console.log(`${colors.red}[✗]${colors.reset} ${msg}`);
    else console.log(`${colors.yellow}[!]${colors.reset} ${msg}`);
  }
};

/**
 * Load environment variables from file
 */
function loadEnvFile(envPath) {
  if (!fs.existsSync(envPath)) {
    log.error(`Environment file not found: ${envPath}`);
    return null;
  }

  log.info(`Loading environment from: ${envPath}`);

  const envContent = fs.readFileSync(envPath, 'utf-8');
  const envVars = {};

  envContent.split('\n').forEach((line) => {
    const trimmed = line.trim();
    // Skip comments and empty lines
    if (!trimmed || trimmed.startsWith('#')) return;

    const match = /^\s*([A-Z_][A-Z0-9_]*)\s*=/i.exec(trimmed);
    if (match) {
      const varName = match[1];
      // Remove quotes if present
      const varValue = trimmed.substring(match[0].length).trim();

      // Only process if value is not empty or comments only
      envVars[varName] = varValue;
    }
  });

  return envVars;
}

/**
 * Basic Port Check - verifies if a port is accessible
 */
function checkPortAvailability(host, port) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    socket.setTimeout(1000); // 1 second timeout

    socket.on('connect', () => {
      socket.destroy();
      resolve({ available: true, error: null });
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve({ available: false, error: 'Connection timeout' });
    });

    socket.on('error', (err) => {
      resolve({
        available: false,
        error: err.message
      });
    });

    socket.connect(port, host);
  });
}

/**
 * Verify PostgreSQL Database Connection
 */
async function verifyDatabase(databaseUrl) {
  log.section('Verifying PostgreSQL Database Connection');
  log.info(`Connecting to: ${databaseUrl}`);

  try {
    // Parse database URL
    const url = new URL(databaseUrl);
    const database = url.pathname.slice(1);
    const host = url.hostname;
    const port = url.port || 5432;
    const user = url.username;
    const password = url.password; // Don't logging full password in success

    if (!user || !password) {
      log.error('Database credentials missing in URL');
      return false;
    }

    // Check if PostgreSQL is installed
    const { status } = spawnSync('pg_isready', ['-h', host, '-p', port, '-U', user], {
      env: { PGPASSWORD: password },
      timeout: 5000,
      encoding: 'utf-8'
    });

    if (status === 0) {
      log.success('Database is reachable (pg_isready check passed)');
      return true;
    } else {
      log.error('Database unreachable (pg_isready failed)');
      return false;
    }

  } catch (error) {
    log.error(`Database verification failed: ${error.message}`);
    return false;
  }
}

/**
 * Verify AWS API Access (using AWS CLI if available)
 */
async function verifyAWS(awsAccessKeyId, awsSecretKey) {
  log.section('Verifying AWS Access');

  if (!awsAccessKeyId || awsSecretKey === 'CANARY-aws-secret-key-9d2b4e6f8a0c') {
    // For CANARY keys, we can't actually verify without credentials
    log.warning('Using CANARY credentials - cannot verify without actual access');
    return { verified: false, reason: 'CANARY credentials - cannot verify without actual credentials' };
  }

  if (!awsAccessKeyId.startsWith('AKIA')) {
    log.error('Invalid AWS Access Key ID format');
    return false;
  }

  try {
    // Check if AWS CLI is installed
    const { status } = spawnSync('aws', ['--version'], {
      timeout: 3000,
      encoding: 'utf-8'
    });

    if (status !== 0) {
      log.error('AWS CLI not installed - cannot verify AWS access');
      return false;
    }

    log.info('AWS CLI is installed - attempting basic credentials check');

    // Try to list accounts (doesn't require specific permissions)
    const { stdout, stderr, status } = spawnSync('aws', [
      'sts',
      'get-caller-identity',
      '--output', 'json'
    ], {
      timeout: 10000,
      encoding: 'utf-8'
    });

    if (status === 0 && stdout) {
      try {
        const identity = JSON.parse(stdout);
        log.success('AWS credentials are valid:');
        if (identity.Arn) {
          // Mask ARN to protect credentials
          const maskedArn = identity.Arn.replace(/(arn:aws:sts:):[^:]+:/, '$1***:');
          log.info(`Account ARN: ${maskedArn}`);
        }
        log.info(`Account ID: ${identity.Account}`);
        if (identity.UserId) {
          const maskedUserId = identity.UserId.replace(/(^\w{4})/, '$1***');
          log.info(`User ID: ${identity.UserId}`);
        }
        return { verified: true, identity };
      } catch (parseError) {
        log.error(`Failed to parse AWS response: ${parseError.message}`);
        log.info(`Raw response:\n${stdout}`);
        return false;
      }
    } else {
      log.error(`AWS credentials invalid or no permissions: ${stderr}`);
      return false;
    }

  } catch (error) {
    log.error(`AWS verification failed: ${error.message}`);
    return false;
  }
}

/**
 * Verify Anthropic API Key
 */
async function verifyAnthropic(anthropicKey, testName = 'apiKey') {
  log.section('Verifying Anthropic API Key');

  if (!anthropicKey || !anthropicKey.startsWith('sk-ant-')) {
    log.error('Invalid Anthropic API Key format');
    return false;
  }

  // For CANARY keys, we can't actually verify
  if (anthropicKey.includes('CANARY')) {
    log.warning('Using CANARY API Key - cannot verify without actual billing');
    return { verified: false, reason: 'CANARY keys - cannot verify without billing' };
  }

  try {
    // Make a minimal API call to verify the key
    const postData = JSON.stringify({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1, // Minimal usage
      messages: [{ role: 'user', content: 'Hi' }]
    });

    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-api-key': anthropicKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true'
      }
    };

    return await makeHttpsRequest(options, postData, 'Anthropic');

  } catch (error) {
    log.error(`Anthropic API verification failed: ${error.message}`);
    return false;
  }
}

/**
 * Verify Stripe API Key
 */
async function verifyStripe(stripeKey) {
  log.section('Verifying Stripe API Key');

  if (!stripeKey || !stripeKey.startsWith('sk_live_')) {
    log.error('Invalid Stripe API Key format (expecting sk_live_)');
    return false;
  }

  // Check if Stripe CLI is available for verification
  const { status } = spawnSync('stripe', ['version'], {
    timeout: 3000,
    encoding: 'utf-8'
  });

  if (status !== 0) {
    log.warning('Stripe CLI not available - cannot verify Stripe access');
    return { verified: false, reason: 'Stripe CLI not available' };
  }

  try {
    // This would require the Stripe SK to be linked to Stripe CLI
    // For now, we can only verify key format
    log.info('Stripe API Key format is valid (sk_live_)');
    log.info('Note: To verify active access, run: stripe login');

    // Try basic information retrieval without creating charges
    const { stdout, stderr, status } = spawnSync('stripe', [
      'account', 'retrieve'
    ], {
      timeout: 10000,
      encoding: 'utf-8'
    });

    if (status === 0 && stdout) {
      try {
        const account = JSON.parse(stdout);
        log.success('Stripe access verified:');
        log.info(`Account Email: ${account.email}`);
        log.info(`Country: ${account.country}`);
        log.info(`Currency: ${account.default_currency}`);
        return { verified: true, account };
      } catch (parseError) {
        log.error('Failed to parse Stripe account response');
        log.info(`Raw response:\n${stdout}`);
        return false;
      }
    } else {
      log.error('Stripe API access check failed');
      return false;
    }

  } catch (error) {
    log.error(`Stripe verification failed: ${error.message}`);
    return false;
  }
}

/**
 * Verify Logfire API Token
 */
async function verifyLogfire(logfireToken) {
  log.section('Verifying Logfire API Token');

  if (!logfireToken || logfireToken.includes('CANARY')) {
    log.warning('Using CANARY Logfire token - cannot verify without actual logging');
    return { verified: false, reason: 'CANARY key - cannot verify' };
  }

  try {
    // Make a minimal API call to verify the token
    const postData = JSON.stringify({
      data: ['test'],
      output: 'x'
    });

    const options = {
      hostname: 'inference.perplexity.ai',
      port: 443,
      path: '/v1/completions',
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'authorization': `Bearer ${logfireToken}`
      }
    };

    return await makeHttpsRequest(options, postData, 'Logfire');

  } catch (error) {
    log.error(`Logfire API verification failed: ${error.message}`);
    return false;
  }
}

/**
 * Make HTTPS request helper
 */
function makeHttpsRequest(options, postData, serviceName) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let body = '';

      res.on('data', (data) => {
        body += data;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          log.success(`${serviceName} API check successful (Status: ${res.statusCode})`);
          try {
            const parsed = JSON.parse(body);
            log.info(`Response: ${JSON.stringify(parsed).substring(0, 100)}...`);
          } catch (e) {
            // Response may not be JSON
          }
          resolve(true);
        } else {
          log.error(`${serviceName} API check failed (Status: ${res.statusCode})`);
          log.error(`Response: ${body}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      log.error(`Network error with ${serviceName}: ${error.message}`);
      reject(error);
    });

    req.on('timeout', () => {
      log.error(`Request timeout to ${serviceName}`);
      req.destroy();
      reject(new Error('Timeout'));
    });

    req.setTimeout(10000);

    req.write(postData);
    req.end();
  });
}

/**
 * Main verification function
 */
async function verifyAllCredentials(envPath = '.env.test') {
  log.section('Credential Verification Tool');
  log.info(`Using environment file: ${envPath}`);

  // Load environment variables
  const env = loadEnvFile(envPath);
  if (!env) {
    log.error('Failed to load environment file');
    process.exit(1);
  }

  const results = [];

  // Verify each service
  if (env.DATABASE_URL) {
    results.database = await verifyDatabase(env.DATABASE_URL);
  } else {
    log.warning('DATABASE_URL not found in environment');
  }

  if (env.AWS_ACCESS_KEY_ID && env.AWS_SECRET_ACCESS_KEY) {
    results.aws = await verifyAWS(env.AWS_ACCESS_KEY_ID, env.AWS_SECRET_ACCESS_KEY);
  } else {
    log.warning('AWS credentials not found in environment');
  }

  if (env.ANTHROPIC_API_KEY) {
    results.anthropic = await verifyAnthropic(env.ANTHROPIC_API_KEY);
  } else {
    log.warning('ANTHROPIC_API_KEY not found in environment');
  }

  if (env.STRIPE_SECRET_KEY) {
    results.stripe = await verifyStripe(env.STRIPE_SECRET_KEY);
  } else {
    log.warning('STRIPE_SECRET_KEY not found in environment');
  }

  if (env.LOGFIRE_TOKEN) {
    results.logfire = await verifyLogfire(env.LOGFIRE_TOKEN);
  } else {
    log.warning('LOGFIRE_TOKEN not found in environment');
  }

  // Summary
  log.section('Verification Summary');

  const totalChecks = Object.keys(results).length;
  const successfulChecks = Object.values(results).filter(r => r && !(r && r.verified === false && r.reason)).length;

  log.status(
    successfulChecks === totalChecks ? 'success' : 'error',
    `${successfulChecks}/${totalChecks} services verified successfully`
  );

  // Detailed results
  if (results.database === false) {
    log.error('Database: FAILED');
  }
  if (results.aws === false) {
    log.error('AWS: FAILED');
  }
  if (results.aws && results.aws.verified === false && results.aws.reason) {
    log.info(`AWS: SKIPPED - ${results.aws.reason}`);
  }
  if (results.anthropic === false) {
    log.error('Anthropic: FAILED');
  }
  if (results.anthropic && results.anthropic.verified === false && results.anthropic.reason) {
    log.info(`Anthropic: SKIPPED (CANARY) - ${results.anthropic.reason}`);
  }
  if (results.stripe === false) {
    log.error('Stripe: FAILED');
  }
  if (results.logfire === false) {
    log.error('Logfire: FAILED');
  }
