# Security Review: Error Handling and Input Validation

## Summary

Based on the simple Express.js application found, here are comprehensive security improvements focusing on error handling and input validation.

---

## Critical Security Issues Identified

### 1. **Missing Error Handling Hooks** ⚠️ CRITICAL

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Issues:**
- No error handling for the server startup
- If port 3000 is already in use, the app crashes silently
- No graceful shutdown handling

**Recommended Fix:**
```javascript
const { notStrictEqual: isNotStrictEqual } = require('assert');

const port = process.env.PORT || 3000;
const server = app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${port} is already in use.`);
  } else {
    console.error('Server error:', error.message);
  }
  process.exit(1);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

### 2. **Missing Input Validation for Query Parameters** ⚠️ HIGH

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Issues:**
- No validation of request parameters
- Potential for NoSQL injection if this endpoint accesses a database
- No input sanitization

**Recommended Fix:**
```javascript
const { body, param, query, validationResult } = require('express-validator');

app.get(
  '/users',
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('sort')
      .optional()
      .isIn(['name', 'email', 'id'])
      .withMessage('Invalid sort field'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array(),
      });
    }

    // Safe to proceed with validated parameters
    const { page = 1, limit = 10 } = req.query;

    // Your actual data retrieval logic here
    res.json({
      data: [...], // Your validated data
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: 0, // Your total count
      },
    });
  }
);
```

### 3. **Missing Input Validation for Headers (Kinna demo app logic)**

**Recommended Fix:**
```javascript
// Validate Content-Type header for POST requests
const contentType = req.headers['content-type'];

if (!contentType || !contentType.includes('application/json')) {
  return res.status(415).json({
    status: 'error',
    message: 'Content-Type must be application/json',
  });
}
```

---

## Additional Security Improvements

### 4. **Missing rate limiting** ⚠️ HIGH

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: {
    status: 'error',
    message: 'Too many requests from this IP, please try again later.',
  },
});

// Apply to all routes
app.use(generalLimiter);

// Health check endpoint - higher rate limit
app.get('/health', (req, res, next) => {
  // Custom health check logic if needed
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Critical endpoint - more strict limiting
const criticalLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 10,
  message: {
    status: 'error',
    message: 'Rate limit exceeded for this endpoint.',
  },
});
```

### 5. **Missing input sanitization** ⚠️ MEDIUM

**Recommended Fix:**
```javascript
const { body, validationResult } = require('express-validator');
const { sanitizeBody } = require('express-validator');

// For any POST/PATCH request
app.put(
  '/users/:id',
  [
    sanitizeBody('name').trim().escape(), // Prevent XSS
    sanitizeBody('email').normalizeEmail({ gmail_remove_dots: false }),
    body('name')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters'),
    body('email')
      .isEmail()
      .withMessage('Invalid email address'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array(),
      });
    }
    // Process sanitized inputs
  }
);
```

### 6. **Missing Input Validation for ID Parameters** ⚠️ HIGH

**Recommended Fix:**
```javascript
app.get(
  '/users/:id',
  [
    param('id')
      .isLength({ min: 1, max: 100 })
      .matches(/^[a-fA-F0-9]+$/)
      .withMessage('Invalid user ID format'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array(),
      });
    }
    // Safe to proceed with validated user ID
  }
);
```

### 7. **Missing Path Traversal Protection** ⚠️ HIGH

**Recommended Fix:**
```javascript
const path = require('path');
const { body, param } = require('express-validator');
const { custom } = require('express-validator');

app.get('/files/:filename', [
  param('filename')
    .custom(validator.isFilename),
], (req, res) => {
  // Use the validated filename, not req.params.filename directly
  const filePath = path.join(__dirname, 'uploads', req.params.filename);
  // Safe file operations
});

const validator = {
  isFilename: (value) => {
    // Prevent path traversal attacks
    const regex = /^[a-zA-Z0-9_\-.]+$/;
    if (!regex.test(value)) {
      throw new Error('Invalid filename');
    }
    if (value.includes('..')) {
      throw new Error('Path traversal detected');
    }
    return true;
  }
};
```

### 8. **Missing HTTP Security Headers** ⚠️ MEDIUM

**Recommended Fix:**
```javascript
const helmet = require('helmet');

// Security headers middleware
app.use(helmet({
  contentSecurityPolicy: false, // Disable if needed for specific reasons
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  xssFilter: true,
  noSniff: true,
  hidePoweredBy: true,
}));

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});
```

### 9. **Missing CORS Configuration** ⚠️ MEDIUM

**Recommended Fix:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400,
}));
```

### 10. **Missing input validation for JSON body parsers** ⚠️ MEDIUM

**Recommended Fix:**
```javascript
const bodyParser = require('body-parser');
const { body } = require('express-validator');

// Enhanced body parser with size limits
app.use(bodyParser.json({
  limit: '1mb', // Prevents denial of service via large payloads
  verify: (req, res, buf) => {
    req.rawBody = buf.toString('utf8');
  }
}));

app.use(bodyParser.urlencoded({
  extended: true,
  limit: '1mb',
}));
```

### 11. **Missing security logging** ⚠️ LOW

**Recommended Fix:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Error handling middleware with logging
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  if (!res.headersSent) {
    res.status(err.status || 500).json({
      status: 'error',
      message: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
    });
  }
  next(err);
});

// Security event logging
app.use((req, res, next) => {
  if (req.method !== 'GET') {
    logger.info('Request received', {
      method: req.method,
      path: req.path,
      ip: req.ip,
      userAgent: req.userAgent,
    });
  }
  next();
});
```

### 12. **Missing environment validation** ⚠️ MEDIUM

**Recommended Fix:**
```javascript
const dotenv = require('dotenv');
const Joi = require('joi');

// Load and validate environment variables
require('dotenv').config();

const envSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'production', 'test')
    .default('development'),
  PORT: Joi.number()
    .port()
    .default(3000),
  APP_URL: Joi.string().uri().default('http://localhost:3000'),
  DATABASE_URL: Joi.string().uri(),
  SESSION_SECRET: Joi.string().min(32).required(),
  ALLOWED_ORIGINS: Joi.string(),
}).required();

const { error, value: envValues } = envSchema.validate(process.env);

if (error) {
  throw new Error(`Environment validation error: ${error.details[0].message}`);
}

// Use validated values
const { NODE_ENV, PORT, APP_URL, DATABASE_URL, SESSION_SECRET, ALLOWED_ORIGINS } = envValues;
```

### 13. **Missing request body size validation** ⚠️ LOW

**Recommended Fix:**
```javascript
const express = require('express');
const app = express();

// Limit the size of JSON and URL-encoded request bodies
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));

app.use((req, res, next) => {
  const contentLength = req.headers['content-length'];
  const maxSize = 1 * 1024 * 1024; // 1MB

  if (contentLength && parseInt(contentLength) > maxSize) {
    return res.status(413).json({
      status: 'error',
      message: 'Request body too large',
    });
  }
  next();
});
```

### 14. **Missing response sanitization** ⚠️ LOW

**Recommended Fix:**
```javascript
const sanitize = require('sanitize-html');

// Helper function to sanitize responses
function sanitizeResponse(data) {
  if (typeof data === 'string') {
    return sanitize(data, {
      allowedTags: [],
      allowedAttributes: {},
    });
  }
  if (typeof data === 'object' && data !== null) {
    return Object.entries(data).reduce((acc, [key, value]) => {
      acc[key] = sanitize(value, {
        allowedTags: [],
        allowedAttributes: {},
      });
      return acc;
    }, {});
  }
  return data;
}

// Apply to responses
app.get('/users', (req, res) => {
  const users = [/* ... */];

  // Sanitize response data
  const sanitizedUsers = users.map(user => sanitizeResponse(user));

  res.json({
    status: 'success',
    data: sanitizedUsers,
  });
});
```

---

## Error Handling Best Practices

### Centralized Error Handler
```javascript
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Middleware to handle operational errors
const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;

  // Log error
  logger.error({
    message: err.message,
    stack: err.stack,
  });

  // Mongoose bad ObjectId
  if (err.name === 'CastError') {
    const message = 'Resource not found';
    error = new AppError(message, 404);
  }

  // Mongoose duplicate key
  if (err.code === 11000) {
    const message = 'Duplicate field value entered';
    error = new AppError(message, 400);
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const message = Object.values(err.errors).map(val => val.message).join(', ');
    error = new AppError(message, 400);
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    const message = 'Invalid token';
    error = new AppError(message, 401);
  }

  if (err.name === 'TokenExpiredError') {
    const message = 'Token expired';
    error = new AppError(message, 401);
  }

  // Operation-specific errors
  if (err.isOperational) {
    res.status(error.statusCode || 500).json({
      status: 'error',
      message: error.message,
    });
  } else {
    // Programming or unknown errors
    res.status(500).json({
      status: 'error',
      message: 'Something went wrong!',
    });
  }
};

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  logger.error('UNHANDLED REJECTION! 💥 Shutting down...');
  logger.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  logger.error(err.name, err.message);
  process.exit(1);
});

app.use(errorHandler);
```

---

## Complete Improved File Structure

