### 1. **Missing Server Error Handling**
Your current code doesn't handle server startup errors:

```javascript
// CURRENT (No error handling)
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// IMPROVED
const port = process.env.PORT || 3000;
const server = app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

// Handle port conflicts
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${port} is already in use.`);
  } else {
    console.error('Server error:', error.message);
  }
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});

process.on('SIGINT', () => {
  server.close(() => process.exit(0));
});
```

### 2. **Missing Input Validation for Route Parameters**
GET requests don't validate input, which could lead to injection attacks:

```javascript
// CURRENT (No validation)
app.get('/users/:id', (req, res) => {
  res.json(users);
});

// IMPROVED
const { param, validationResult } = require('express-validator');

app.get('/users/:id', [
  param('id')
    .isLength({ min: 1, max: 100 })
    .matches(/^[a-fA-F0-9]+$/)
    .withMessage('Invalid user ID format'),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: errors.array(),
    });
  }
  // Safe to use req.params.id
  res.json(users);
});
```

