#!/usr/bin/env node

/**
 * Credential Validation Script
 * Checks connectivity and validity of credentials in .env.test
 */

const { URL } = require('url');
const https = require('https');
const http = require('http');
const fs = require('fs');
const path = require('path');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
};

// ============================================
// UTILITY FUNCTIONS
// ============================================

function log(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

function logSection(title) {
  console.log('\n' + '═'.repeat(70));
  log(`  ${title}`, colors.cyan);
  console.log('═'.repeat(70));
}

function logResult(testName, passed, details = '') {
  const icon = passed ? '✅' : '❌';
  const color = passed ? colors.green : colors.red;
  const prefix = `${icon} ${testName}`;
  log(prefix, color);
  if (details) {
    console.log(`   ${details}`);
  }
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Basic URL validation
function isValidUrl(string) {
  try {
    const url = new URL(string);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch (_) {
    return false;
  }
}

// HTTP GET request with timeout
function getUrl(urlString, options = {}) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const client = url.protocol === 'https:' ? https : http;

    const requestOptions = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname + url.search,
      method: 'GET',
      timeout: options.timeout || 10000, // 10 second timeout
      headers: {
        'User-Agent': 'CredentialValidator/1.0',
        ...options.headers,
      },
    };

    const req = client.request(requestOptions, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: data,
          responseTime: res.elapsedTime || req.elapsedTime,
        });
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Request failed: ${error.message}`));
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timed out'));
    });

    req.on('socket', (socket) => {
      socket.connecting = true;
      socket.on('connect', () => {
        socket.connecting = false;
        const connectStartTime = socket._connectStartTime || Date.now();
        req.elapsedTime = Date.now() - connectStartTime;

        // Set up timer for overall timeout
        const timeoutTimer = setTimeout(() => {
          req.destroy();
          reject(new Error('Connection timed out'));
        }, requestOptions.timeout);

        if (!socket._connectStartTime) {
          socket._connectStartTime = connectStartTime;
          socket.once('close', () => clearTimeout(timeoutTimer));
        }
      });
    });

    req.write('');
    req.end();
  });
}

// ============================================
// CREDENTIAL VALIDATION FUNCTIONS
// ============================================

/**
 * Test PostgreSQL Database Connection
 */
async function testDatabaseConnection(dbUrl, testQuery = 'SELECT 1') {
  logSection('Testing Database Connection');

  // Parse and validate URL
  try {
    const parsedUrl = new URL(dbUrl);

    if (!parsedUrl.hostname.match(/^[\w.-]+(\.[\w.-]+)+$/)) {
      return { passed: false, error: 'Invalid database hostname' };
    }

    if (parsedUrl.protocol !== 'postgresql:' && parsedUrl.protocol !== 'postgres:') {
      return { passed: false, error: 'Invalid database protocol (must be postgresql://)' };
    }

    log(`Database URL: ${parsedUrl.hostname}`, colors.yellow);
    log(`Port: ${parsedUrl.port || 5432}`, colors.yellow);

    // PostgreSQL requires TCP connection, not HTTP
    // We'll test connectivity with a basic TCP check

    const net = await import('net');
    const { default: client } = await import('socks-proxy-agent');

    // Set up connection timeout
    return new Promise((resolve) => {
      const socket = new net.Socket();
      const startTime = Date.now();
      let timedOut = false;

      socket.setTimeout(8000); // 8 second timeout

      // Try to connect
      socket.connect(parseInt(parsedUrl.port) || 5432, parsedUrl.hostname, () => {
        const responseTime = Date.now() - startTime;

        if (socket.destroyed) {
          resolve({
            passed: true,
            message: 'Connection established',
            details: `Connection time: ${responseTime}ms`,
            timing: responseTime,
          });
        } else {
          socket.destroy();
        }
      });

      socket.on('error', (err) => {
        if (timedOut) return;

        const isTimeout = err.code === 'ETIMEDOUT' || err.code === 'ESOCKETTIMEDOUT';
        const isRefused = err.code === 'ECONNREFUSED';
        const isNetwork = err.code === 'ENETUNREACH' || err.code === 'EHOSTUNREACH';

        if (isTimeout) {
          resolve({
            passed: false,
            error: 'Connection timed out (database may be down or unreachable)',
            details: `Host: ${parsedUrl.hostname}:${parsedUrl.port || 5432}`,
          });
        } else if (isRefused) {
          resolve({
            passed: false,
            error: 'Connection refused (database server may not be running)',
            details: `Host: ${parsedUrl.hostname}:${parsedUrl.port || 5432}`,
          });
        } else if (isNetwork) {
          resolve({
            passed: false,
            error: 'Network unreachable (check your firewall or network settings)',
          });
        } else {
          resolve({
            passed: false,
            error: 'Connection error',
            details: err.message,
          });
        }
        timedOut = true;
        if (!socket.destroyed) socket.destroy();
      });

      socket.on('timeout', () => {
        if (timedOut) return;

        timedOut = true;
        log('Connection timed out', colors.yellow);
        socket.destroy();
        resolve({
          passed: false,
          error: 'Connection timed out after 8000ms',
        });
      });

      // Close after 1 second
      setTimeout(() => {
        if (timedOut) return;
        timedOut = true;
        socket.destroy();
        resolve({
          passed: false,
          error: 'Connection closed by validator (timed out during startup)',
        });
      }, 1000);

      // Send initial handshake
      socket.write('G\x00\x00\x02\tJ\x00\x00\xa8\x00\x00\x00\x00\x00\x00\x00\x00 \x04 fils\naccount\n');
    });

  } catch (error) {
    return {
      passed: false,
      error: `Invalid database URL format: ${error.message}`,
    };
  }
}

/**
 * Test AWS API Key validity
 */
async function testAWSCredentials(accessKeyId, secretAccessKey) {
  logSection('Testing AWS Credentials');

  // Basic format validation
  const isValidAks = /^[A-Za-z0-9]{20}$/.test(accessKeyId);
  const isValidSec = /^[A-Za-z0-9\/+]+=*$/.test(secretAccessKey);

  log(`Access Key ID length: ${accessKeyId.length} chars`, colors.blue);
  log(`Secret Access Key length: ${secretAccessKey.length} chars`, colors.blue);

  if (!isValidAks) {
    logResult('AWS Access Key Format', false, 'Invalid length or format');
    return { passed: false, reason: 'Invalid format' };
  }

  if (!isValidSec) {
    logResult('AWS Secret Key Format', false, 'Invalid length or format');
    return { passed: false, reason: 'Invalid format' };
  }

  // Attempt to make a call to AWS STS
  try {
    // STS DescribeUser endpoint
    const data = JSON.stringify({
      Action: 'DescribeUser',
      Version: '2010-05-08',
    });

    const url = new URL('https://sts.amazonaws.com');
    const hostname = 'sts.amazonaws.com';

    return new Promise((resolve) => {
      const options = {
        hostname,
        port: 443,
        path: '/',
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Content-Length': Buffer.byteLength(data),
          'User-Agent': 'CredentialValidator/1.0',
        },
      };

      const client = https;

      const req = client.request(options, (res) => {
        let body = '';
        res.on('data', (chunk) => body += chunk);
        res.on('end', () => {
          const statusCode = res.statusCode;

          // Check for valid responses
          if (statusCode === 400) {
            // This might be validation - check body
            resolve({
              passed: checkAWSResponse(body, '.invalid_access_key_id'),
              statusCode: 400,
              response: body,
            });
          } else if (statusCode === 200) {
            resolve({
              passed: checkAWSResponse(body, 'error'),
              statusCode: 200,
              response: body,
            });
          } else {
            resolve({
              passed: false,
              error: `Unexpected status code: ${statusCode}`,
              response: body,
            });
          }
        });
      });

      req.on('error', (error) => {
        resolve({
          passed: false,
          error: `Connection failed: ${error.message}`,
        });
      });

      req.write(data);
      req.end();
    });
  } catch (error) {
    return {
      passed: false,
      error: `AWS test failed: ${error.message}`,
    };
  }
}

// Check AWS response for specific error patterns
function checkAWSResponse(body, searchTerm) {
  const lowerBody = body.toLowerCase();
  return lowerBody.includes(searchTerm) || lowerBody.includes('error') || lowerBody.includes('invalid');
}

/**
 * Test Anthropic API Key validity
 */
