          const statusCode = res.statusCode;

          if (statusCode === 200 || statusCode === 400) {
            // Either valid key (works) or validation error
            const valid = body.toLowerCase().includes('error') ? false : true;
            resolve({
              passed: valid,
              statusCode: res.statusCode,
              response: body.substring(0, 200), // First 200 chars
              isTest: true, // We're just validating format, not actually using the key
            });
          } else if (statusCode === 401 || statusCode === 403) {
            resolve({
              passed: false,
              error: 'Unauthorized or forbidden - invalid API key',
              statusCode: statusCode,
            });
          } else {
            resolve({
              passed: false,
              error: `Unexpected status code: ${statusCode}`,
              response: body.substring(0, 200),
            });
          }
        });
      });

      req.on('error', (error) => {
        resolve({
          passed: false,
          error: `Connection failed: ${error.message}`,
        });
      });

      req.setTimeout(8000, () => {
        req.destroy();
        resolve({ passed: false, error: 'Request timed out' });
      });

      req.write(data);
      req.end();
    });
  } catch (error) {
    return {
      passed: false,
      error: `Anthropic test failed: ${error.message}`,
    };
  }
}

/**
 * Test Stripe API Key validity
 */
async function testStripeSecretKey(secretKey) {
  logSection('Testing Stripe Secret Key');

  // Basic format validation
  const skLiveRegex = /^sk_live_[a-zA-Z0-9]{24,}$/;
  const skTestRegex = /^sk_test_[a-zA-Z0-9]{24,}$/;
  const isValidTest = skLiveRegex.test(secretKey) || skTestRegex.test(secretKey);

  log(`Key contains "CANARY": ${secretKey.includes('CANARY')}`, colors.yellow);
  log(`Key length: ${secretKey.length} chars`, colors.blue);
  log(`Key format: ${isValidTest ? 'Valid' : 'Invalid'}`, colors.blue);

  if (!isValidTest) {
    logResult('Stripe Secret Key Format', false, 'Must be sk_live or sk_test prefixed with 24+ hex chars');
    return { passed: false, reason: 'Invalid format' };
  }

  if (secretKey.includes('CANARY')) {
    logResult('Stripe Secret Key', false, 'WARNING: This appears to be a test/canary value');
    return { passed: false, reason: 'CANARY prefix detected - not a valid key' };
  }

  // Attempt to validate with Stripe API
  try {
    // Check if it's a live key for security (we don't actually call Stripe, just validate format)
    const isLive = secretKey.startsWith('sk_live_');
    log(`This appears to be ${isLive ? 'a LIVE' : 'a TEST'} key`, isLive ? colors.yellow : colors.green);
    log('Note: Attempting to validate without making actual charges', colors.cyan);

    return new Promise((resolve) => {
      // Just validate the format for now to avoid potential live charges
      // Real validation would be to call Stripe API, but we don't want to make actual charges

      const valid = secretKey.length >= 48;
      resolve({
        passed: valid,
        message: 'Format valid (no actual charge will be made for security)',
        formatValid: isValidTest,
        length: secretKey.length,
      });
    });
  } catch (error) {
    return {
      passed: false,
      error: `Stripe test failed: ${error.message}`,
    };
  }
}

/**
 * Test Logfire API Key validity
 */
async function testLogfireToken(token) {
  logSection('Testing Logfire Token');

  // Basic format validation
  const isValid = token.startsWith('CANARY-');
  log(`Token format: ${isValid ? 'Valid CANARY token' : 'Likely custom format'}`, isValid ? colors.yellow : colors.blue);
  log(`Token length: ${token.length} chars`, colors.blue);

  if (token.startsWith('CANARY-')) {
    logResult('Logfire Token', false, 'WARNING: This is a test/canary token');
    return { passed: false, reason: 'Empty token or invalid format' };
  }

  return {
    passed: true,
    message: 'Format appears valid (note: this is a test validation)',
    formatValid: token.length > 10,
  };
}

