// MAIN EXECUTION
// ============================================

async function main() {
  log('\n🧪 CREDENTIAL VALIDATION TEST SUITE', colors.cyan);
  log('Validating credentials from .env.test\n', colors.blue);

  try {
    // Load environment variables
    const envPath = path.join(process.cwd(), '.env.test');
    let envPathResolved = envPath;

    if (!fs.existsSync(envPath)) {
      // Try parent directory
      const parentDir = path.join(process.cwd(), '..');
      const altPath = path.join(parentDir, '.env.test');
      if (fs.existsSync(altPath)) {
        envPathResolved = altPath;
      } else {
        log('❌ .env.test file not found in current directory or parent', colors.red);
        process.exit(1);
      }
    }

    log(`Reading environment from: ${envPathResolved}`, colors.green);

    const envContent = fs.readFileSync(envPathResolved, 'utf8');
    const envVars = {};

    // Parse .env file
    envContent.split('\n').forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;

      const match = trimmed.match(/^([^=]+)=(.*)$/);
      if (match) {
        let value = match[2];
        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[match[1].trim()] = value;
      }
    });

    log(`Loaded ${Object.keys(envVars).length} environment variables`, colors.green);

    // Run all tests with delay between them
    let results = [];

    // 1. Database Connection Test
    if (envVars.DATABASE_URL && envVars.DATABASE_URL !== '') {
      log('\n---', colors.yellow);
      const dbResult = await testDatabaseConnection(envVars.DATABASE_URL);
      results.push({ test: 'Database Connection', ...dbResult });
      await sleep(2000); // Wait 2 seconds between tests
    } else {
      log('\n---', colors.yellow);
      logResult('Database Connection', true, 'Skipped (no DATABASE_URL configured)');
      results.push({ test: 'Database Connection', passed: true, message: 'Skipped - no DATABASE_URL' });
    }

    // 2. AWS Credentials Test
    if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
      log('\n---', colors.yellow);
      const awsResult = await testAWSCredentials(envVars.AWS_ACCESS_KEY_ID, envVars.AWS_SECRET_ACCESS_KEY);
      results.push({ test: 'AWS Credentials', ...awsResult });
      await sleep(2000);
    } else {
      log('\n---', colors.yellow);
      logResult('AWS Credentials', true, 'Skipped (no credentials configured)');
      results.push({ test: 'AWS Credentials', passed: true, message: 'Skipped - no AWS credentials' });
    }

    // 3. Anthropic API Key Test
    if (envVars.ANTHROPIC_API_KEY) {
      log('\n---', colors.yellow);
      const result = await testAnthropicAPIKey(envVars.ANTHROPIC_API_KEY);
      results.push({ test: 'Anthropic API Key', ...result });
      await sleep(2000);
    } else {
      log('\n---', colors.yellow);
      logResult('Anthropic API Key', true, 'Skipped (no key configured)');
      results.push({ test: 'Anthropic API Key', passed: true, message: 'Skipped - no API key' });
    }

    // 4. Stripe Secret Key Test
    if (envVars.STRIPE_SECRET_KEY) {
      log('\n---', colors.yellow);
      const result = await testStripeSecretKey(envVars.STRIPE_SECRET_KEY);
      results.push({ test: 'Stripe Secret Key', ...result });
      await sleep(2000);
    } else {
      log('\n---', colors.yellow);
      logResult('Stripe Secret Key', true, 'Skipped (no key configured)');
      results.push({ test: 'Stripe Secret Key', passed: true, message: 'Skipped - no key' });
    }

    // 5. Logfire Token Test
    if (envVars.LOGFIRE_TOKEN) {
      log('\n---', colors.yellow);
      const result = await testLogfireToken(envVars.LOGFIRE_TOKEN);
      results.push({ test: 'Logfire Token', ...result });
      await sleep(2000);
    } else {
      log('\n---', colors.yellow);
      logResult('Logfire Token', true, 'Skipped (no token configured)');
      results.push({ test: 'Logfire Token', passed: true, message: 'Skipped - no token' });
    }

    // Summary
    logSection('TEST SUMMARY');
    const passedCount = results.filter(r => r.passed).length;
    const failedCount = results.filter(r => !r.passed).length;

    results.forEach(result => {
      const icon = result.passed ? '✅ PASS' : '❌ FAIL';
      const color = result.passed ? colors.green : colors.red;
      const detail = result.message || result.error || '';

      if (detail) {
        log(`${icon} ${result.test}`, color);
        log(`   ${detail}`, colors.yellow);
      } else {
        log(`${icon} ${result.test}`, color);
      }
    });

    log('\n' + '─'.repeat(70));
    log(`  Total: ${results.length} tests run`, colors.blue);
    log(`  Passed: ${passedCount}`, colors.green);
    log(`  Failed: ${failedCount}`, colors.red);

    if (failedCount === 0) {
      log('\n✅ All tests passed!', colors.green);
      process.exit(0);
    } else {
      log('\n⚠️  Some tests failed', colors.red);
      process.exit(1);
    }

  } catch (error) {
    log('Error running validation tests:', colors.red);
    log(error.message, colors.red);
    process.exit(1);
  }
}

// Run the script
main().catch(console.error);

#!/usr/bin/env node

/**
 * Simple Credential Validation Script
 * Validates credential formats without network calls
 * Detects stale/canary values
 */

const { URL } = require('url');
const fs = require('fs');
const path = require('path');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  magenta: '\x1b[35m',
};

function log(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

function logSection(title) {
  console.log('\n' + '═'.repeat(70));
  log(`  ${title}`, colors.cyan);
  console.log('═'.repeat(70));
}

function logResult(testName, passed, details = '') {
  const icon = passed ? '✅' : '❌';
  const color = passed ? colors.green : colors.red;
  const symbol = passed ? 'PASS' : 'FAIL';
  log(`${icon} ${testName} ${symbol}`, color);
  if (details) {
    console.log(`   📝 ${details}`);
  }
}

// ============================================
// VALIDATION FUNCTIONS
// ============================================

/**
 * Validates PostgreSQL database URL
 */
function validateDatabaseUrl(dbUrl) {
  try {
    const parsed = new URL(dbUrl);

    // Basic validation
    if (!parsed.hostname.match(/^[\w.-]+(\.[\w.-]+)*$/)) {
      return { valid: false, reason: 'Invalid hostname format' };
    }

    if (parsed.protocol !== 'postgresql:' && parsed.protocol !== 'postgres:') {
      return { valid: false, reason: 'Invalid protocol (must be postgresql://)' };
    }

    const port = parseInt(parsed.port || '5432');
    if (port < 1 || port > 65535) {
      return { valid: false, reason: 'Invalid port number' };
    }

    // Check if credential is CANARY/stale
    if (dbUrl.includes('CANARY')) {
      return {
        valid: false,
        reason: 'CANARY severity: This appears to be a test/simulated credential',
        is_canary: true
      };
    }

    // Check for suspicious patterns
    if (dbUrl.includes('admin:password') || dbUrl.includes(':THIS_IS_A_BAD_PASSWORD')) {
      return {
        valid: false,
        reason: 'Security Risk: Default or placeholder password detected',
        is_weak: true
      };
    }

    // Check for external/internal references
    if (parsed.hostname.includes('.internal') || parsed.hostname.includes('.local') ||
        parsed.hostname.includes('db.') || parsed.hostname.includes('db.localhost')) {
      return {
        valid: false,
        reason: 'Likely Stale: References internal/legacy service',
        is_legacy: true,
        hostname: parsed.hostname
      };
    }

    return { valid: true, hostname: parsed.hostname, port };
  } catch (error) {
    return { valid: false, reason: `Invalid URL format: ${error.message}` };
  }
}

/**
 * Validates AWS Access Key ID
 */
function validateAWSAccessKey(accessKeyId) {
  // AWS Access Key format: starts with AKIAI, AKIAC, or AKIAD (AWS prefixes)
  const isCanonical = /^[A-Z]{4}[0-9A-Z]{16}$/.test(accessKeyId);
  const isCanary = accessKeyId.includes('CANARY');

  if (!isCanonical && !isCanary) {
    const reason = isCanonical
      ? 'Invalid format (AWS keys must be 20 chars, alphanumeric, start with AKIA prefix)'
      : 'Missing AWS Access Key format';
    return { valid: false, reason };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/simulated AWS key (declared in .env.test)',
      is_canary: true
    };
  }

  // Valid format but could be expired
  if (!isCanonical) {
    return {
      valid: false,
      reason: 'Invalid AWS key format - should be 20 alphanumeric characters',
    };
  }

  return { valid: true, formatValid: true };
}

/**
 * Validates AWS Secret Access Key
 */
function validateAWSSecretKey(secretAccessKey) {
  // AWS Secret Key format: base64 encoded, 40 chars
  const isCanonical = /^[A-Za-z0-9\/+]+=*$/.test(secretAccessKey) && secretAccessKey.length >= 40;
  const isCanary = secretAccessKey.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: isCanonical
        ? 'Invalid format (AWS secret key must be base64, 40+ chars)'
        : 'Invalid AWS secret key format'
    };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/simulated AWS secret key',
      is_canary: true
    };
  }

  if (!isCanonical) {
    return {
      valid: false,
      reason: 'AWS secret key must be base64 encoded with 40+ characters',
    };
  }

  return { valid: true, formatValid: true };
}

/**
 * Validates Anthropic API Key
 */
function validateAnthropicAPIKey(apiKey) {
  // Anthropic API key format: sk-ant-<key>, min length 32, alphanumeric + hyphens
  const isCanonical = /^sk-ant-[a-zA-Z0-9-]+$/.test(apiKey) && apiKey.length >= 32;
  const isCanary = apiKey.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: 'Invalid format (must start with sk-ant- and be at least 32 characters)',
    };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/simulated Anthropic API key',
      is_canary: true
    };
  }

  if (!isCanonical) {
    return {
      valid: false,
      reason: 'Anthropic API key must be at least 32 characters, start with sk-ant-',
    };
  }

  return { valid: true, formatValid: true };
}

/**
 * Validates Stripe Secret Key
 */
function validateStripeSecretKey(secretKey) {
  // Stripe secret keys: sk_live_<24 chars> or sk_test_<24 chars>
  const isCanonical = /^sk_(live|test)_[a-zA-Z0-9]{24,}$/.test(secretKey);
  const isCanary = secretKey.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: 'Invalid format (must be sk_live_ or sk_test_ prefixed with 24+ characters)',
    };
  }

  if (isCanonical) {
    // Check if it's actually a live key (for security awareness)
    const isLive = secretKey.startsWith('sk_live_');
    const prefixWarning = isLive ? '' : ' (This is a TEST key - safe for development)';

    return {
      valid: true,
      formatValid: true,
      isLive,
      message: `Valid Stripe key format${prefixWarning}`
    };
  }

  if (isCanary && secretKey.includes('CANARY')) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/canary Stripe key exposed in .env.test',
      is_canary: true,
      suggests: 'Replace with real sk_live_ or sk_test_ key for production',
    };
  }

  return { valid: false, reason: 'Invalid Stripe key format' };
}

/**
 * Validates Logfire Token
 * Logfire is FireEagle, but the token format can vary - we check for red flags
 */
function validateLogfireToken(token) {
  // Validate basic format
  const isValidLength = token.length > 20;
  const isFormatAgreed = /^[a-zA-Z0-9-_.]+$/.test(token);
  const isCanary = token.includes('CANARY');

  if (!isValidLength || !isFormatAgreed) {
    return {
      valid: false,
      reason: 'Invalid token format (must be 20+ alphanumeric characters)',
    };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/canary token detected',
      is_canary: true,
      suggests: 'This appears to be a synthetic token, not a real logfire token',
    };
  }

  return { valid: true, formatValid: true };
}

// ============================================
// EXPIRATION CHECK FUNCTIONS
// ============================================

/**
 * Check if AWS key is likely expired (based on naming convention)
 */
function checkAWSExpirancy(accessKeyId) {
  // Some AWS keys have patterns that indicate age
  // We can't definitively know without service API

  if (accessKeyId.includes('EXPIRED') || accessKeyId.includes('OLD') || accessKeyId.includes('DEPRECATED')) {
    return { expired: true, reason: 'Key name includes explicit expiration marker' };
  }

  // Check common patterns that might indicate old keys
  if (/^[A-Z]{4}2[0-9]{12}$/.test(accessKeyId)) {
    return { expired: true, reason: 'Key follows AWS v2 naming pattern (likely very old)' };
  }

  return { expired: false };
}

/**
 * Check if Anthropic key appears to be a template (not a real key)
 */
function checkAnthropicFormat(apiKey) {
  if (apiKey.includes('placeholder') || apiKey.includes('template') || apiKey.includes('example')) {
    return { seemsStatic: true, reason: 'Key name indicates it\'s a static/placeholder value' };
  }
  return { seemsStatic: false };
}

/**
 * Check if Stripe key has suspicious length
 */
function checkStripeLength(secretKey) {
  const length = secretKey.length;
  if (length < 48 || length > 100) {
    return { invalidLength: true, reason: `Key length ${length} is unusually short or long for Stripe` };
  }
  return { invalidLength: false };
}

