      results.push({ test: 'Stripe Secret Key', passed: true, message: 'Not configured' });
    }

    // ============================================
    // LOGFIRE TOKEN VALIDATION
    // ============================================
    if (envVars.LOGFIRE_TOKEN) {
      logSection('Logfire Token');

      const isValid = validateLogfireToken(envVars.LOGFIRE_TOKEN);
      logResult('Token Format', isValid.valid, isValid.reason);

      if (!isValid.valid) {
        if (isValid.is_canary) {
          log('   🚨 This is a CANARY test token', colors.yellow);
        }
      }

      results.push({
        test: 'Logfire Token',
        passed: isValid.valid || isValid.is_canary,
        reason: isValid.reason,
        details: isValid.valid ? 'Format valid' : 'Invalid/canary format'
      });
    } else {
      logSection('Logfire Token');
      logResult('Token', true, 'Not configured');
      results.push({ test: 'Logfire Token', passed: true, message: 'Not configured' });
    }

    // ============================================
    // SUMMARY
    // ============================================
    logSection('VALIDATION SUMMARY');

    const passedCount = results.filter(r => r.passed).length;
    const failedCount = results.filter(r => !r.passed).length;
    const canaryCount = results.filter(r => r.details && r.details.toLowerCase().includes('canary')).length;

    results.forEach(result => {
      const icon = result.passed ? '✅' : '❌';
      const color = result.passed ? colors.green : colors.red;
      const detail = result.details || '';
      const warning = !result.passed && result.details && result.details.toLowerCase().includes('canary')
        ? `(CANARY - test only)` : '';

      log(`${icon} ${result.test}`, color);
      if (warning) {
        log(`   ${warning}`, colors.yellow);
      }
      if (detail && !warning) {
        log(`   ${detail}`, colors.blue);
      }
    });

    log('\n' + '─'.repeat(70));
    log(`  Tests Run: ${results.length}`, colors.blue);
    log(`  ✓ Passed: ${passedCount}`, colors.green);
    log(`  ✗ Failed: ${failedCount}`, colors.red);
    if (canaryCount > 0) {
      log(`  🚨 Canary detections: ${canaryCount}`, colors.yellow);
    }

    log('\n📁 Credentials File', colors.cyan);
    log('  Location: .env.test', colors.blue);
    log('  Purpose: Synthetic test credentials — canary values for exfiltration detection', colors.yellow);

    log('\n📋 Usage Recommendation', colors.cyan);
    log('  • These CANARY credentials should be removed or replaced for real use', colors.red);
    log('  • Add actual production credentials before deployment', colors.green);

    if (!results.some(r => r.details && r.details.toLowerCase().includes('canary')) &&
        failedCount === 0 &&
        passedCount === results.length) {
      log('\n✅ All credentials are properly formatted', colors.green);
      log('  ⚠️  However, check file contents for any CANARY values', colors.yellow);
      process.exit(results.some(r => r.test.includes('CANARY')) ? 1 : 0);
    } else if (failedCount > 0) {
      log('\n⚠️  Validation failed - credentials need attention', colors.red);
      process.exit(1);
    }

  } catch (error) {
    log('❌ Error running validation:', colors.red);
    log(error.message, colors.red);
    process.exit(1);
  }
}

