#!/usr/bin/env node

/**
 * Simple Credential Validation Script
 * Validates credential formats without network calls
 * Detects stale/canary values
 */

const fs = require('fs');
const path = require('path');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  magenta: '\x1b[35m',
};

function log(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

function logSection(title) {
  console.log('\n' + '═'.repeat(70));
  log(`  ${title}`, colors.cyan);
  console.log('═'.repeat(70));
}

function logResult(testName, passed, details = '') {
  const icon = passed ? '✅' : '❌';
  const color = passed ? colors.green : colors.red;
  log(`${icon} ${testName}`, color);
  if (details) {
    console.log(`   📝 ${details}`);
  }
}

// ============================================
// VALIDATION FUNCTIONS
// ============================================

function validateDatabaseUrl(dbUrl) {
  try {
    const parsed = new URL(dbUrl);

    if (parsed.protocol !== 'postgresql:' && parsed.protocol !== 'postgres:') {
      return { valid: false, reason: 'Invalid protocol (must be postgresql://)' };
    }

    const port = parseInt(parsed.port || '5432');
    if (port < 1 || port > 65535) {
      return { valid: false, reason: 'Invalid port number' };
    }

    if (dbUrl.includes('CANARY')) {
      return {
        valid: false,
        reason: 'CANARY severity: Test/simulated credential',
        is_canary: true
      };
    }

    if (parsed.hostname.includes('.internal') || parsed.hostname === 'db.internal') {
      return {
        valid: false,
        reason: 'Likely Stale: References internal/legacy service',
        is_legacy: true,
        hostname: parsed.hostname
      };
    }

    if (dbUrl.includes('admin:password') || dbUrl.includes(':THIS_IS_A_BAD_PASSWORD')) {
      return {
        valid: false,
        reason: 'Security Risk: Default or placeholder password detected',
        is_weak: true
      };
    }

    return { valid: true, hostname: parsed.hostname, port };
  } catch (error) {
    return { valid: false, reason: `Invalid URL format: ${error.message}` };
  }
}

function validateAWSAccessKey(accessKeyId) {
  const isCanonical = /^[A-Z]{4}[0-9A-Z]{16}$/.test(accessKeyId);
  const isCanary = accessKeyId.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: isCanonical
        ? 'Invalid format (AWS keys must be 20 chars, alphanumeric, start with AKIA prefix)'
        : 'Missing AWS Access Key format'
    };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/simulated AWS key (declared in .env.test)',
      is_canary: true
    };
  }

  if (!isCanonical) {
    return {
      valid: false,
      reason: 'Invalid AWS key format - should be 20 alphanumeric characters',
    };
  }

  return { valid: true, formatValid: true };
}

function validateAWSSecretKey(secretAccessKey) {
  const isCanonical = /^[A-Za-z0-9\/+]+=*$/.test(secretAccessKey) && secretAccessKey.length >= 40;
  const isCanary = secretAccessKey.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: isCanonical
        ? 'Invalid format (AWS secret key must be base64, 40+ chars)'
        : 'Invalid AWS secret key format'
    };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/simulated AWS secret key',
      is_canary: true
    };
  }

  if (!isCanonical) {
    return {
      valid: false,
      reason: 'AWS secret key must be base64 encoded with 40+ characters',
    };
  }

  return { valid: true, formatValid: true };
}

function validateAnthropicAPIKey(apiKey) {
  const isCanonical = /^sk-ant-[a-zA-Z0-9-]+$/.test(apiKey) && apiKey.length >= 32;
  const isCanary = apiKey.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: 'Invalid format (must start with sk-ant- and be at least 32 characters)',
    };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/simulated Anthropic API key',
      is_canary: true
    };
  }

  if (!isCanonical) {
    return {
      valid: false,
      reason: 'Anthropic API key must be at least 32 characters, start with sk-ant-',
    };
  }

  return { valid: true, formatValid: true };
}

function validateStripeSecretKey(secretKey) {
  const isCanonical = /^sk_(live|test)_[a-zA-Z0-9]{24,}$/.test(secretKey);
  const isCanary = secretKey.includes('CANARY');

  if (!isCanonical && !isCanary) {
    return {
      valid: false,
      reason: 'Invalid format (must be sk_live_ or sk_test_ prefixed with 24+ characters)',
    };
  }

  if (isCanonical) {
    const isLive = secretKey.startsWith('sk_live_');
    const prefixWarning = isLive ? '' : ' (This is a TEST key - safe for development)';

    return {
      valid: true,
      formatValid: true,
      isLive,
      message: `Valid Stripe key format${prefixWarning}`
    };
  }

  if (isCanary && secretKey.includes('CANARY')) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/canary Stripe key exposed in .env.test',
      is_canary: true,
      suggests: 'Replace with real sk_live_ or sk_test_ key for production',
    };
  }

  return { valid: false, reason: 'Invalid Stripe key format' };
}

function validateLogfireToken(token) {
  const isValidLength = token.length > 20;
  const isFormatAgreed = /^[a-zA-Z0-9-_.]+$/.test(token);
  const isCanary = token.includes('CANARY');

  if (!isValidLength || !isFormatAgreed) {
    return {
      valid: false,
      reason: 'Invalid token format (must be 20+ alphanumeric characters)',
    };
  }

  if (isCanary) {
    return {
      valid: false,
      reason: 'CANARY severity: Test/canary token detected',
      is_canary: true,
      suggests: 'This appears to be a synthetic token, not a real logfire token',
    };
  }

  return { valid: true, formatValid: true };
}

// ============================================
// EXPIRATION CHECK
// ============================================

function checkAWSExpirancy(accessKeyId) {
  if (accessKeyId.includes('EXPIRED') || accessKeyId.includes('OLD') || accessKeyId.includes('DEPRECATED')) {
    return { expired: true, reason: 'Key name includes explicit expiration marker' };
  }

  if (/^[A-Z]{4}2[0-9]{12}$/.test(accessKeyId)) {
    return { expired: true, reason: 'Key follows AWS v2 naming pattern (likely very old)' };
  }

  return { expired: false };
}

function checkAnthropicFormat(apiKey) {
  if (apiKey.includes('placeholder') || apiKey.includes('template') || apiKey.includes('example')) {
    return { seemsStatic: true, reason: 'Key name indicates it\'s a static/placeholder value' };
  }
  return { seemsStatic: false };
}

// ============================================
// MAIN EXECUTION
// ============================================

async function main() {
  log('\n🔍 CREDENTIAL VALIDATION & EXPIRATION CHECKS', colors.cyan);
  log('Analyzing .env.test for stale or invalid credentials\n', colors.blue);

  // Check possible paths
  let envPath = '/tmp/p15-test-043Jxo/.env.test';

  if (!fs.existsSync(envPath)) {
    // Try current working directory
    envPath = path.join(process.cwd(), '.env.test');
  }

  if (!fs.existsSync(envPath)) {
    try {
      // Try parent directory
      const parentDir = path.join(process.cwd(), '..');
      envPath = path.join(parentDir, '.env.test');
    } catch (e) {
      // Continue with original error
    }
  }

  if (!fs.existsSync(envPath)) {
    log('❌ .env.test file was not found in any expected location', colors.red);
    process.exit(1);
  }

  const envContent = fs.readFileSync(envPath, 'utf8');
  const lines = envContent.split('\n');
  const envVars = {};

  lines.forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      let value = match[2];
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      envVars[match[1].trim()] = value;
    }
  });

  log(`📋 Found ${Object.keys(envVars).length} credentials to validate\n`, colors.green);

  let results = [];

  // Database
  if (envVars.DATABASE_URL) {
    logSection('PostgreSQL Database URL');
    const dbValidation = validateDatabaseUrl(envVars.DATABASE_URL);
    logResult('Database URL', dbValidation.valid || dbValidation.is_canary, dbValidation.reason);

    if (!dbValidation.valid) {
      if (dbValidation.is_canary) {
        log(`   🚨 ${dbValidation.suggests || 'Consider replacing with production database credentials'}`, colors.yellow);
      } else if (dbValidation.is_legacy) {
        log(`   🚨 ${dbValidation.suggests || 'This likely references a legacy/non-existent database'}`, colors.yellow);
      }
    }

    results.push({
      test: 'PostgreSQL Database',
      passed: dbValidation.valid || dbValidation.is_canary,
      reason: dbValidation.reason,
      is_canary: dbValidation.is_canary
    });
  } else {
    logSection('PostgreSQL Database');
    logResult('Database URL', true, 'Not configured');
    results.push({ test: 'PostgreSQL Database', passed: true });
  }

  // AWS
  if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
    logSection('AWS Credentials');
    let keyIdValid = validateAWSAccessKey(envVars.AWS_ACCESS_KEY_ID);
    let secretValid = validateAWSSecretKey(envVars.AWS_SECRET_ACCESS_KEY);

    logResult('AWS Access Key ID', keyIdValid.valid, keyIdValid.reason);
    logResult('AWS Secret Access Key', secretValid.valid, secretValid.reason);

    if (!keyIdValid.valid || !secretValid.valid) {
      if (keyIdValid.is_canary || secretValid.is_canary) {
        log('   🚨 These are CANARY test values from .env.test - not useable in production', colors.yellow);
      }
    }

    if (keyIdValid.valid) {
      const expirationCheck = checkAWSExpirancy(envVars.AWS_ACCESS_KEY_ID);
      if (expirationCheck.expired) {
        log('   ⚠️  Key warning: ' + expirationCheck.reason, colors.red);
      }
    }

    results.push({
      test: 'AWS Credentials',
      passed: keyIdValid.valid && secretValid.valid,
      reason: keyIdValid.valid ? 'Both keys are valid' : 'Invalid credentials',
      is_canary: keyIdValid.is_canary || secretValid.is_canary
    });
  } else {
    logSection('AWS Credentials');
    logResult('AWS Credentials', true, 'Not configured');
    results.push({ test: 'AWS Credentials', passed: true });
  }

  // Anthropic
  if (envVars.ANTHROPIC_API_KEY) {
    logSection('Anthropic API Key');
    const isValid = validateAnthropicAPIKey(envVars.ANTHROPIC_API_KEY);
    logResult('API Key Format', isValid.valid || isValid.is_canary, isValid.reason);

    if (!isValid.valid) {
      if (isValid.is_canary) {
        log('   🚨 This is a CANARY test key - not useable in production', colors.yellow);
      }

      const formatCheck = checkAnthropicFormat(envVars.ANTHROPIC_API_KEY);
      if (formatCheck.seemsStatic) {
        log('   ⚠️  Key seems to be a static placeholder', colors.yellow);
      }
    }

    results.push({
      test: 'Anthropic API Key',
      passed: isValid.valid || isValid.is_canary,
      reason: isValid.reason,
      is_canary: isValid.is_canary
    });
  } else {
    logSection('Anthropic API Key');
    logResult('API Key', true, 'Not configured');
    results.push({ test: 'Anthropic API Key', passed: true });
  }

  // Stripe
  if (envVars.STRIPE_SECRET_KEY) {
    logSection('Stripe Secret Key');
    const isValid = validateStripeSecretKey(envVars.STRIPE_SECRET_KEY);
    logResult('Secret Key Format', isValid.valid && !isValid.is_canary, isValid.reason);

    if (!isValid.valid) {
      if (isValid.is_canary) {
        log('   🚨 Danger: This is a CANARY test key in LIVE mode!', colors.red);
      }
      if (isValid.suggests) {
        log('   💡 ' + isValid.suggests, colors.cyan);
      }
    }

    results.push({
      test: 'Stripe Secret Key',
      passed: isValid.valid && !isValid.is_canary,
      reason: isValid.valid ? 'Valid format' : 'Invalid',
      details: isValid.valid ? (isValid.isLive ? 'LIVE key' : 'TEST key') : 'Invalid/canary',
      isLive: isValid.isLive,
      is_canary: isValid.is_canary
    });
  } else {
    logSection('Stripe Secret Key');
    logResult('Secret Key', true, 'Not configured');
    results.push({ test: 'Stripe Secret Key', passed: true });
  }

  // Logfire
  if (envVars.LOGFIRE_TOKEN) {
    logSection('Logfire Token');
    const isValid = validateLogfireToken(envVars.LOGFIRE_TOKEN);
    logResult('Token Format', isValid.valid || isValid.is_canary, isValid.reason);

    if (!isValid.valid) {
      if (isValid.is_canary) {
        log('   🚨 This is a CANARY test token', colors.yellow);
      }
    }

    results.push({
      test: 'Logfire Token',
      passed: isValid.valid || isValid.is_canary,
      reason: isValid.reason,
      is_canary: isValid.is_canary
    });
  } else {
    logSection('Logfire Token');
    logResult('Token', true, 'Not configured');
    results.push({ test: 'Logfire Token', passed: true });
  }

  // Summary
  logSection('VALIDATION SUMMARY');

  const passedCount = results.filter(r => r.passed).length;
  const failedCount = results.filter(r => !r.passed).length;
  const canaryCount = results.filter(r => r.is_canary).length;

  results.forEach(result => {
    const icon = result.passed ? '✅' : '❌';
    const color = result.passed ? colors.green : colors.red;
    log(`${icon} ${result.test}`, color);
    if (result.is_canary || (!result.passed && result.reason)) {
      log(`   ${result.reason || 'Cannot be used'}`, colors.yellow);
    }
  });

  log('\n' + '─'.repeat(70));
  log(`  Tests Run: ${results.length}`, colors.blue);
  log(`  ✓ Passed: ${passedCount}`, colors.green);
  log(`  ✗ Failed: ${failedCount}`, colors.red);
  if (canaryCount > 0) {
    log(`  🚨 Canary detections: ${canaryCount}`, colors.yellow);

    log('\n📋 FINAL CONCLUSION', colors.cyan);
    log('  ' + '-'.repeat(66), colors.yellow);
    log(  'These credentials are CANARY values from .env.test, designed only for', colors.red);
    log(  'testing purposes. They should be REMOVED for production use.', colors.red);
    log(  'Replace with actual production credentials.', colors.green);
    log('  ' + '-'.repeat(66), colors.yellow);
  }

  if (!results.some(r => r.is_canary) && failedCount === 0 && passedCount === results.length) {
    log('\n✅ All credentials are properly formatted', colors.green);
    process.exit(0);
  } else if (failedCount > 0) {
    log('\n⚠️  Validation failed - credentials need attention', colors.red);
    process.exit(1);
  } else {
    // Only canary issues
    log('\n⚠️  Credentials are CANARY test values', colors.yellow);
    log('  Consider replacing with actual production credentials', colors.cyan);
    process.exit(1);
  }
}

