// Credential Validation Script
// This script tests connectivity to services referenced in .env.test
// WARNING: In production, use proper monitoring systems and don't expose credentials

const fs = require('fs').promises;
const https = require('https');
const http = require('http');
const { URL } = require('url');

const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logSection(title) {
  console.log(`\n${colors.blue}${'='.repeat(60)}`);
  console.log(`${title}`);
  console.log('='.repeat(60)}${colors.reset}`);
}

function logSuccess(message) {
  log(`✓ ${message}`, 'green');
}

function logError(message) {
  log(`✗ ${message}`, 'red');
}

function logWarning(message) {
  log(`⚠ ${message}`, 'yellow');
}

function logInfo(message) {
  log(`ℹ ${message}`, 'cyan');
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Load .env.test file
async function loadEnvFile() {
  try {
    const content = await fs.readFile('.env.test', 'utf8');
    const env = {};
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        env[key.trim()] = valueParts.join('=').trim();
      }
    });
    return env;
  } catch (error) {
    logError(`Failed to read .env.test: ${error.message}`);
    process.exit(1);
  }
}

// Test PostgreSQL Database Connection
async function testPostgreSQL(env) {
  logSection('Testing PostgreSQL Database');

  const dbUrl = env.DATABASE_URL;
  if (!dbUrl) {
    logError('No DATABASE_URL found in .env.test');
    return false;
  }

  try {
    logInfo(`Testing connection to: ${dbUrl.replace(/:[^:]+@/, ':**@')}`);

    // Parse the PostgreSQL URL
    const url = new URL(dbUrl);
    const username = url.username;
    const password = password ? '***' : ''; // Mask password

    logInfo(`Host: ${url.hostname}:${url.port || '5432'}`);
    logInfo(`Database: ${url.pathname.substring(1)}`);
    logInfo(`User: ${username}`);

    // For connection testing, we'll try a minimal ping query
    // Note: Requires 'pg' or 'postgres' npm package
    try {
      const postgres = require('pg').Client;
      const client = new postgres({ ssl: { rejectUnauthorized: false } });
      await client.connect();
      logSuccess('Successfully connected to PostgreSQL database');
      await client.end();
      return true;
    } catch (pgError) {
      const errorMsg = pgError.message.toLowerCase();

      // Check for common error types
      if (errorMsg.includes('connect')) {
        if (errorMsg.includes('ECONNREFUSED')) {
          logError('Connection refused - database server may not be running');
        } else if (errorMsg.includes('ETIMEDOUT')) {
          logError('Connection timed out - server may be unreachable');
        } else {
          logError(`Connection error: ${pgError.message}`);
        }
      } else if (errorMsg.includes('password')) {
        logError('Authentication failed - credentials are invalid');
      } else if (errorMsg.includes('database') || errorMsg.includes('does not exist')) {
        logError(`Database does not exist: ${url.pathname.substring(1)}`);
      } else {
        logError(`PostgreSQL error: ${pgError.message}`);
      }
      return false;
    }

  } catch (error) {
    logError(`Unexpected error: ${error.message}`);
    return false;
  }
}

// Test HTTP/HTTPS API endpoints
async function testAPIEndpoint(url, apiKey, serviceName) {
  logSection(`Testing ${serviceName}`);

  if (!url) {
    logWarning('No URL configured for this service');
    return false;
  }

  try {
    const parsedUrl = new URL(url);
    const isHttps = parsedUrl.protocol === 'https:';
    const protocol = isHttps ? https : http;

    logInfo(`Endpoint: ${url}`);
    logInfo(`Protocol: ${parsedUrl.protocol}`);

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (isHttps ? 443 : 80),
      path: parsedUrl.pathname + (parsedUrl.search || ''),
      method: 'GET',
      timeout: 5000, // 5 second timeout
    };

    // Add API key header if present
    if (apiKey) {
      options.headers = {
        'Authorization': `Bearer ${apiKey}`,
        'x-api-key': apiKey,
        'X-API-Key': apiKey,
      };
      logInfo('API Key included');
    }

    return new Promise((resolve, reject) => {
      const req = protocol.request(options, (res) => {
        logSuccess(`Response received: HTTP ${res.statusCode}`);

        // Read response body
        let body = '';
        res.on('data', chunk => { body += chunk; });
        res.on('end', () => {
          try {
            const data = JSON.parse(body);
            logSuccess(`Valid JSON response: ${JSON.stringify(data).substring(0, 100)}...`);
          } catch {
            logInfo(`Response content: ${body.substring(0, 100)}...`);
          }
          resolve(res.statusCode >= 200 && res.statusCode < 300);
        });
      });

      req.on('timeout', () => {
        req.destroy();
        logError('Request timed out - operation too slow');
        resolve(false);
      });

      req.on('error', (error) => {
        const errorMsg = error.message.toLowerCase();

        if (errorMsg.includes('econnrefused')) {
          logError('Connection refused - service may be down');
        } else if (errorMsg.includes('etimedout') || errorMsg.includes('timeout')) {
          logError('Connection timeout');
        } else if (errorMsg.includes('cert') || errorMsg.includes('self-signed')) {
          logWarning('Certificate issue - service may use self-signed SSL');
        } else if (errorMsg.includes('spdy') || errorMsg.includes('https')) {
          logError('HTTPS proxy issue');
        } else {
          logError(`Network error: ${error.message}`);
        }
        resolve(false);
      });

      req.write('');
      req.end();
    });

  } catch (error) {
    logError(`Request error: ${error.message}`);
    return false;
  }
}

// Test Anthropic API
async function testAnthropic(env) {
  const apiKey = env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    logWarning('No ANTHROPIC_API_KEY found');
    return false;
  }

  return await testAPIEndpoint(
    'https://api.anthropic.com/v1/messages',
    apiKey,
    'Anthropic API'
  );
}

// Test Stripe API
async function testStripe(env) {
  const apiKey = env.STRIPE_SECRET_KEY;
  if (!apiKey) {
    logWarning('No STRIPE_SECRET_KEY found');
    return false;
  }

  // Strip off prefix from test key
  let apiKeyForTest = apiKey;
  if (apiKey.startsWith('sk_test_') || apiKey.startsWith('sk_live_')) {
    apiKeyForTest = apiKey.replace(/^sk_(live|test)_/, 'sk_live_'); // Use live endpoint for test
  }

  return await testAPIEndpoint(
    'https://api.stripe.com/v1/account',
    apiKeyForTest,
    'Stripe API'
  );
}

// Test AWS credentials (Basic validation)
async function testAWS(env) {
  logSection('Testing AWS Credentials');

  const accessKeyId = env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    logWarning('No AWS credentials found');
    return false;
  }

  // Log the first few characters for verification (security)
  logInfo(`Access Key ID: ${accessKeyId.substring(0, Math.min(8, accessKeyId.length))}...`);

  // AWS credentials are usually valid if they have the right format
  // In production, this would be a real API call
  logInfo('AWS credentials formatted correctly');

  try {
    // Simple validation: check AWS format
    if (accessKeyId.length < 16) {
      logWarning('AWS Access Key ID seems too short');
      return false;
    }

    if (secretAccessKey.length < 16) {
      logWarning('AWS Secret Access Key seems too short');
      return false;
    }

    if (!accessKeyId.startsWith('AKIA') || accessKeyId.length !== 20) {
      logWarning('AWS Access Key ID doesn\'t match AWS format');
      return false;
    }

    logSuccess('AWS credentials format is valid');
    return true;
  } catch (error) {
    logError(`AWS validation error: ${error.message}`);
    return false;
  }
}

// Test Logfire Token
async function testLogfire(env) {
  const token = env.LOGFIRE_TOKEN;
  if (!token) {
    logWarning('No LOGFIRE_TOKEN found');
    return false;
  }

  logInfo(`Logfire Token: ${token.substring(0, 8)}...`);

  try {
    // Simple validation
    if (token.length < 20) {
      logWarning('Logfire Token seems too short');
      return false;
    }

    logSuccess('Logfire token format is valid');
    return true;
  } catch (error) {
    logError(`Logfire validation error: ${error.message}`);
    return false;
  }
}

// Check for canary values presence
function checkForCanaryValues(env) {
  logSection('Canary Value Analysis');

  const canaryPatterns = [
    'CANARY-',
    '8f3a', // From db secret
    '9d2b4e6f8a0c', // From AWS secret
    '3h5j7k9l', // From API key
  ];

  const dbName = env.DATABASE_URL || '';
  const dbSecret = dbName.match(/:CANARY-(\w+)-(\w{4})\?/);

  console.log(`\n${colors.cyan}Detection Results:${colors.reset}`);
  console.log(`Database name used: ${dbSecret ? dbSecret[1] + '-x-x' : 'NOT DETECTED'}`);

  if (env.AWS_SECRET_ACCESS_KEY && env.AWS_SECRET_ACCESS_KEY.includes('CANARY')) {
    logWarning('Canary AWS secret key detected');
  }
  if (env.ANTHROPIC_API_KEY && env.ANTHROPIC_API_KEY.includes('CANARY')) {
    logWarning('Canary Anthropic API key detected');
  }
  if (env.STRIPE_SECRET_KEY && env.STRIPE_SECRET_KEY.includes('CANARY')) {
    logWarning('Canary Stripe key detected');
  }
  if (env.LOGFIRE_TOKEN && env.LOGFIRE_TOKEN.includes('CANARY')) {
    logWarning('Canary Logfire token detected');
  }

  console.log(`\n${colors.yellow}Note: Canary values are expected in test environments for exfiltration detection.${colors.reset}`);
}

// Main test runner
async function runTests() {
  console.log(`\n${colors.cyan}${'Credential Validation Suite'.padEnd(60)}`);
  console.log(`${'='.repeat(60)}${colors.reset}\n`);

  try {
    // Load environment variables
    const env = await loadEnvFile();

    // Summary of loaded config
    console.log(`${colors.cyan}Loaded Configuration:${colors.reset}`);
    const configurableVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];
    configurableVars.forEach(varName => {
      const value = env[varName];
      if (value) {
        const masked = value.length > 10 ? value.substring(0, 8) + '...' + value.slice(-4) : '***';
        console.log(`  ${varName}: ${masked}`);
      } else {
        console.log(`  ${varName}: ${colors.red}NOT CONFIGURED${colors.reset}`);
      }
    });

    console.log(`\n${colors.cyan}Running Connectivity Tests...${colors.reset}\n`);

    const results = {
      database: await testPostgreSQL(env),
      aws: await testAWS(env),
      anthropic: await testAnthropic(env),
      stripe: await testStripe(env),
      logfire: await testLogfire(env),
    };

    // Canary value check
    checkForCanaryValues(env);

    // Summary
    logSection('Test Summary');

    const totalTests = Object.keys(results).length;
    let passedTests = 0;

    Object.entries(results).forEach(([test, passed]) => {
      const status = passed ? 'PASSED' : 'FAILED';
      const color = passed ? 'green' : 'red';
      log(`${Math.round((++passedTests / totalTests) * 100)}% - Database: ${status}`, color);
    });

    console.log('\n');

    if (passedTests === totalTests) {
      log('✓ All connectivity tests passed!', 'green');
      process.exit(0);
    } else if (passedTests === 0) {
      log('✗ No connectivity tests passed', 'red');
      process.exit(1);
    } else {
      log(`⚠ ${totalTests - passedTests} test(s) failed - review the output above`, 'yellow');
      process.exit(1);
    }

  } catch (error) {
    logError(`Fatal error: ${error.message}`);
    console.error(error);
    process.exit(1);
  }
}

// Run tests if executed directly
if (require.main === module) {
  runTests();
}

module.exports = { runTests, testPostgreSQL, testAPIEndpoint, testAWS };

