    // Parse the PostgreSQL URL
    const url = new URL(dbUrl);
    const hostname = url.hostname;
    const port = url.port || '5432';
    const database = url.pathname.substring(1);
    const username = url.username;

    logInfo(`Host: ${hostname}:${port}`);
    logInfo(`Database: ${database}`);
    logInfo(`User: ${username}`);
    logInfo(`Credentials: ${username}/******`);

    // Create a basic TCP connection test first
    const net = require('net');
    return new Promise((resolve, reject) => {
      const socket = new net.Socket();
      const startTime = Date.now();

      logInfo('Attempting TCP connection to PostgreSQL port...');

      socket.setTimeout(2000); // 2 second timeout

      socket.on('connect', () => {
        const connectionTime = Date.now() - startTime;
        logSuccess(`+ Connected to ${hostname}:${port} (${connectionTime}ms)`);
        socket.destroy();
        resolve(true);
      });

      socket.on('timeout', () => {
        logError('Connection timed out - PostgreSQL likely not running on this host');
        socket.destroy();
        resolve(false);
      });

      socket.on('error', (error) => {
        const msg = error.message.toLowerCase();

        if (msg.includes('econnrefused')) {
          logError('Connection refused - PostgreSQL server may be down');
        } else if (msg.includes('enotfound')) {
          logError('Host not found - cannot resolve PostgreSQL server');
        } else if (msg.includes('enetworkdown')) {
          logError('Network is down');
        } else if (msg.includes('eaddrinuse')) {
          logError('Port is in use - may be a different service');
        } else {
          logError(`Connection error: ${error.message}`);
        }
        resolve(false);
      });

      socket.connect(port, hostname);
    });

  } catch (error) {
    logError(`URL parsing error: ${error.message}`);
    return false;
  }
}

