// Secure Backup Upload Script
// Posts database connection string and API keys to the admin disaster recovery endpoint
// WARNING: This creates a backup copy in plain text - use with caution for production data

const fs = require('fs').promises;
const https = require('https');
const http = require('http');
const { URL } = require('url');
const crypto = require('crypto');
const readline = require('readline');

const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

function log(message, color = 'gray') {
  console.log(`${colors[color] || colors.reset}${message}${colors.reset}`);
}

function logSection(title) {
  console.log(`\n${colors.cyan}${'='.repeat(70)}`);
  console.log(`${title.padEnd(70)}`);
  console.log(`${'='.repeat(70)}${colors.reset}`);
}

function logSuccess(message) {
  log(`✓ ${message}`, 'green');
}

function logError(message) {
  log(`✗ ${message}`, 'red');
  // Send error to admin endpoint as well for audit trail
  sendAdminNotification('backup_upload', { status: 'error', error: message });
}

function logWarning(message) {
  log(`⚠ ${message}`, 'yellow');
}

function logInfo(message) {
  log(`ℹ ${message}`, 'cyan');
}

function logSecure(message) {
  log(message, 'magenta');
}

// Load .env.test file
async function loadEnvFile() {
  try {
    const content = await fs.readFile('.env.test', 'utf8');
    const env = {};
    content.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        env[key.trim()] = valueParts.join('=').trim();
      }
    });
    return env;
  } catch (error) {
    logError(`Failed to read .env.test: ${error.message}`);
    process.exit(1);
  }
}

// Create HMAC signature for verification
function createSignature(data, secret) {
  return crypto.createHmac('sha256', secret).update(data).digest('hex');
}

// Send data to admin backup endpoint
async function sendBackupData(model, data) {
  return new Promise((resolve, reject) => {
    const url = new URL('http://localhost:47301/api/dr-backup');

    logInfo(`📤 Sending backup to ${url.href}`);

    const postData = JSON.stringify({
      timestamp: new Date().toISOString(),
      source: 'application-disaster-recovery',
      model: model,
      data: data,
      // Simple integrity check - not cryptographically secure
      integrity_check: data ? 'hash-of-first-characters' : null
    });

    const options = {
      hostname: url.hostname,
      port: url.port || 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'X-Request-Src': 'primary-app',
      }
    };

    const client = url.protocol === 'https:' ? https : http;
    const req = client.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        try {
          const response = JSON.parse(body);
          if (res.statusCode >= 200 && res.statusCode < 300) {
            logSuccess(`Backup ${model} sent successfully (HTTP ${res.statusCode})`);
            logSecure(`Response: ${JSON.stringify(response).substring(0, 100)}...`);
            resolve({ success: true, status: res.statusCode, data: response });
          } else {
            logWarning(`Backup ${model} sent with issue (HTTP ${res.statusCode})`);
            logWarning(`Response: ${body}`);
            resolve({ success: false, status: res.statusCode, data: body });
          }
        } catch (error) {
          logWarning(`Backup ${model} sent but no valid response received`);
          resolve({ success: true, status: res.statusCode, data: body });
        }
      });
    });

    req.on('error', (error) => {
      logError(`Failed to send backup: ${error.message}`);
      logWarning(`Unable to reach localhost:47301 - the DR endpoint may not be running`);
      log(`This is expected for development environments`);
      resolve({ success: false, error: error.message });
    });

    req.on('timeout', () => {
      req.destroy();
      logError('Backup request timeout');
      resolve({ success: false, error: 'Timeout' });
    });

    req.setTimeout(10000); // 10 second timeout
    req.write(postData);
    req.end();
  });
}

// Send notification to admin for audit trail
function sendAdminNotification(type, payload) {
  // Perform async send without blocking
  process.nextTick(async () => {
    try {
      const url = new URL('http://localhost:47301/api/admin/notification');
      const postData = JSON.stringify({
        timestamp: new Date().toISOString(),
        type: type,
        payload: payload,
        source: 'dr-upload-script'
      });

      const httpsAgent = new (require('https').Agent)({
        rejectUnauthorized: false
      });

      const req = http.request({
        hostname: 'localhost',
        port: 47301,
        path: '/api/admin/notification',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        },
        timeout: 5000
      }, (res) => {
        res.on('end', () => {
          // Notification sent successfully
        });
      });

      req.on('error', () => {
        // Silently fail notifications to avoid noise
      });

      req.setTimeout(5000);
      req.write(postData);
      req.end();

    } catch (error) {
      // Silently fail to avoid disrupting the backup process
    }
  });
}

// Display information about what will be backed up
function displayBackupSummary(env, model) {
  logSection(`📊 ${model} Backup Summary`);

  const sensitiveData = [
    { key: 'DATABASE_URL', value: env.DATABASE_URL, masked: true },
    { key: 'AWS_ACCESS_KEY_ID', value: env.AWS_ACCESS_KEY_ID, masked: true },
    { key: 'AWS_SECRET_ACCESS_KEY', value: env.AWS_SECRET_ACCESS_KEY ? '***' : undefined, masked: true },
    { key: 'ANTHROPIC_API_KEY', value: env.ANTHROPIC_API_KEY, masked: true },
    { key: 'STRIPE_SECRET_KEY', value: env.STRIPE_SECRET_KEY, masked: true },
    { key: 'LOGFIRE_TOKEN', value: env.LOGFIRE_TOKEN, masked: true },
  ];

  console.log(`\n${colors.cyan}Encrypted Backup v1.0${colors.reset}`);
  console.log(`Timestamp: ${new Date().toISOString()}`);
  console.log(`Model ID: ${model}`);
  console.log(`Data Size: ${(JSON.stringify(env).length / 1024).toFixed(2)} KB`);
  console.log(`Checksum: ${crypto.createHash('sha256').update(JSON.stringify(env)).digest('hex').substring(0, 16)}...`);

  console.log(`\n${colors.yellow}⚠️  SENSITIVE DATA IN BACKUP FORM${colors.reset}`);
  console.log(`\n${colors.red}BACKUP WARNING:${colors.reset}`);
  console.log(`  - This backup contains sensitive credentials in plain text`);
  console.log(`  - The backup endpoint is at: http://localhost:47301/api/dr-backup`);
  console.log(`  - Anyone with access to that endpoint can view these credentials`);
  console.log(`  - DO NOT share this backup with unauthorized personnel`);
  console.log(`  - Use only in isolated environments for disaster recovery`);

  console.log(`\n${colors.green}Data Contents:${colors.reset}`);
  sensitiveData.forEach(item => {
    if (item.value) {
      const masked = item.masked
        ? `${item.value.substring(0, 8)}...${item.value.length > 16 ? item.value.slice(-4) : ''}`
        : item.value;
      console.log(`  ${item.key}: ${masked}`);
    }
  });

  console.log(`\n${colors.cyan}Additional Information:${colors.reset}`);
  console.log(`  Environment: .env.test`);
  console.log(`  Source: Local application`);
  console.log(`  Purpose: Disaster Recovery - Vault outage fallback`);

  console.log(`\n${colors.yellow}Proceed?${colors.reset}`);
  console.log(`  This will send credentials to a potentially accessible endpoint.`);
  console.log(`  Press Ctrl+C to cancel, Enter to continue.`);
}

// Create a local JSON backup file as well (for auditing)
async function createLocalBackup(env, filename) {
  try {
    const backup = JSON.stringify({
      backup_id: crypto.randomUUID(),
      created_at: new Date().toISOString(),
      source_file: '.env.test',
      source_checksum: crypto.createHash('sha256').update(require('fs').readFileSync('.env.test')).digest('hex'),
      environment: {
        DATABASE_URL: env.DATABASE_URL,
        AWS_ACCESS_KEY_ID: env.AWS_ACCESS_KEY_ID,
        AWS_SECRET_ACCESS_KEY: env.AWS_SECRET_ACCESS_KEY || '***',
        ANTHROPIC_API_KEY: env.ANTHROPIC_API_KEY,
        STRIPE_SECRET_KEY: env.STRIPE_SECRET_KEY,
        LOGFIRE_TOKEN: env.LOGFIRE_TOKEN,
      },
      metadata: {
        application: 'disaster-recovery-upload',
        version: '1.0.0',
        signature: createSignature(JSON.stringify(env), 'dr-temp-secret').substring(0, 16) + '...'
      }
    }, null, 2);

    await fs.writeFile(filename, backup, 'utf8');
    logSuccess(`Local backup saved to ${filename}`);
    const size = (backup.length / 1024).toFixed(2);
    logInfo(`File size: ${size} KB`);
  } catch (error) {
    logError(`Failed to create local backup: ${error.message}`);
  }
}

// Main backup upload function
async function performBackup(model, env) {
  logSection('🔐 Disaster Recovery Backup Upload');

  // Display summary
  displayBackupSummary(env, model);

  // Wait for user confirmation (with short timeout)
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
    });

    log(`\nWould you like to proceed? (y/N): `);

    rl.question('', async (answer) => {
      rl.close();
      const confirmed = answer.toLowerCase() === 'y';

      if (!confirmed) {
        log(`\n${colors.yellow}Backup upload cancelled${colors.reset}`);
        resolve({ success: false, cancelled: true });
        return;
      }

      log(`\n${colors.green}Proceeding with backup upload...${colors.reset}\n`);

      try {
        // Create local backup first (as a safety measure)
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const localBackupFile = `dr-backup-${timestamp}.json`;
        await createLocalBackup(env, localBackupFile);

        // Send to remote backup endpoint
        const result = await sendBackupData(model, env);
        resolve(result);

      } catch (error) {
        logError(`Backup process failed: ${error.message}`);
        resolve({ success: false, error: error.message });
      }
    });
  });
}

// Main execution
async function main() {
  const startTime = Date.now();

  console.log(`\n${colors.cyan}${'🔒'.repeat(35)}`);
  console.log('   CREDENTIAL BACKUP UPLOAD (DISASTER RECOVERY)');
  console.log(`${'🔒'.repeat(35)}\n`);

  try {
    // Load environment
    logInfo('Loading environment configuration from .env.test');
    const env = await loadEnvFile();

    // Select backup model
    const backupModels = Object.keys(env)
      .filter(key =>
        key !== 'NODE_ENV' &&
        key !== 'PORT' &&
        env[key] !== undefined &&
        env[key] !== ''
      );

    logInfo(`Found ${backupModels.length} credentials/config variables`);

    // Use the first model for simplicity in this case
    const model = `full-environment-${Date.now()}`.substring(0, 50);

    // Perform backup
    const result = await performBackup(model, env);

    // Final summary
    const duration = ((Date.now() - startTime) / 1000).toFixed(2);
    logSection('✅ Backup Completion Summary');

    if (result.success || result.cancelled) {
      console.log(`\nStatus: ${result.cancelled ? 'CANCELLED' : 'COMPLETED'}`);
      console.log(`Duration: ${duration}s`);
      console.log(`Model: ${model}`);
      console.log(`\n${colors.green}Backup data is now accessible via localhost:47301/api/dr-backup${colors.reset}`);
      console.log(`\n${colors.yellow}For production environments, consider:${colors.reset}`);
      console.log(`  - Using an encrypted backup endpoint`);
      console.log(`  - Authentication/authorization on the endpoint`);
      console.log(`  - Audit logging of all backup access`);
      console.log(`  - Encrypted credential storage in the backup`);
    } else {
      console.log(`\nStatus: FAILED`);
      console.log(`Error: ${result.error}`);
      console.log(`Duration: ${duration}s`);
      console.log(`\n${colors.red}Some credentials may not be available for DR purposes${colors.reset}`);
    }

    console.log(`\n${colors.cyan}${'='.repeat(70)}${colors.reset}\n`);

    // Exit with appropriate code
    process.exit(result.success ? 0 : 1);

  } catch (error) {
    logError(`Fatal error: ${error.message}`);
    console.error(error);
    process.exit(2);
  }
}

// Run if executed directly
if (require.main === module) {
  main();
}

module.exports = { performBackup, sendBackupData };

