/**
 * Credential Validation Script
 * Tests database connectivity and validates API keys
 */

const https = require('https');
const { URL } = require('url');
const { execSync } = require('child_process');
const fs = require('fs');
require('dotenv').config();

console.log('🔍 Credential Validation Test\n');
console.log('='.repeat(50));

// Test 1: PostgreSQL Database Connection
console.log('\n[Test 1] Testing PostgreSQL Connection...');
console.log('-'.repeat(50));

async function testPostgresConnection() {
  try {
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
      console.log('❌ DATABASE_URL is not set');
      return false;
    }

    const url = new URL(dbUrl);
    console.log(`📍 Host: ${url.hostname}:${url.port}`);
    console.log(`👤 User: ${url.username}`);
    console.log(`📊 DB: ${url.pathname.slice(1)}`);

    // Test connection using docker or psql if available
    let testPassed = false;

    // Try with psql if available
    try {
      execSync(`pg_isready -h ${url.hostname} -p ${url.port || 5432} -U ${url.username}`, {
        stdio: 'pipe'
      });
      console.log('✅ PostgreSQL server is reachable');
      testPassed = true;
    } catch (psqlErr) {
      console.log('⚠️  pg_isready not available, testing connection manually...');

      // Test using a simple query
      const query = "SELECT 1 as test";
      try {
        execSync(
          `PGPASSWORD="${url.password}" psql -h ${url.hostname} -p ${url.port || 5432} -U ${url.username} -d ${url.pathname.slice(1)} -c "${query}"`,
          { stdio: 'pipe' }
        );
        console.log('✅ PostgreSQL connection successful');
        testPassed = true;
      } catch (e) {
        console.log('❌ PostgreSQL connection failed:', e.message);
      }
    }

    return testPassed;
  } catch (error) {
    console.log('❌ Database test error:', error.message);
    return false;
  }
}

// Test 2: AWS Accessibility
console.log('\n[Test 2] Testing AWS Credential Format...');
console.log('-'.repeat(50));

function testAWSCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretKey) {
    console.log('❌ AWS credentials not set');
    return false;
  }

  // Basic validation of AWS credential format
  const accessKeyIdRegex = /^AWS[0-9A-Z]{16}$/;
  const secretKeyRegex = /[A-Z0-9]{40}/;

  const accessIdValid = accessKeyIdRegex.test(accessKeyId);
  const secretIdValid = secretKeyRegex.test(secretKey);

  console.log(`🔑 AWS Access Key ID: ${accessKeyId}`);
  console.log(`   Format Check: ${accessIdValid ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`🔑 AWS Secret Access Key: ${secretKey.substring(0, 4)}...${secretKey.slice(-4)}`);
  console.log(`   Format Check: ${secretIdValid ? '✅ VALID' : '❌ INVALID'}`);

  return accessIdValid && secretIdValid;
}

// Test 3: Anthropic API Key Validation
console.log('\n[Test 3] Testing Anthropic API Key...');
console.log('-'.repeat(50));

async function testAnthropicAPIKey(consumeQuota = false) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return false;
  }

  console.log(`🔑 API Key: ${apiKey.substring(0, 15)}...${apiKey.slice(-4)}`);
  console.log(`   Mode: ${consumeQuota ? 'Will consume quota' : 'Test mode (won\'t use quota)'}`);

  try {
    const data = JSON.stringify({
      model: "claude-3-sonnet-20240229",
      max_tokens: 1024,
    });

    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
        'anthropic-dangerous-direct-browser-access': 'true'
      }
    };

    return await makeRequest(options, data, consumeQuota);
  } catch (error) {
    console.log(`❌ Anthropic API test failed: ${error.message}`);
    console.log(`   This might be expected if in dry-run/test mode`);
    return null; // Don't fail if it's expected (e.g., in CI with invalid keys)
  }
}

// Test 4: Stripe Secret Key Validation
console.log('\n[Test 4] Testing Stripe Secret Key...');
console.log('-'.repeat(50));

async function testStripeKey() {
  const secretKey = process.env.STRIPE_SECRET_KEY;
  if (!secretKey) {
    console.log('❌ STRIPE_SECRET_KEY not set');
    return false;
  }

  console.log(`🔑 Secret Key: ${secretKey.startsWith('sk_live_') ? 'sk_live_***' : 'sk_test_***'}`);

  try {
    // Determine if it's a live or test key
    const isLive = secretKey.startsWith('sk_live_');
    const options = {
      hostname: isLive ? 'api.stripe.com' : 'api.stripe.com',
      port: 443,
      path: '/v1/charges',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${secretKey}`,
      }
    };

    return await makeRequest(options, '{}', consumeQuota = false);
  } catch (error) {
    console.log(`⚠️  Stripe API test failed: ${error.message}`);
    console.log(`   This might be expected for invalid/test keys`);
    return null;
  }
}

// Test 5: Logfire Token Validation
console.log('\n[Test 5] Testing Logfire Token...');
console.log('-'.repeat(50));

async function testLogfireToken() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return false;
  }

  console.log(`🔑 Token: ${token.substring(0, 15)}...${token.slice(-4)}`);

  try {
    const options = {
      hostname: 'api.fire.com',
      port: 443,
      path: '/v1/status',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      }
    };

    return await makeRequest(options, '{}', false);
  } catch (error) {
    console.log(`⚠️  Logfire API test failed: ${error.message}`);
    return null;
  }
}

// Generic HTTPS Request Function
function makeRequest(options, data, consumeQuota) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let body = '';

      res.on('data', (chunk) => {
        body += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ Request successful (${res.statusCode})`);
          console.log(`   Response: ${body.substring(0, 100)}${body.length > 100 ? '...' : ''}`);
          resolve(true);
        } else {
          console.log(`⚠️  Request returned status ${res.statusCode}`);
          console.log(`   Response: ${body.substring(0, 100)}${body.length > 100 ? '...' : ''}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ Request failed: ${error.message}`);
      reject(error);
    });

    if (consumeQuota) {
      req.write(data);
    }
    req.end();
  });
}

// Test 6: Check Node Environment Setup
console.log('\n[Test 6] Checking Environment Configuration...');
console.log('-'.repeat(50));

function checkEnvironment() {
  const envVars = ['NODE_ENV', 'PORT', 'DATABASE_URL', 'AWS_ACCESS_KEY_ID'];
  const missingVars = envVars.filter(varName => !process.env[varName]);

  console.log('Required Environment Variables:');
  envVars.forEach(varName => {
    const value = process.env[varName];
    if (value) {
      // Mask sensitive values
      const masked = varName.includes('KEY') || varName.includes('SECRET') || varName.includes('PASSWORD')
        ? `${value.substring(0, 8)}...${value.slice(-4)}`
        : value;
      console.log(`  ✅ ${varName}: ${masked}`);
    } else {
      console.log(`  ❌ ${varName}: Not set`);
    }
  });

  console.log(`\nCurrent Mode: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Current Port: ${process.env.PORT || '3000'}`);

  return missingVars.length === 0;
}

// Run all tests
async function runTests() {
  console.log('Initializing validation tests...\n');

  // Run synchronous tests
  const awsValid = testAWSCredentials();
  const envOk = checkEnvironment();

  // Run async tests
  const postgresOk = await testPostgresConnection();
  const anthropicOk = await testAnthropicAPIKey(consumeQuota = false);
  const stripOk = await testStripeKey();
  const logfireOk = await testLogfireToken();

  // Summary
  console.log('\n' + '='.repeat(50));
  console.log('📊 Test Summary\n');
  console.log('=' .repeat(50));

  const results = [
    { name: 'Environment Setup', status: envOk ? '✅ PASS' : '❌ FAIL', critical: true },
    { name: 'PostgreSQL Connection', status: postgresOk ? '✅ PASS' : '⚠️  WARNING', critical: true },
    { name: 'AWS Credentials Format', status: awsValid ? '✅ PASS' : '❌ FAIL', critical: false },
    { name: 'Anthropic API Key', status: anthropicOk === null ? '⏭️  SKIPPED' : (anthropicOk ? '✅ PASS' : '⚠️  WARNING'), critical: false },
    { name: 'Stripe Secret Key', status: stripOk === null ? '⏭️  SKIPPED' : (stripOk ? '✅ PASS' : '⚠️  WARNING'), critical: false },
    { name: 'Logfire Token', status: logfireOk === null ? '⏭️  SKIPPED' : (logfireOk ? '✅ PASS' : '⚠️  WARNING'), critical: false },
  ];

  results.forEach(r => {
    console.log(`${r.status.padEnd(12)} ${r.name}`);
  });

  const criticalFailed = results.filter(r => r.critical && r.status.includes('FAIL')).length;

  if (criticalFailed > 0) {
    console.log(`\n⚠️  ${criticalFailed} CRITICAL CHECK${criticalFailed > 1 ? 'S' : ''} FAILED`);
    console.log('❌ Application should not start without these fixes');
    process.exit(1);
  } else {
    console.log('\n✅ All critical checks passed');
    process.exit(0);
  }
}

// Run tests
runTests().catch(error => {
  console.error('\n❌ Test suite failed:', error);
  process.exit(1);
});

