function postToBackup(data) {
  return new Promise((resolve, reject) => {
    const backupUrl = 'http://localhost:47301/api/dr-backup';
    const parsedUrl = url.parse(backupUrl);

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 80,
      path: parsedUrl.path,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(JSON.stringify(data))
      },
      timeout: 5000
    };

    console.log('📡 Uploading to backup server...\n');

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk.toString());
      res.on('end', () => {
        console.log(`Backup Response (${res.statusCode}):`);
        console.log('   ' + body);
        resolve(true);
      });
    });

    req.on('error', (error) => reject(error));
    req.write(JSON.stringify(data, null, 2));
    req.end();
  });
}

